import {
  Component, signal, HostListener,
  ElementRef, ChangeDetectionStrategy, inject,
  ViewEncapsulation, OnInit, OnDestroy, Renderer2,
  input,
  output
} from '@angular/core';
import { DOCUMENT } from '@angular/common';
import {
  resolveTableActionIcon,
  resolveTableActionTone,
  TableActionName,
} from '../../atoms/table-action/table-action';

let nextActionGroupId = 0;

/**
 * Representa una acción individual en el grupo
 */
export interface ActionItem {
  /** Identificador único de la acción */
  id: string;
  /** Clase de icono FontAwesome, e.g. 'fa-solid fa-eye' */
  icon?: string;
  /** Nombre semantico del atomo TableAction o string custom. */
  action?: TableActionName | string;
  /** Texto del tooltip y label en el menú */
  label: string;
  /** Variante de color */
  variant?: 'default' | 'primary' | 'secondary' | 'danger' | 'warning' | 'success' | 'info' | 'tertiary';
  /** Fuerza la acción al menú, aunque todavía exista espacio para acciones directas. */
  isMenuOnly?: boolean;
  /** Si la acción está deshabilitada */
  disabled?: boolean;
  /** Presenta carga y bloquea temporalmente la accion. */
  loading?: boolean;
}

type MenuPosition = 'auto' | 'top' | 'bottom' | 'left' | 'right';

/**
 * ActionGroupComponent - Grupo de acciones con overflow inteligente
 * 
 * Características:
 * - Muestra los primeros N botones directamente (default 3)
 * - Oculta el resto en un menú desplegable identificado por un caret
 * - Posicionamiento inteligente que evita solapamiento con bordes de pantalla
 * - Soporte para modo compacto (todas las acciones en menú)
 * 
 * @example
 * ```html
 * <app-action-group
 *   [actions]="[
 *     { id: 'view', icon: 'fa-solid fa-eye', label: 'Ver' },
 *     { id: 'edit', icon: 'fa-solid fa-pen', label: 'Editar', variant: 'primary' },
 *     { id: 'delete', icon: 'fa-solid fa-trash', label: 'Eliminar', variant: 'danger' }
 *   ]"
 *   [maxVisible]="3"
 *   (actionClick)="onAction($event)">
 * </app-action-group>
 * ```
 */
@Component({
  selector: 'app-action-group, prest-action-group',
  standalone: true,
  imports: [],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  template: `
    <div class="action-group" [class.compact]="compact()" [class]="'action-group--' + size()">
      <!-- Visible Actions -->
      @if (!compact()) {
        @for (action of visibleActions(); track action.id) {
          <button
            type="button"
            class="action-btn"
            [class]="'action-btn--' + actionVariant(action)"
            [class.disabled]="action.disabled || action.loading"
            [title]="action.label"
            [attr.aria-label]="action.label"
            [disabled]="action.disabled || action.loading"
            [attr.aria-busy]="action.loading || null"
            (click)="onActionClick(action, $event)"
          >
            @if (action.loading) {
              <span class="action-spinner" aria-hidden="true"></span>
            } @else {
              <i [class]="actionIconClass(action)" aria-hidden="true"></i>
            }
          </button>
        }
      }

      <!-- More Button (if there are overflow actions or compact mode) -->
      @if ((hasOverflow() || compact()) && menuActions().length > 0) {
        <div class="more-wrapper" [class.open]="isOpen()">
          <button
            type="button"
            class="action-btn action-btn--more"
            [title]="compact() ? 'Acciones' : 'Más acciones'"
            [attr.aria-label]="compact() ? 'Acciones' : 'Más acciones'"
            (click)="toggleMenu($event)"
            [attr.aria-expanded]="isOpen()"
            [attr.aria-controls]="menuId"
            aria-haspopup="menu"
            (keydown.arrowdown)="openMenuFromKeyboard($event)"
          >
            <i class="fa-solid fa-caret-down action-more-icon" aria-hidden="true"></i>
          </button>
          <!-- Menu se crea dinámicamente en document.body -->
        </div>
      }
    </div>
  `,
  styleUrl: './action-group.component.css'
})
export class ActionGroupComponent implements OnInit, OnDestroy {
  /** Lista de acciones a mostrar */
  readonly actions = input<ActionItem[]>([]);

  /** Número máximo de acciones visibles antes de overflow */
  readonly maxVisible = input(3);

  /** Dirección del menú desplegable: vertical (con labels) u horizontal (solo iconos) */
  readonly direction = input<'vertical' | 'horizontal'>('vertical');

  /** Posición preferida del menú (auto = calcula automáticamente) */
  readonly menuPosition = input<MenuPosition>('auto');

  /** Modo compacto: oculta todas las acciones en el menú */
  readonly compact = input(false);

  /** Tamaño de los botones: sm (2var(--space-2)), md (3var(--space-2)), lg (44px) */
  readonly size = input<'sm' | 'md' | 'lg'>('md');

  /** Emitido cuando se hace clic en una acción */
  readonly actionClick = output<string>();

  /** Estado del menú */
  isOpen = signal(false);

  /** Relaciona el disparador con el menu portal para lectores de pantalla. */
  readonly menuId = `action-group-menu-${nextActionGroupId++}`;


  private readonly elementRef = inject(ElementRef);
  private readonly renderer = inject(Renderer2);
  private readonly document = inject(DOCUMENT);

  // Elemento del menú en el body
  private menuElement: HTMLElement | null = null;
  private menuListenerCleanups: (() => void)[] = [];

  // Bound listeners para poder removerlos
  private scrollListener = () => this.onScrollOrResize();
  private resizeListener = () => this.onScrollOrResize();

  ngOnInit(): void {
    if (typeof window !== 'undefined') {
      window.addEventListener('scroll', this.scrollListener, true);
      window.addEventListener('resize', this.resizeListener);
    }
  }

  ngOnDestroy(): void {
    if (typeof window !== 'undefined') {
      window.removeEventListener('scroll', this.scrollListener, true);
      window.removeEventListener('resize', this.resizeListener);
    }
    // Limpiar menú si existe
    this.destroyMenu();
  }

  /** Destruir menú del body */
  private destroyMenu(): void {
    this.menuListenerCleanups.forEach((cleanup) => cleanup());
    this.menuListenerCleanups = [];
    if (this.menuElement) {
      this.renderer.removeChild(this.document.body, this.menuElement);
      this.menuElement = null;
    }
  }

  /** Recalcular posición en scroll/resize */
  private onScrollOrResize(): void {
    if (this.isOpen()) {
      this.updatePosition();
    }
  }

  /** Acciones visibles (primeras N) */
  visibleActions(): ActionItem[] {
    if (this.compact()) return [];
    return this.directActions().slice(0, this.visibleLimit());
  }

  /**
   * Acciones en el menú overflow.
   *
   * Se recorre el arreglo original para conservar el orden relativo de las
   * acciones forzadas al menú y de las que exceden el límite directo.
   */
  menuActions(): ActionItem[] {
    if (this.compact()) return this.actions();
    let directasMostradas = 0;
    const limite = this.visibleLimit();

    return this.actions().filter((action) => {
      if (action.isMenuOnly) return true;
      if (directasMostradas < limite) {
        directasMostradas += 1;
        return false;
      }
      return true;
    });
  }

  /** ¿Hay acciones en overflow? */
  hasOverflow(): boolean {
    return this.menuActions().length > 0;
  }

  private directActions(): ActionItem[] {
    return this.actions().filter((action) => !action.isMenuOnly);
  }

  actionIconClass(action: ActionItem): string {
    return resolveTableActionIcon((action.action ?? 'custom') as TableActionName, action.icon);
  }

  actionVariant(action: ActionItem): string {
    return action.variant ?? resolveTableActionTone((action.action ?? 'custom') as TableActionName);
  }

  private visibleLimit(): number {
    const maxVisible = this.maxVisible();
    return Number.isFinite(maxVisible) ? Math.max(0, Math.floor(maxVisible)) : 3;
  }

  /** Toggle del menú */
  toggleMenu(event: Event): void {
    event.stopPropagation();
    event.preventDefault();

    const wasOpen = this.isOpen();

    if (wasOpen) {
      // Cerrar menú
      this.closeMenu(true);
    } else {
      // Abrir menú
      this.openMenu();
    }
  }

  openMenuFromKeyboard(event: Event): void {
    event.preventDefault();
    event.stopPropagation();
    if (!this.isOpen()) {
      this.openMenu();
    }
  }

  private openMenu(): void {
    if (this.menuActions().length === 0) return;
    this.isOpen.set(true);
    this.createMenuInBody();
  }

  private closeMenu(restoreFocus = false): void {
    this.isOpen.set(false);
    this.destroyMenu();
    if (restoreFocus) {
      (this.elementRef.nativeElement.querySelector('.action-btn--more') as HTMLElement | null)
        ?.focus({ preventScroll: true });
    }
  }

  /** Crear menú en document.body */
  private createMenuInBody(): void {
    const moreBtn = this.elementRef.nativeElement.querySelector('.action-btn--more');
    if (!moreBtn) return;

    // Crear elemento del menú
    this.menuElement = this.renderer.createElement('div');
    this.renderer.addClass(this.menuElement, 'action-menu-portal');
    this.renderer.setAttribute(this.menuElement, 'id', this.menuId);
    this.renderer.setAttribute(this.menuElement, 'role', 'menu');
    this.renderer.setAttribute(this.menuElement, 'aria-label', 'Acciones adicionales');
    const direction = this.direction();
    this.renderer.setAttribute(this.menuElement, 'aria-orientation', direction);
    if (direction === 'horizontal') {
      this.renderer.addClass(this.menuElement, 'horizontal');
    }

    // Crear items del menú
    const actions = this.menuActions();
    actions.forEach(action => {
      const btn = this.renderer.createElement('button');
      this.renderer.setAttribute(btn, 'type', 'button');
      this.renderer.addClass(btn, 'menu-item');
      this.renderer.addClass(btn, `menu-item--${this.actionVariant(action)}`);
      if (action.disabled || action.loading) {
        this.renderer.addClass(btn, 'disabled');
        this.renderer.setAttribute(btn, 'disabled', 'true');
      }
      this.renderer.setAttribute(btn, 'role', 'menuitem');
      this.renderer.setAttribute(btn, 'aria-label', action.label);
      if (action.loading) {
        this.renderer.setAttribute(btn, 'aria-busy', 'true');
      }

      // Icono
      if (action.loading) {
        const spinner = this.renderer.createElement('span');
        this.renderer.addClass(spinner, 'action-spinner');
        this.renderer.setAttribute(spinner, 'aria-hidden', 'true');
        this.renderer.appendChild(btn, spinner);
      } else {
        const icon = this.renderer.createElement('i');
        this.actionIconClass(action)
          .split(' ')
          .forEach(cls => this.renderer.addClass(icon, cls));
        this.renderer.setAttribute(icon, 'aria-hidden', 'true');
        this.renderer.appendChild(btn, icon);
      }

      // Label (para vertical o compact)
      if (this.direction() === 'vertical' || this.compact()) {
        const label = this.renderer.createElement('span');
        this.renderer.addClass(label, 'menu-item-label');
        const text = this.renderer.createText(action.label);
        this.renderer.appendChild(label, text);
        this.renderer.appendChild(btn, label);
      }

      // Event listener
      const cleanup = this.renderer.listen(btn, 'click', (e: Event) => {
        e.stopPropagation();
        e.preventDefault();
        if (!action.disabled && !action.loading) {
          this.closeMenu(true);
          this.actionClick.emit(action.id);
        }
      });
      this.menuListenerCleanups.push(cleanup);

      this.renderer.appendChild(this.menuElement, btn);
    });

    // Añadir al body
    this.renderer.appendChild(this.document.body, this.menuElement);

    this.menuListenerCleanups.push(
      this.renderer.listen(this.menuElement, 'keydown', (event: KeyboardEvent) =>
        this.onMenuKeydown(event),
      ),
    );

    // Calcular posición
    requestAnimationFrame(() => {
      this.updatePosition();
      this.enabledMenuItems()[0]?.focus({ preventScroll: true });
    });
  }

  /** Click en acción visible */
  onActionClick(action: ActionItem, event?: Event): void {
    event?.stopPropagation();
    if (action.disabled || action.loading) return;
    this.actionClick.emit(action.id);
  }



  /** Cerrar menú al hacer clic fuera */
  @HostListener('document:mousedown', ['$event'])
  onClickOutside(event: MouseEvent): void {
    const target = event.target as HTMLElement;
    // Verificar si el click fue fuera del componente Y fuera del menú portal
    const isOutsideComponent = !this.elementRef.nativeElement.contains(target);
    const isOutsideMenu = !this.menuElement || !this.menuElement.contains(target);

    if (isOutsideComponent && isOutsideMenu) {
      this.closeMenu();
    }
  }

  /** Cerrar menú con Escape */
  @HostListener('document:keydown.escape')
  onEscape(): void {
    if (this.isOpen()) {
      this.closeMenu(true);
    }
  }

  private enabledMenuItems(): HTMLButtonElement[] {
    return this.menuElement
      ? Array.from(this.menuElement.querySelectorAll<HTMLButtonElement>('.menu-item:not(:disabled)'))
      : [];
  }

  private onMenuKeydown(event: KeyboardEvent): void {
    const items = this.enabledMenuItems();
    if (items.length === 0) return;
    const activeIndex = items.indexOf(this.document.activeElement as HTMLButtonElement);
    let nextIndex: number | null = null;

    if (event.key === 'ArrowDown' || event.key === 'ArrowRight') {
      nextIndex = activeIndex < 0 ? 0 : (activeIndex + 1) % items.length;
    } else if (event.key === 'ArrowUp' || event.key === 'ArrowLeft') {
      nextIndex = activeIndex <= 0 ? items.length - 1 : activeIndex - 1;
    } else if (event.key === 'Home') {
      nextIndex = 0;
    } else if (event.key === 'End') {
      nextIndex = items.length - 1;
    }

    if (nextIndex !== null) {
      event.preventDefault();
      items[nextIndex]?.focus({ preventScroll: true });
    }
  }

  /** Calcular posición óptima del menú (position: fixed) */
  private updatePosition(): void {
    if (!this.menuElement) return;

    const moreBtn = this.elementRef.nativeElement.querySelector('.action-btn--more');
    if (!moreBtn) return;

    const rect = moreBtn.getBoundingClientRect();
    const menuRect = this.menuElement.getBoundingClientRect();
    const menuHeight = menuRect.height || 180;
    const menuWidth = menuRect.width || 160;

    const spaceBelow = window.innerHeight - rect.bottom;
    const spaceRight = window.innerWidth - rect.right;

    const preferredPosition = this.menuPosition();
    const clamp = (value: number, min: number, max: number) => Math.max(min, Math.min(value, max));

    const computeAutoVertical = () => spaceBelow >= menuHeight ? 'bottom' : 'top';
    const computeAutoHorizontal = () => spaceRight >= menuWidth ? 'right' : 'left';

    const positionToUse = preferredPosition === 'auto'
      ? computeAutoVertical()
      : preferredPosition;

    let top: number;
    let left: number;

    switch (positionToUse) {
      case 'top':
        top = rect.top - menuHeight - 4;
        left = rect.left;
        break;
      case 'bottom':
        top = rect.bottom + 4;
        left = rect.left;
        break;
      case 'left':
        top = rect.top + (rect.height - menuHeight) / 2;
        left = rect.left - menuWidth - 4;
        break;
      case 'right':
        top = rect.top + (rect.height - menuHeight) / 2;
        left = rect.right + 4;
        break;
      default: {
        // Fallback: decide vertical first, then horizontal to keep menu visible
        const vertical = computeAutoVertical();
        const horizontal = computeAutoHorizontal();
        top = vertical === 'bottom' ? rect.bottom + 4 : rect.top - menuHeight - 4;
        left = horizontal === 'right' ? rect.right - menuWidth : rect.left;
      }
    }

    // Asegurar que no se salga de la pantalla
    top = clamp(top, 8, window.innerHeight - menuHeight - 8);
    left = clamp(left, 8, window.innerWidth - menuWidth - 8);

    // Aplicar estilos directamente al elemento
    this.renderer.setStyle(this.menuElement, 'top', `${top}px`);
    this.renderer.setStyle(this.menuElement, 'left', `${left}px`);
  }
}

import {
  Component, signal, HostListener,
  ElementRef, ChangeDetectionStrategy, inject,
  ViewEncapsulation, OnInit, OnDestroy, Renderer2,
  input,
  output
} from '@angular/core';
import { DOCUMENT } from '@angular/common';

let nextActionMenuId = 0;

export interface ActionMenuItem {
  id: string;
  icon?: string;
  label: string;
  variant?: 'default' | 'primary' | 'secondary' | 'danger' | 'warning' | 'success' | 'info';
  disabled?: boolean;
}

@Component({
  selector: 'app-action-menu',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  template: `
    <div class="action-menu-wrapper" [class.open]="isOpen()">
      <button
        type="button"
        class="action-menu-trigger"
        [title]="triggerTitle()"
        [attr.aria-label]="triggerTitle()"
        (click)="toggleMenu($event)"
        [attr.aria-expanded]="isOpen()"
        [attr.aria-controls]="menuId"
        aria-haspopup="menu"
        (keydown.arrowdown)="openMenuFromKeyboard($event)"
      >
        <i [class]="triggerIcon()" aria-hidden="true"></i>
      </button>
    </div>
  `,
  styleUrl: './action-menu.component.css'
})
export class ActionMenuComponent implements OnInit, OnDestroy {
  readonly actions = input<ActionMenuItem[]>([]);
  readonly triggerIcon = input<string>('fa-solid fa-ellipsis-vertical');
  readonly triggerTitle = input<string>('Opciones');
  readonly actionClick = output<string>();

  isOpen = signal(false);
  readonly menuId = `action-menu-portal-${nextActionMenuId++}`;

  private readonly elementRef = inject(ElementRef);
  private readonly renderer = inject(Renderer2);
  private readonly document = inject(DOCUMENT);

  private menuElement: HTMLElement | null = null;
  private menuListenerCleanups: (() => void)[] = [];

  private scrollListener = () => this.onScrollOrResize();
  private resizeListener = () => this.onScrollOrResize();

  ngOnInit(): void {
    if (typeof window !== 'undefined') {
      window.addEventListener('scroll', this.scrollListener, true);
      window.addEventListener('resize', this.resizeListener);
    }
  }

  ngOnDestroy(): void {
    if (typeof window !== 'undefined') {
      window.removeEventListener('scroll', this.scrollListener, true);
      window.removeEventListener('resize', this.resizeListener);
    }
    this.destroyMenu();
  }

  private destroyMenu(): void {
    this.menuListenerCleanups.forEach((cleanup) => cleanup());
    this.menuListenerCleanups = [];
    if (this.menuElement) {
      this.renderer.removeChild(this.document.body, this.menuElement);
      this.menuElement = null;
    }
  }

  private onScrollOrResize(): void {
    if (this.isOpen()) {
      this.updatePosition();
    }
  }

  toggleMenu(event: Event): void {
    event.stopPropagation();
    event.preventDefault();
    if (this.isOpen()) {
      this.closeMenu(true);
    } else {
      this.openMenu();
    }
  }

  openMenuFromKeyboard(event: Event): void {
    event.preventDefault();
    event.stopPropagation();
    if (!this.isOpen()) {
      this.openMenu();
    }
  }

  private openMenu(): void {
    if (this.actions().length === 0) return;
    this.isOpen.set(true);
    this.createMenuInBody();
  }

  toggleMenuProgrammatically(): void {
    this.toggleMenu(new Event('click'));
  }

  private closeMenu(restoreFocus = false): void {
    this.isOpen.set(false);
    this.destroyMenu();
    if (restoreFocus) {
      (this.elementRef.nativeElement.querySelector('.action-menu-trigger') as HTMLElement | null)?.focus({ preventScroll: true });
    }
  }

  private createMenuInBody(): void {
    const triggerBtn = this.elementRef.nativeElement.querySelector('.action-menu-trigger');
    if (!triggerBtn) return;

    this.menuElement = this.renderer.createElement('div');
    this.renderer.addClass(this.menuElement, 'action-menu-portal');
    this.renderer.setAttribute(this.menuElement, 'id', this.menuId);
    this.renderer.setAttribute(this.menuElement, 'role', 'menu');
    this.renderer.setAttribute(this.menuElement, 'aria-label', this.triggerTitle());

    this.actions().forEach(action => {
      const btn = this.renderer.createElement('button');
      this.renderer.setAttribute(btn, 'type', 'button');
      this.renderer.addClass(btn, 'menu-item');
      if (action.variant) {
        this.renderer.addClass(btn, `menu-item--${action.variant}`);
      }
      if (action.disabled) {
        this.renderer.addClass(btn, 'disabled');
        this.renderer.setAttribute(btn, 'disabled', 'true');
      }
      this.renderer.setAttribute(btn, 'role', 'menuitem');

      if (action.icon) {
        const icon = this.renderer.createElement('i');
        action.icon.split(' ').forEach((cls: string) => this.renderer.addClass(icon, cls));
        this.renderer.setAttribute(icon, 'aria-hidden', 'true');
        this.renderer.appendChild(btn, icon);
      }

      const label = this.renderer.createElement('span');
      this.renderer.addClass(label, 'menu-item-label');
      const text = this.renderer.createText(action.label);
      this.renderer.appendChild(label, text);
      this.renderer.appendChild(btn, label);

      const cleanup = this.renderer.listen(btn, 'click', (e: Event) => {
        e.stopPropagation();
        e.preventDefault();
        if (!action.disabled) {
          this.closeMenu(true);
          this.actionClick.emit(action.id);
        }
      });
      this.menuListenerCleanups.push(cleanup);

      this.renderer.appendChild(this.menuElement, btn);
    });

    this.renderer.appendChild(this.document.body, this.menuElement);

    this.menuListenerCleanups.push(
      this.renderer.listen(this.menuElement, 'keydown', (event: KeyboardEvent) => this.onMenuKeydown(event))
    );

    requestAnimationFrame(() => {
      this.updatePosition();
      this.enabledMenuItems()[0]?.focus({ preventScroll: true });
    });
  }

  @HostListener('document:mousedown', ['$event'])
  onClickOutside(event: MouseEvent): void {
    const target = event.target as HTMLElement;
    const isOutsideComponent = !this.elementRef.nativeElement.contains(target);
    const isOutsideMenu = !this.menuElement || !this.menuElement.contains(target);

    if (isOutsideComponent && isOutsideMenu) {
      this.closeMenu();
    }
  }

  @HostListener('document:keydown.escape')
  onEscape(): void {
    if (this.isOpen()) {
      this.closeMenu(true);
    }
  }

  private enabledMenuItems(): HTMLButtonElement[] {
    return this.menuElement
      ? Array.from(this.menuElement.querySelectorAll<HTMLButtonElement>('.menu-item:not(:disabled)'))
      : [];
  }

  private onMenuKeydown(event: KeyboardEvent): void {
    const items = this.enabledMenuItems();
    if (items.length === 0) return;
    const activeIndex = items.indexOf(this.document.activeElement as HTMLButtonElement);
    let nextIndex: number | null = null;

    if (event.key === 'ArrowDown' || event.key === 'ArrowRight') {
      nextIndex = activeIndex < 0 ? 0 : (activeIndex + 1) % items.length;
    } else if (event.key === 'ArrowUp' || event.key === 'ArrowLeft') {
      nextIndex = activeIndex <= 0 ? items.length - 1 : activeIndex - 1;
    } else if (event.key === 'Home') {
      nextIndex = 0;
    } else if (event.key === 'End') {
      nextIndex = items.length - 1;
    }

    if (nextIndex !== null) {
      event.preventDefault();
      items[nextIndex]?.focus({ preventScroll: true });
    }
  }

  private updatePosition(): void {
    if (!this.menuElement) return;
    const triggerBtn = this.elementRef.nativeElement.querySelector('.action-menu-trigger');
    if (!triggerBtn) return;

    const rect = triggerBtn.getBoundingClientRect();
    const menuRect = this.menuElement.getBoundingClientRect();
    const menuHeight = menuRect.height || 180;
    const menuWidth = menuRect.width || 160;

    const spaceBelow = window.innerHeight - rect.bottom;
    const clamp = (value: number, min: number, max: number) => Math.max(min, Math.min(value, max));

    let top: number;
    let left: number;

    if (spaceBelow >= menuHeight) {
      top = rect.bottom + 4;
    } else {
      top = rect.top - menuHeight - 4;
    }

    // align right by default
    left = rect.right - menuWidth + rect.width;

    top = clamp(top, 8, window.innerHeight - menuHeight - 8);
    left = clamp(left, 8, window.innerWidth - menuWidth - 8);

    this.renderer.setStyle(this.menuElement, 'top', `${top}px`);
    this.renderer.setStyle(this.menuElement, 'left', `${left}px`);
  }
}

import { NgTemplateOutlet } from '@angular/common';
import {
  AfterViewInit,
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  NgZone,
  OnDestroy,
  TemplateRef,
  computed,
  contentChild,
  inject,
  input,
  linkedSignal,
  output,
  signal,
} from '@angular/core';
import { TranslatePipe } from '@ngx-translate/core';
import { Alert } from '../../molecules/alert/alert.component';
import { ButtonComponent } from '../../atoms/button/button.component';
import { BadgeComponent, BadgeVariant } from '../../atoms/badge/badge.component';

import { ScrollOverlayComponent } from '../scroll-overlay/scroll-overlay.component';
import { VariablesCssDirective } from '../../directives/variables-css.directive';
import { Select2Component, Select2Option } from '../../molecules/select2/select2.component';
import { FormsModule } from '@angular/forms';

export type DataTableAlignment = 'start' | 'center' | 'end';
export type DataTableDensity = 'comfortable' | 'compact';
export type DataTablePaginationMode = 'none' | 'client' | 'server';
export type DataTableStatus = 'idle' | 'loading' | 'success' | 'empty' | 'error';
export type DataTableSortDirection = 'asc' | 'desc' | null;

export interface DataTableColumn<T extends object = Record<string, unknown>> {
  readonly key: Extract<keyof T, string>;
  readonly header: string;
  readonly sortable?: boolean;
  readonly align?: DataTableAlignment;
  readonly width?: string;
  readonly isBadge?: boolean;
  readonly badgeVariant?: (row: T) => BadgeVariant;
  readonly isTag?: boolean;
  readonly tagVariant?: (row: T) => BadgeVariant;
  readonly value?: (row: T) => unknown;
  readonly format?: (value: unknown, row: T) => string;
  readonly sortValue?: (row: T) => unknown;
  readonly compare?: (left: T, right: T) => number;
}

export interface DataTableSortChange<T extends object = Record<string, unknown>> {
  readonly key: Extract<keyof T, string>;
  readonly direction: DataTableSortDirection;
}

export interface DataTableActionContext<T extends object = Record<string, unknown>> {
  readonly $implicit: T;
  readonly row: T;
  readonly index: number;
}

export type DataTableTrackBy<T extends object = Record<string, unknown>> = (
  index: number,
  row: T,
) => unknown;

interface ActiveSort<T extends object> {
  readonly key: Extract<keyof T, string>;
  readonly direction: Exclude<DataTableSortDirection, null>;
}

interface IndexedRow<T extends object> {
  readonly row: T;
  readonly originalIndex: number;
}

function trackByIdentity<T extends object>(_index: number, row: T): T {
  return row;
}

@Component({
  selector: 'app-data-table, prest-data-table',
  imports: [
    Alert,
    ButtonComponent,
    NgTemplateOutlet,
    ScrollOverlayComponent,
    BadgeComponent,
    VariablesCssDirective,
    Select2Component,
    FormsModule,
    TranslatePipe,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './data-table.html',
  styleUrl: './data-table.scss',
})
export class DataTable<T extends object = Record<string, unknown>> implements AfterViewInit, OnDestroy {
  private readonly host = inject<ElementRef<HTMLElement>>(ElementRef);
  private readonly zone = inject(NgZone);
  readonly columns = input.required<readonly DataTableColumn<T>[]>();
  readonly rows = input.required<readonly T[]>();
  readonly caption = input.required<string>();
  readonly captionVisible = input(false);
  readonly density = input<DataTableDensity>('comfortable');
  readonly status = input<DataTableStatus>('success');
  readonly loadingMessage = input('Cargando información…');
  readonly idleMessage = input('Aún no se ha cargado información.');
  readonly emptyMessage = input('No hay información para mostrar.');
  readonly errorMessage = input('No fue posible cargar la información.');
  readonly retryLabel = input('Reintentar');
  readonly actionsHeader = input('Acciones');
  readonly actionsWidth = input('12rem');
  readonly emptyValue = input('—');
  readonly trackBy = input<DataTableTrackBy<T>>(trackByIdentity);
  readonly showRowNumber = input(true);
  readonly rowNumberHeader = input('N.º');
  readonly rowNumberWidth = input('4.5rem');

  // Row numbering and local pagination remain the published defaults.
  // Consumers may opt out of pagination explicitly with `none`.
  readonly pagination = input<DataTablePaginationMode>('client');
  readonly totalRecords = input<number | null>(null);
  readonly page = input(1);
  readonly pageSize = input(10);
  readonly totalPages = input(1);
  readonly pageSizeOptions = input<readonly number[]>([10, 20, 50, 100]);
  readonly hasPreviousPage = input(false);
  readonly hasNextPage = input(false);

  readonly sortChange = output<DataTableSortChange<T>>();
  readonly retry = output<void>();
  readonly pageChange = output<number>();
  readonly pageSizeChange = output<number>();

  protected readonly actionsTemplate =
    contentChild<TemplateRef<DataTableActionContext<T>>>('actions');

  private readonly activeSort = signal<ActiveSort<T> | null>(null);
  private readonly internalPage = linkedSignal(() => Math.max(this.page(), 1));
  private readonly internalPageSize = linkedSignal(() => Math.max(this.pageSize(), 1));
  private readonly collator = new Intl.Collator('es-PE', {
    numeric: true,
    sensitivity: 'base',
  });

  protected readonly usesClientPagination = computed(
    () => this.pagination() === 'client' && this.totalRecords() === null,
  );
  protected readonly paginationEnabled = computed(
    () => this.pagination() !== 'none',
  );
  protected readonly effectivePageSize = computed(() => this.internalPageSize());
  /*
    El desplegable «POR PÁGINA» tiene que poder mostrar el tamaño REALMENTE
    vigente, aunque nadie lo haya incluido en la lista de opciones.

    Sin esto, un consumidor que fije `[pageSize]="25"` con las opciones por
    omisión —10, 20, 30, 40, 50— obtiene una tabla que pagina de 25 en 25 y un
    desplegable sin ninguna opción que coincida, que queda en blanco: el
    paginador contradice a su propia tabla y el usuario no puede saber de cuánto
    está paginando.

    Se inserta ordenado, no al final, para que la escala siga leyéndose.
  */
  protected readonly effectivePageSizeOptions = computed<readonly number[]>(() => {
    const options = this.pageSizeOptions();
    const current = this.effectivePageSize();
    return options.includes(current)
      ? options
      : [...options, current].sort((first, second) => first - second);
  });
  protected readonly pageSizeSelectOptions = computed<Select2Option[]>(() => {
    return this.effectivePageSizeOptions().map((size) => ({
      value: size,
      label: String(size),
    }));
  });
  protected readonly effectiveTotalRecords = computed(
    () => this.totalRecords() ?? this.sortedRows().length,
  );
  protected readonly effectiveTotalPages = computed(() => {
    if (!this.paginationEnabled()) {
      return 1;
    }
    if (!this.usesClientPagination()) {
      return Math.max(this.totalPages(), 1);
    }
    return Math.max(
      Math.ceil(this.effectiveTotalRecords() / this.effectivePageSize()),
      1,
    );
  });
  protected readonly effectivePage = computed(() => {
    if (!this.paginationEnabled()) return 1;
    return this.usesClientPagination()
      ? Math.min(this.internalPage(), this.effectiveTotalPages())
      : this.internalPage();
  });
  protected readonly effectiveHasPreviousPage = computed(() =>
    this.usesClientPagination()
      ? this.effectivePage() > 1
      : this.hasPreviousPage(),
  );
  protected readonly effectiveHasNextPage = computed(() =>
    this.usesClientPagination()
      ? this.effectivePage() < this.effectiveTotalPages()
      : this.hasNextPage(),
  );

  protected readonly rangeStart = computed(() => {
    const total = this.effectiveTotalRecords();
    if (total === 0) return 0;
    return (this.effectivePage() - 1) * this.effectivePageSize() + 1;
  });

  protected readonly rangeEnd = computed(() => {
    const total = this.effectiveTotalRecords();
    if (total === 0) return 0;
    return Math.min(this.effectivePage() * this.effectivePageSize(), total);
  });

  protected onPageSizeSelectionChange(value: string | number): void {
    const pageSize = Number(value);
    this.internalPageSize.set(pageSize);
    if (this.usesClientPagination()) {
      this.internalPage.set(1);
      return;
    }
    this.pageSizeChange.emit(pageSize);
  }



  /*
  EL BOTON QUE SE DESHABILITA BAJO LOS DEDOS SE LLEVA EL FOCO AL <body>.

  Los dos botones se deshabilitan al llegar al extremo Y durante cada carga.
  Cuando eso pasa con el foco encima, el navegador lo descarta y quien paginaba
  con el teclado se queda sin punto de partida: el siguiente Tab empieza desde
  el principio del documento. Con tres paginas eso ocurre siempre en la ultima.

  Se traslada ANTES de emitir, porque despues el boton ya no puede recibirlo.
  Va al resumen —la barra que dice cuantos registros hay—, que es lo que la
  persona necesita leer justo despues de cambiar de pagina.
  */
  protected onPageChange(page: number): void {
    this.rescueFocusFromPager();
    const newPage = Math.min(Math.max(page, 1), this.effectiveTotalPages());
    this.internalPage.set(newPage);
    if (this.usesClientPagination()) {
      return;
    }
    this.pageChange.emit(page);
  }

  private rescueFocusFromPager(): void {
    const host = this.host.nativeElement;
    const active = host.ownerDocument.activeElement;
    if (!(active instanceof HTMLElement) || !active.classList.contains('data-table__page-btn')) {
      return;
    }
    const summary = host.querySelector<HTMLElement>('.data-table__summary');
    if (!summary) {
      return;
    }
    if (!summary.hasAttribute('tabindex')) {
      summary.setAttribute('tabindex', '-1');
    }
    summary.focus({ preventScroll: true });
  }

  protected readonly effectiveStatus = computed<DataTableStatus>(() => {
    const requestedStatus = this.status();
    if (requestedStatus === 'success' && this.sortedRows().length === 0) {
      return 'empty';
    }
    return requestedStatus;
  });

  protected readonly columnSpan = computed(() =>
    Math.max(
      this.columns().length +
        (this.showRowNumber() ? 1 : 0) +
        (this.actionsTemplate() ? 1 : 0),
      1,
    ),
  );

  protected readonly regionLabel = computed(
    () => `${this.caption()}. Desplace horizontalmente para ver más columnas.`,
  );

  private readonly sortedRows = computed<readonly T[]>(() => {
    let rows: unknown = this.rows();
    if (typeof rows === 'string') {
      try {
        rows = JSON.parse(rows);
      } catch {
        rows = [];
      }
    }

    if (rows && typeof rows === 'object' && !Array.isArray(rows)) {
      const envoltorio = rows as Record<string, unknown>;
      const valor = envoltorio['value'];
      const valorAnidado = valor !== null && (typeof valor === 'object' || typeof valor === 'function')
        ? valor as Record<string, unknown>
        : undefined;
      // Conservar la prioridad historica de los arreglos, incluso si estan vacios.
      if (Array.isArray(envoltorio['$values'])) {
        rows = envoltorio['$values'];
      } else if (Array.isArray(envoltorio['data'])) {
        rows = envoltorio['data'];
      } else if (Array.isArray(envoltorio['items'])) {
        rows = envoltorio['items'];
      } else if (Array.isArray(envoltorio['elementos'])) {
        rows = envoltorio['elementos'];
      } else if (valorAnidado && Array.isArray(valorAnidado['elementos'])) {
        rows = valorAnidado['elementos'];
      } else if (valorAnidado && Array.isArray(valorAnidado['data'])) {
        rows = valorAnidado['data'];
      } else {
        const claveArreglo = Object.keys(envoltorio).find(clave => Array.isArray(envoltorio[clave]));
        if (claveArreglo) {
          rows = envoltorio[claveArreglo];
        } else if (valorAnidado) {
          const claveArregloAnidado = Object.keys(valorAnidado).find(clave => Array.isArray(valorAnidado[clave]));
          if (claveArregloAnidado) rows = valorAnidado[claveArregloAnidado];
        }
      }
    }

    if (!Array.isArray(rows)) {
      rows = [];
    }
    const sort = this.activeSort();
    if (!sort) {
      return rows as readonly T[];
    }

    const column = this.columns().find(
      (candidate) => candidate.key === sort.key && candidate.sortable,
    );
    if (!column) {
      return rows as readonly T[];
    }

    return (rows as readonly T[])
      .map<IndexedRow<T>>((row, originalIndex) => ({ row, originalIndex }))
      .sort((left, right) => {
        const comparison = this.compareRows(column, left.row, right.row, sort.direction);
        return comparison === 0 ? left.originalIndex - right.originalIndex : comparison;
      })
      .map(({ row }) => row);
  });

  protected readonly displayedRows = computed<readonly T[]>(() => {
    const rows = this.sortedRows();
    if (!this.usesClientPagination()) {
      return rows;
    }
    const offset = (this.effectivePage() - 1) * this.effectivePageSize();
    return rows.slice(offset, offset + this.effectivePageSize());
  });

  protected rowNumber(index: number): number {
    return (
      (this.effectivePage() - 1) * this.effectivePageSize() +
      index +
      1
    );
  }

  protected identifyRow(index: number, row: T): unknown {
    const identity = this.trackBy()(index, row);
    if (identity === row && (typeof row !== 'object' || row === null)) {
      return index;
    }
    return identity;
  }

  protected isTagColumn(column: DataTableColumn<T>): boolean {
    return (
      !!column.isBadge ||
      !!column.isTag ||
      ['stateLabel', 'state', 'status', 'estado'].includes(column.key)
    );
  }

  protected columnAlignment(column: DataTableColumn<T>): DataTableAlignment {
    return column.align ?? (this.isTagColumn(column) ? 'center' : 'start');
  }

  protected getTagVariant(column: DataTableColumn<T>, row: T): BadgeVariant {
    const customVariant = column.badgeVariant ?? column.tagVariant;
    if (customVariant) {
      return customVariant(row);
    }
    const val = String(this.columnValue(column, row) ?? '').trim().toLowerCase();
    if (
      val === 'activo' ||
      val === 'activa' ||
      val === 'active' ||
      val === 'vigente' ||
      val === 'completado' ||
      val === 'completada' ||
      val === 'completed' ||
      val === 'pagado' ||
      val === 'pagada' ||
      val === 'paid' ||
      val === 'registrado' ||
      val === 'registrada' ||
      val === 'emitido' ||
      val === 'emitida' ||
      val === 'aplicado' ||
      val === 'aplicada' ||
      val === 'aprobado' ||
      val === 'aprobada' ||
      val === 'al día' ||
      val === 'al dia' ||
      val === 'true' ||
      val === '1'
    ) {
      return 'success';
    }
    if (
      val === 'inactivo' ||
      val === 'inactiva' ||
      val === 'inactive' ||
      val === 'bloqueado' ||
      val === 'bloqueada' ||
      val === 'anulada' ||
      val === 'anulado' ||
      val === 'cancelado' ||
      val === 'cancelada' ||
      val === 'cancelled' ||
      val === 'canceled' ||
      val === 'eliminado' ||
      val === 'eliminada' ||
      val === 'rechazado' ||
      val === 'rechazada' ||
      val === 'revertido' ||
      val === 'revertida' ||
      val === 'error' ||
      val === 'false' ||
      val === '0'
    ) {
      return 'danger';
    }
    if (
      val.includes('incidencia') ||
      val.includes('degradado') ||
      val.includes('vencid') ||
      val.includes('mora') ||
      val.includes('atrasad') ||
      val.includes('parcial') ||
      val.includes('pendiente') ||
      val.includes('pending') ||
      val.includes('ausente') ||
      val.includes('revisión') ||
      val.includes('revision') ||
      val.includes('en espera')
    ) {
      return 'warning';
    }
    return 'default';
  }

  protected displayValue(column: DataTableColumn<T>, row: T): string {
    const value = this.columnValue(column, row);
    if (column.format) {
      return column.format(value, row);
    }
    if (value === null || value === undefined || value === '') {
      return this.emptyValue();
    }
    return String(value);
  }

  protected actionContext(row: T, index: number): DataTableActionContext<T> {
    return { $implicit: row, row, index };
  }

  protected onSort(column: DataTableColumn<T>): void {
    if (!column.sortable) {
      return;
    }

    const current = this.activeSort();
    let direction: DataTableSortDirection = 'asc';
    if (current?.key === column.key && current.direction === 'asc') {
      direction = 'desc';
    } else if (current?.key === column.key && current.direction === 'desc') {
      direction = null;
    }

    this.activeSort.set(direction ? { key: column.key, direction } : null);
    if (this.usesClientPagination()) {
      this.internalPage.set(1);
    }
    this.sortChange.emit({ key: column.key, direction });
  }

  protected ariaSort(column: DataTableColumn<T>): 'ascending' | 'descending' | 'none' | null {
    if (!column.sortable) {
      return null;
    }

    const current = this.activeSort();
    if (current?.key !== column.key) {
      return 'none';
    }
    return current.direction === 'asc' ? 'ascending' : 'descending';
  }

  protected sortButtonLabel(column: DataTableColumn<T>): string {
    const current = this.activeSort();
    if (current?.key !== column.key) {
      return `${column.header}: sin orden. Activar para ordenar ascendente.`;
    }
    if (current.direction === 'asc') {
      return `${column.header}: orden ascendente. Activar para ordenar descendente.`;
    }
    return `${column.header}: orden descendente. Activar para quitar el orden.`;
  }

  protected sortIndicatorClass(column: DataTableColumn<T>): string {
    const current = this.activeSort();
    if (current?.key !== column.key) {
      return 'fa-sort';
    }
    return current.direction === 'asc' ? 'fa-sort-up' : 'fa-sort-down';
  }

  private columnValue(column: DataTableColumn<T>, row: T): unknown {
    return column.value ? column.value(row) : row[column.key];
  }

  private sortValue(column: DataTableColumn<T>, row: T): unknown {
    return column.sortValue ? column.sortValue(row) : this.columnValue(column, row);
  }

  private compareRows(
    column: DataTableColumn<T>,
    left: T,
    right: T,
    direction: Exclude<DataTableSortDirection, null>,
  ): number {
    if (column.compare) {
      const comparison = column.compare(left, right);
      return direction === 'asc' ? comparison : -comparison;
    }

    const leftValue = this.sortValue(column, left);
    const rightValue = this.sortValue(column, right);
    const leftIsEmpty = leftValue === null || leftValue === undefined;
    const rightIsEmpty = rightValue === null || rightValue === undefined;

    // Los valores ausentes permanecen al final en ambos sentidos de ordenamiento.
    if (leftIsEmpty || rightIsEmpty) {
      if (leftIsEmpty && rightIsEmpty) {
        return 0;
      }
      return leftIsEmpty ? 1 : -1;
    }

    const comparison = this.compareValues(leftValue, rightValue);
    return direction === 'asc' ? comparison : -comparison;
  }

  private compareValues(left: unknown, right: unknown): number {
    if (left === right) {
      return 0;
    }
    if (typeof left === 'number' && typeof right === 'number') {
      if (Number.isNaN(left) || Number.isNaN(right)) {
        return this.collator.compare(String(left), String(right));
      }
      return left < right ? -1 : 1;
    }
    if (typeof left === 'bigint' && typeof right === 'bigint') {
      return left < right ? -1 : 1;
    }
    if (left instanceof Date && right instanceof Date) {
      return left.getTime() - right.getTime();
    }
    if (typeof left === 'boolean' && typeof right === 'boolean') {
      return left ? 1 : -1;
    }
    return this.collator.compare(String(left), String(right));
  }

  protected readonly isScrolledRight = signal(true);
  private scrollObserver?: ResizeObserver;
  private scrollListener?: () => void;

  ngAfterViewInit(): void {
    this.zone.runOutsideAngular(() => {
      const host = this.host.nativeElement;
      const scrollArea = host.querySelector('.so-scroll-area');
      if (!scrollArea) {
        return;
      }

      const checkScroll = () => {
        const { scrollLeft, clientWidth, scrollWidth } = scrollArea;
        // Permite 1px de tolerancia por redondeos en pantallas con escala fraccional
        const atRight = scrollWidth === 0 || (scrollLeft + clientWidth >= scrollWidth - 1);
        if (this.isScrolledRight() !== atRight) {
          this.zone.run(() => this.isScrolledRight.set(atRight));
        }
      };

      this.scrollListener = () => checkScroll();
      scrollArea.addEventListener('scroll', this.scrollListener, { passive: true });

      if (typeof ResizeObserver !== 'undefined') {
        this.scrollObserver = new ResizeObserver(() => checkScroll());
        this.scrollObserver.observe(scrollArea);
        const table = host.querySelector('table');
        if (table) {
          this.scrollObserver.observe(table);
        }
      }

      setTimeout(checkScroll, 0);
    });
  }

  ngOnDestroy(): void {
    if (this.scrollListener) {
      const scrollArea = this.host.nativeElement.querySelector('.so-scroll-area');
      if (scrollArea) {
        scrollArea.removeEventListener('scroll', this.scrollListener);
      }
    }
    if (this.scrollObserver) {
      this.scrollObserver.disconnect();
    }
  }
}

import { Injectable, inject } from '@angular/core';
import { HttpClient, HttpHeaders, HttpParams, HttpErrorResponse } from '@angular/common/http';
import { Observable, throwError } from 'rxjs';
import { catchError, retry } from 'rxjs/operators';

/**
 * Configuración de request HTTP
 */
export interface ApiRequestOptions {
  headers?: HttpHeaders | Record<string, string | string[]>;
  params?: HttpParams | Record<string, string | string[]>;
  withCredentials?: boolean;
  retryCount?: number;
}

/**
 * Respuesta de API estandarizada
 */
export interface ApiResponse<T> {
  data: T;
  message?: string;
  status?: number;
  success?: boolean;
}

/**
 * Error de API estandarizado
 */
export interface ApiError {
  message: string;
  status: number;
  statusText: string;
  url: string | null;
  errors?: Record<string, string[]>;
}

/**
 * Servicio genérico para consumir APIs REST.
 * 
 * @example
 * ```typescript
 * // Inyectar el servicio
 * private api = inject(ApiService);
 * 
 * // Configurar URL base
 * constructor() {
 *   this.api.setBaseUrl('https://api.example.com/v1');
 * }
 * 
 * // GET request
 * this.api.get<User[]>('/users').subscribe(users => console.log(users));
 * 
 * // POST request
 * this.api.post<User>('/users', { name: 'John' }).subscribe(user => console.log(user));
 * 
 * // Con opciones
 * this.api.get<User>('/users/1', { 
 *   headers: { 'Authorization': 'Bearer token' },
 *   retryCount: 3 
 * }).subscribe();
 * ```
 */
@Injectable({
  providedIn: 'root'
})
export class ApiService {
  private readonly http = inject(HttpClient);
  private baseUrl = '';
  private defaultHeaders: Record<string, string> = {
    'Content-Type': 'application/json',
    'Accept': 'application/json'
  };

  /**
   * Configura la URL base para todas las peticiones
   */
  setBaseUrl(url: string): void {
    this.baseUrl = url.replace(/\/$/, ''); // Remove trailing slash
  }

  /**
   * Obtiene la URL base configurada
   */
  getBaseUrl(): string {
    return this.baseUrl;
  }

  /**
   * Agrega headers por defecto a todas las peticiones
   */
  setDefaultHeaders(headers: Record<string, string>): void {
    this.defaultHeaders = { ...this.defaultHeaders, ...headers };
  }

  /**
   * Agrega un header de autorización Bearer
   */
  setAuthToken(token: string): void {
    this.defaultHeaders['Authorization'] = `Bearer ${token}`;
  }

  /**
   * Elimina el header de autorización
   */
  clearAuthToken(): void {
    delete this.defaultHeaders['Authorization'];
  }

  /**
   * GET request
   */
  get<T>(endpoint: string, options?: ApiRequestOptions): Observable<T> {
    return this.request<T>('GET', endpoint, null, options);
  }

  /**
   * POST request
   */
  post<T>(endpoint: string, body: unknown, options?: ApiRequestOptions): Observable<T> {
    return this.request<T>('POST', endpoint, body, options);
  }

  /**
   * PUT request
   */
  put<T>(endpoint: string, body: unknown, options?: ApiRequestOptions): Observable<T> {
    return this.request<T>('PUT', endpoint, body, options);
  }

  /**
   * PATCH request
   */
  patch<T>(endpoint: string, body: unknown, options?: ApiRequestOptions): Observable<T> {
    return this.request<T>('PATCH', endpoint, body, options);
  }

  /**
   * DELETE request
   */
  delete<T>(endpoint: string, options?: ApiRequestOptions): Observable<T> {
    return this.request<T>('DELETE', endpoint, null, options);
  }

  /**
   * Request genérico
   */
  private request<T>(
    method: string,
    endpoint: string,
    body: unknown | null,
    options?: ApiRequestOptions
  ): Observable<T> {
    const url = this.buildUrl(endpoint);
    const headers = this.buildHeaders(options?.headers);
    const retryCount = options?.retryCount ?? 0;

    const httpOptions = {
      headers,
      params: options?.params,
      withCredentials: options?.withCredentials ?? false,
      body: body ? JSON.stringify(body) : undefined
    };

    let request$: Observable<T>;

    switch (method) {
      case 'GET':
        request$ = this.http.get<T>(url, httpOptions);
        break;
      case 'POST':
        request$ = this.http.post<T>(url, body, httpOptions);
        break;
      case 'PUT':
        request$ = this.http.put<T>(url, body, httpOptions);
        break;
      case 'PATCH':
        request$ = this.http.patch<T>(url, body, httpOptions);
        break;
      case 'DELETE':
        request$ = this.http.delete<T>(url, httpOptions);
        break;
      default:
        throw new Error(`Unsupported HTTP method: ${method}`);
    }

    return request$.pipe(
      retry(retryCount),
      catchError(this.handleError.bind(this))
    );
  }

  /**
   * Construye la URL completa
   */
  private buildUrl(endpoint: string): string {
    if (endpoint.startsWith('http://') || endpoint.startsWith('https://')) {
      return endpoint; // URL absoluta
    }
    const cleanEndpoint = endpoint.startsWith('/') ? endpoint : `/${endpoint}`;
    return `${this.baseUrl}${cleanEndpoint}`;
  }

  /**
   * Construye los headers de la petición
   */
  private buildHeaders(customHeaders?: HttpHeaders | Record<string, string | string[]>): HttpHeaders {
    let headers = new HttpHeaders(this.defaultHeaders);

    if (customHeaders) {
      if (customHeaders instanceof HttpHeaders) {
        customHeaders.keys().forEach(key => {
          headers = headers.set(key, customHeaders.get(key) || '');
        });
      } else {
        Object.entries(customHeaders).forEach(([key, value]) => {
          headers = headers.set(key, value);
        });
      }
    }

    return headers;
  }

  /**
   * Maneja errores HTTP
   */
  private handleError(error: HttpErrorResponse): Observable<never> {
    const apiError: ApiError = {
      message: this.extractErrorMessage(error),
      status: error.status,
      statusText: error.statusText,
      url: error.url,
      errors: error.error?.errors
    };

    console.error('[ApiService] Error:', apiError);
    return throwError(() => apiError);
  }

  /**
   * Extrae mensaje de error legible
   */
  private extractErrorMessage(error: HttpErrorResponse): string {
    if (error.status === 0) {
      return 'No se pudo conectar con el servidor. Verifica tu conexión a internet.';
    }

    if (error.error?.message) {
      return error.error.message;
    }

    if (typeof error.error === 'string') {
      return error.error;
    }

    switch (error.status) {
      case 400: return 'Solicitud inválida';
      case 401: return 'No autorizado. Por favor inicia sesión.';
      case 403: return 'Acceso denegado';
      case 404: return 'Recurso no encontrado';
      case 422: return 'Datos de entrada inválidos';
      case 429: return 'Demasiadas solicitudes. Intenta más tarde.';
      case 500: return 'Error interno del servidor';
      case 502: return 'Servidor no disponible';
      case 503: return 'Servicio temporalmente no disponible';
      default: return `Error ${error.status}: ${error.statusText}`;
    }
  }
}

