import {
  Component, signal, computed, effect, untracked,
  forwardRef, ChangeDetectionStrategy, ElementRef, inject, PLATFORM_ID,
  input,
  output,
  viewChild
} from '@angular/core';
import { isPlatformBrowser } from '@angular/common';

import { ControlValueAccessor, NG_VALUE_ACCESSOR, FormsModule } from '@angular/forms';
import {
  FIELD_LABEL_VARIANT_DEFAULT,
  FieldLabelVariant,
  esEtiquetaElevada,
  esEtiquetaFlotante,
  esMarcadorVisible,
} from '../../atoms/form-field/field-label';

export interface ComboboxOption {
  value: string | number;
  label: string;
  disabled?: boolean;
  group?: string;
  /** Texto secundario; entra también en la búsqueda. */
  description?: string;
  /** Sinónimos por los que el usuario podría teclear esta opción. */
  keywords?: readonly string[];
}

/*
Normaliza para comparar: separa los diacríticos de su letra (NFD), los retira, y
minusculiza con las reglas del español. Colapsa además los espacios, para que
«San  Juan» y «San Juan» sean lo mismo al buscar.

El rango ̀-ͯ es el bloque de marcas diacríticas combinantes, que es lo
que NFD deja suelto detrás de cada letra acentuada.
*/
function normalizeSearch(value: string): string {
  return value
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLocaleLowerCase('es')
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * ComboboxComponent — Input con sugerencias de autocompletado.
 *
 * @example
 * ```html
 * <app-combobox
 *   [options]="userOptions"
 *   [(ngModel)]="selectedUser"
 *   label="Buscar usuario"
 *   placeholder="Escribe para buscar..."
 * ></app-combobox>
 * ```
 */
@Component({
  selector: 'app-combobox',
  standalone: true,
  imports: [FormsModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => ComboboxComponent),
      multi: true
    }
  ],
  template: `
    <div
      class="combobox"
      [class.fl-field--floating]="flotante()"
      [class.combobox-open]="isOpen()"
      [class.combobox-disabled]="disabled"
      [class.combobox-error-state]="error()"
    >
      @if (label() && !flotante()) {
        <label
          class="fl-label combobox-label"
          [class.fl-label--error]="error()"
          [class.fl-label--disabled]="disabled"
          [for]="inputId"
        >
          {{ label() }}
          @if (required()) {
            <span class="field__required fl-label__required" aria-hidden="true">*</span>
          }
        </label>
      }
      <div class="fl-control combobox-control" #controlRef>
        <input
          #inputRef
          [id]="inputId"
          class="combobox-input"
          type="text"
          [attr.placeholder]="marcador()"
          [required]="required()"
          [attr.aria-required]="required() ? 'true' : null"
          [disabled]="disabled"
          [value]="inputValue()"
          (input)="onInput($event)"
          (focus)="onFocus()"
          (blur)="onBlur()"
          (keydown)="onKeydown($event)"
          autocomplete="off"
          role="combobox"
          [attr.aria-expanded]="isOpen()"
          aria-autocomplete="list"
          [attr.aria-controls]="listboxId"
          [attr.aria-activedescendant]="activeOptionId()"
          [attr.aria-label]="label() ? null : ariaLabel() || placeholder()"
          [attr.aria-invalid]="error() ? 'true' : 'false'"
          [attr.aria-errormessage]="error() ? errorId : null"
          aria-haspopup="listbox"
        />
        @if (flotante()) {
          <label
            class="fl-label fl-label--floating"
            [class.fl-label--floated]="elevada()"
            [class.fl-label--error]="error()"
            [class.fl-label--disabled]="disabled"
            [for]="inputId"
          >
            {{ label() }}
            @if (required()) {
              <span class="field__required fl-label__required" aria-hidden="true">*</span>
            }
          </label>
        }
        @if (inputValue() && !disabled && clearable()) {
          <button
            type="button"
            class="combobox-clear"
            (mousedown)="$event.preventDefault()"
            (click)="clear()"
            [attr.aria-label]="'Limpiar ' + (label() || placeholder())">
            <i class="fa-solid fa-xmark" aria-hidden="true"></i>
          </button>
        } @else {
          <span class="combobox-icon" aria-hidden="true"><i class="fa-solid fa-chevron-down"></i></span>
        }
      </div>

      @if (isOpen()) {
        <ul class="combobox-dropdown" role="listbox" [id]="listboxId">
          @for (option of filteredOptions(); track option.value; let i = $index) {
            <li
              [id]="optionId(i)"
              class="combobox-option"
              [class.combobox-option-highlighted]="i === highlightedIndex()"
              [class.combobox-option-selected]="option.value === value"
              [class.combobox-option-disabled]="option.disabled"
              role="option"
              [attr.aria-selected]="option.value === value"
              [attr.aria-disabled]="option.disabled ? 'true' : null"
              (mousedown)="onOptionPointerDown(option, $event)"
              (mouseenter)="highlightOption(option, i)"
            >
              <span class="combobox-option-label">{{ option.label }}</span>
              @if (option.value === value) {
                <i class="fa-solid fa-check combobox-check" aria-hidden="true"></i>
              }
            </li>
          } @empty {
            <li class="combobox-empty" role="presentation">
              <i class="fa-solid fa-magnifying-glass" aria-hidden="true"></i>
              <span role="status">Sin resultados para "{{ inputValue() }}"</span>
            </li>
          }
        </ul>
      }

      @if (error()) {
        <span class="combobox-error" [id]="errorId" role="alert">{{ error() }}</span>
      }
    </div>
  `,
  styleUrls: ['./combobox.component.css', '../../atoms/form-field/field-label.css']
})
export class ComboboxComponent implements ControlValueAccessor {
  private readonly platformId = inject(PLATFORM_ID);
  readonly inputId = 'combobox-input-' + Math.random().toString(36).slice(2, 8);
  readonly listboxId = 'combobox-list-' + Math.random().toString(36).slice(2, 8);
  readonly errorId = 'combobox-error-' + Math.random().toString(36).slice(2, 8);

  // La señal interna conserva el contrato público histórico `options` mientras se adapta su setter.
  // eslint-disable-next-line @angular-eslint/no-input-rename
  readonly entradaOpciones = input<ComboboxOption[]>([], { alias: 'options' });

  set options(value: ComboboxOption[]) {
    this._options = [...(value || [])];
    this.optionsState.set(this._options);
    this.reconcileSelection();
  }
  get options(): ComboboxOption[] {
    return this._options;
  }
  readonly label = input('');
  /** Modo de etiqueta comun: standard | floating | floating-value. */
  readonly variant = input<FieldLabelVariant>(FIELD_LABEL_VARIANT_DEFAULT);
  readonly ariaLabel = input('');
  readonly placeholder = input('Buscar...');
  // El alias permite combinar el estado del binding con el estado entregado por ControlValueAccessor.
  // eslint-disable-next-line @angular-eslint/no-input-rename
  readonly entradaDeshabilitado = input(false, { alias: 'disabled' });

  set disabled(value: boolean) {
    this.disabledState.set(value);
    if (value) this.closeOptions();
  }
  get disabled(): boolean {
    return this.disabledState();
  }
  readonly clearable = input(true);
  readonly error = input('');
  readonly required = input(false);

  readonly optionSelected = output<ComboboxOption>();
  readonly inputChange = output<string>();

  private readonly consultaInputRef = viewChild<ElementRef<HTMLInputElement>>('inputRef');
  get inputRef(): ElementRef<HTMLInputElement> | undefined {
    return this.consultaInputRef();
  }

  value: string | number | null = null;
  inputValue = signal('');
  /** El campo de texto tiene el foco del teclado. */
  readonly enfocado = signal(false);
  isOpen = signal(false);
  highlightedIndex = signal(-1);
  private _options: ComboboxOption[] = [];
  private readonly disabledState = signal(false);
  private readonly optionsState = signal<readonly ComboboxOption[]>([]);
  private readonly sincronizarOpciones = effect(() => {
    const opciones = this.entradaOpciones();
    untracked(() => {
      this.options = opciones;
    });
  });
  private readonly sincronizarDeshabilitado = effect(() => {
    const deshabilitado = this.entradaDeshabilitado();
    untracked(() => {
      this.disabled = deshabilitado;
    });
  });

  /*
    La búsqueda IGNORA LAS TILDES, y no es un adorno.

    Comparar con `toLowerCase().includes()` a secas significa que escribir
    «jose» no encuentra «José», «angelica» no encuentra «Angélica» y «bano» no
    encuentra «Baño». En un catálogo con nombres propios o descripciones en
    español, el usuario lee «no hay resultados» sobre un dato que sí existe, y
    la conclusión razonable —que el registro no está— es falsa.

    Se normaliza a los DOS lados: descomponer en NFD separa la letra de su
    diacrítico, y quitar el rango de marcas combinantes deja la letra base.
    `toLocaleLowerCase('es')` en vez del genérico porque el minusculizado
    depende del idioma.

    También se busca en `description` y `keywords`: un catálogo suele tener
    sinónimos que el usuario teclea antes que el nombre oficial.
  */
  filteredOptions = computed(() => {
    const query = normalizeSearch(this.inputValue());
    const options = this.optionsState();
    if (!query) return options;
    return options.filter(option =>
      normalizeSearch(
        [option.label, option.description, ...(option.keywords ?? [])]
          .filter((part): part is string => typeof part === 'string' && part.length > 0)
          .join(' '),
      ).includes(query),
    );
  });

  protected readonly tieneEtiqueta = computed(() => this.label().length > 0);
  protected readonly flotante = computed(() =>
    esEtiquetaFlotante(this.variant(), this.tieneEtiqueta()),
  );
  protected readonly elevada = computed(() =>
    esEtiquetaElevada(this.variant(), this.tieneEtiqueta(), this.enfocado(), this.inputValue().length > 0),
  );
  protected readonly marcador = computed(() =>
    esMarcadorVisible(this.variant(), this.tieneEtiqueta(), this.elevada())
      ? this.placeholder() || null
      : null,
  );

  activeOptionId = computed(() => {
    const index = this.highlightedIndex();
    return this.isOpen() && index >= 0 ? this.optionId(index) : null;
  });

  private onChange: (v: string | number | null) => void = () => {};
  private onTouched: () => void = () => {};

  writeValue(val: string | number | null): void {
    this.value = val;
    // Un reset del formulario (null) tambien tiene que vaciar el texto que ya se ve:
    // reconcileSelection() no hace nada con null para no borrar lo que la persona teclea.
    if (val === null) this.inputValue.set('');
    this.reconcileSelection();
  }

  registerOnChange(fn: (v: string | number | null) => void): void { this.onChange = fn; }
  registerOnTouched(fn: () => void): void { this.onTouched = fn; }
  setDisabledState(isDisabled: boolean): void { this.disabled = isDisabled; }

  onInput(event: Event): void {
    const val = (event.target as HTMLInputElement).value;
    this.inputValue.set(val);
    this.isOpen.set(true);
    this.highlightedIndex.set(-1);
    this.inputChange.emit(val);

    const selected = this.optionsState().find(option => option.value === this.value);
    if (this.value !== null && (!selected || selected.label !== val)) {
      this.value = null;
      this.onChange(null);
    }
  }

  onFocus(): void {
    if (this.disabled) return;
    this.enfocado.set(true);
    this.isOpen.set(true);
    this.ensureEnabledHighlight();
  }

  onBlur(): void {
    this.enfocado.set(false);
    this.onTouched();
    setTimeout(() => this.isOpen.set(false), 150);
  }

  onKeydown(event: KeyboardEvent): void {
    if (this.disabled) return;
    const opts = this.filteredOptions();
    switch (event.key) {
      case 'ArrowDown':
        event.preventDefault();
        this.isOpen.set(true);
        this.highlightedIndex.set(this.nextEnabledIndex(opts, this.highlightedIndex(), 1));
        break;
      case 'ArrowUp':
        event.preventDefault();
        this.isOpen.set(true);
        this.highlightedIndex.set(this.nextEnabledIndex(opts, this.highlightedIndex(), -1));
        break;
      case 'Enter':
        event.preventDefault();
        if (this.highlightedIndex() >= 0 && opts[this.highlightedIndex()]) {
          this.selectOption(opts[this.highlightedIndex()]);
        }
        break;
      case 'Escape':
        this.isOpen.set(false);
        break;
    }
  }

  selectOption(option: ComboboxOption): void {
    if (this.disabled || option.disabled) return;
    this.value = option.value;
    this.inputValue.set(option.label);
    this.closeOptions();
    this.onChange(option.value);
    this.onTouched();
    this.optionSelected.emit(option);
  }

  clear(): void {
    if (this.disabled) return;
    this.value = null;
    this.inputValue.set('');
    this.closeOptions();
    this.onChange(null);
    this.onTouched();
    this.inputChange.emit('');
    if (isPlatformBrowser(this.platformId)) {
      this.inputRef?.nativeElement.focus();
    }
  }

  optionId(index: number): string {
    return `${this.listboxId}-option-${index}`;
  }

  onOptionPointerDown(option: ComboboxOption, event: MouseEvent): void {
    event.preventDefault();
    this.selectOption(option);
  }

  highlightOption(option: ComboboxOption, index: number): void {
    if (!option.disabled) this.highlightedIndex.set(index);
  }

  private reconcileSelection(): void {
    if (this.value === null) return;
    const option = this.optionsState().find(candidate => candidate.value === this.value);
    this.inputValue.set(option?.label || '');
    this.ensureEnabledHighlight();
  }

  private ensureEnabledHighlight(): void {
    if (!this.isOpen()) return;
    const options = this.filteredOptions();
    const current = this.highlightedIndex();
    if (current >= 0 && options[current] && !options[current].disabled) return;
    const selected = options.findIndex(option => option.value === this.value && !option.disabled);
    this.highlightedIndex.set(selected >= 0 ? selected : this.nextEnabledIndex(options, -1, 1));
  }

  private nextEnabledIndex(
    options: readonly ComboboxOption[],
    current: number,
    direction: 1 | -1
  ): number {
    let index = current;
    if (index < 0) index = direction === 1 ? -1 : options.length;
    for (index += direction; index >= 0 && index < options.length; index += direction) {
      if (!options[index].disabled) return index;
    }
    return current >= 0 && options[current] && !options[current].disabled ? current : -1;
  }

  private closeOptions(): void {
    this.isOpen.set(false);
    this.highlightedIndex.set(-1);
  }
}

import { Component, ChangeDetectionStrategy, input } from '@angular/core';
import { VariablesCssDirective } from '../../directives/variables-css.directive';

export interface ComparisonChartItem {
  label: string;
  seriesA: number;
  seriesB: number;
  seriesAWidth: number;
  seriesBWidth: number;
}

@Component({
  selector: 'app-comparison-chart',
  standalone: true,
  imports: [VariablesCssDirective],
  template: `
    <div class="chart-legend" aria-label="Leyenda del gráfico">
      <span><i class="chart-legend__dot chart-legend__dot--a"></i>{{ labelA() }}</span>
      <span><i class="chart-legend__dot chart-legend__dot--b"></i>{{ labelB() }}</span>
    </div>
    
    <ol class="monthly-chart" [attr.aria-label]="ariaLabel()">
      @for (item of items(); track item.label) {
        <li>
          <strong class="monthly-chart__month">{{ item.label }}</strong>
          <div class="monthly-chart__plot" aria-hidden="true">
            <span class="monthly-chart__track">
              <i class="monthly-chart__bar monthly-chart__bar--a" [appVariablesCss]="{'--comparison-width': item.seriesAWidth + '%'}"></i>
            </span>
            <span class="monthly-chart__track">
              <i class="monthly-chart__bar monthly-chart__bar--b" [appVariablesCss]="{'--comparison-width': item.seriesBWidth + '%'}"></i>
            </span>
          </div>
          <div class="monthly-chart__values">
            <span>{{ prefixA() }} <strong>{{ formatValue(item.seriesA) }}</strong></span>
            <span>{{ prefixB() }} <strong>{{ formatValue(item.seriesB) }}</strong></span>
          </div>
        </li>
      }
    </ol>
  `,
  styleUrl: './comparison-chart.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ComparisonChartComponent {
  readonly items = input<ComparisonChartItem[]>([]);
  readonly labelA = input('Ingresos');
  readonly labelB = input('Egresos');
  readonly prefixA = input('Ing.');
  readonly prefixB = input('Egr.');
  readonly ariaLabel = input('Evolución comparativa');
  readonly formatType = input<'currency' | 'number'>('currency');

