interface InputSelectionSnapshot {
  kind: 'input';
  start: number;
  end: number;
  direction: 'forward' | 'backward' | 'none';
  selectionSupported: boolean;
  textLength: number;
  revision: number;
}

interface EditableSelectionSnapshot {
  kind: 'editable';
  range: Range | null;
  textLength: number;
  revision: number;
