const TEXT_INPUT_TYPES = new Set(['password', 'search', 'tel', 'text', 'url']);
const CONTEXT_MENU_POLICY_ATTRIBUTE = 'data-context-menu-policy';
const TEXT_EDIT_POLICY = 'text-edit';
