    }
    if (
      val.includes('incidencia') ||
      val.includes('degradado') ||
      val.includes('vencid') ||
      val.includes('mora') ||
      val.includes('atrasad') ||
      val.includes('parcial') ||
      val.includes('pendiente') ||
      val.includes('pending') ||
      val.includes('ausente') ||
      val.includes('revisión') ||
      val.includes('revision') ||
