    if (!column.sortable) {
      return;
    }

    const current = this.activeSort();
    let direction: DataTableSortDirection = 'asc';
    if (current?.key === column.key && current.direction === 'asc') {
      direction = 'desc';
    } else if (current?.key === column.key && current.direction === 'desc') {
      direction = null;
    }

