          [class.fl-label--disabled]="isDisabled()"
          [id]="labelId"
        >{{ label() }}</span>
      }
      <button type="button"
        class="dropdown-trigger"
        [attr.aria-labelledby]="label() ? labelId : null"
        [attr.aria-label]="label() ? null : ariaLabel()"
        (focus)="triggerFocused.set(true)"
        (blur)="triggerFocused.set(false)"
