  private readonly capturedClipboardListener = (event: ClipboardEvent) =>
    this.onProtectedClipboardEvent(event);
  private readonly capturedBeforeInputListener = (event: InputEvent) =>
    this.onProtectedBeforeInput(event);
  private readonly capturedDragStartListener = (event: DragEvent) =>
    this.onProtectedDragStart(event);
  private readonly capturedPointerDownListener = (event: PointerEvent) =>
    this.onDocumentPointerDown(event);
  private readonly capturedInputListener = (event: Event) => this.onControlInput(event);
  private readonly capturedFocusInListener = (event: FocusEvent) => this.onDocumentFocusIn(event);

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['disabled'] && this.disabled() && this.isOpen()) {
      this.closeMenu();
      return;
    }
    if (!changes['disabledActions'] || !this.isOpen()) {
      return;
    }
    const current = this.activeAction();
    const next =
      current && !this.isActionDisabled(current) ? current : (this.navigationActions()[0] ?? null);
    this.activeAction.set(next);
    if (!this.target) {
      return;
    }
    if (next) {
      this.target.setAttribute('aria-activedescendant', this.itemId(next));
    } else {
      this.target.removeAttribute('aria-activedescendant');
    }
  }

  ngOnInit(): void {
    const instances = ContextMenuComponent.documentInstances.get(this.document) ?? [];
    instances.push(this);
    ContextMenuComponent.documentInstances.set(this.document, instances);
    this.registered = true;
    this.document.addEventListener('scroll', this.capturedScrollListener, true);
    this.document.addEventListener('contextmenu', this.capturedContextMenuListener, true);
    this.document.addEventListener('keydown', this.capturedKeydownListener, true);
    this.document.addEventListener('copy', this.capturedClipboardListener, true);
    this.document.addEventListener('cut', this.capturedClipboardListener, true);
    this.document.addEventListener('beforeinput', this.capturedBeforeInputListener, true);
    this.document.addEventListener('dragstart', this.capturedDragStartListener, true);
    this.document.addEventListener('pointerdown', this.capturedPointerDownListener, true);
    this.document.addEventListener('input', this.capturedInputListener, true);
    this.document.addEventListener('focusin', this.capturedFocusInListener, true);
    const visualViewport = this.document.defaultView?.visualViewport;
    visualViewport?.addEventListener('scroll', this.capturedScrollListener);
    visualViewport?.addEventListener('resize', this.visualViewportResizeListener);
  }

  ngOnDestroy(): void {
    if (this.registered) {
      this.document.removeEventListener('scroll', this.capturedScrollListener, true);
      this.document.removeEventListener('contextmenu', this.capturedContextMenuListener, true);
      this.document.removeEventListener('keydown', this.capturedKeydownListener, true);
      this.document.removeEventListener('copy', this.capturedClipboardListener, true);
      this.document.removeEventListener('cut', this.capturedClipboardListener, true);
      this.document.removeEventListener('beforeinput', this.capturedBeforeInputListener, true);
      this.document.removeEventListener('dragstart', this.capturedDragStartListener, true);
      this.document.removeEventListener('pointerdown', this.capturedPointerDownListener, true);
      this.document.removeEventListener('input', this.capturedInputListener, true);
      this.document.removeEventListener('focusin', this.capturedFocusInListener, true);
      const visualViewport = this.document.defaultView?.visualViewport;
      visualViewport?.removeEventListener('scroll', this.capturedScrollListener);
      visualViewport?.removeEventListener('resize', this.visualViewportResizeListener);
      const instances = ContextMenuComponent.documentInstances.get(this.document) ?? [];
      const remaining = instances.filter((instance) => instance !== this);
      if (remaining.length === 0) {
        ContextMenuComponent.documentInstances.delete(this.document);
      } else {
        ContextMenuComponent.documentInstances.set(this.document, remaining);
      }
      this.registered = false;
    }
    this.closeMenu();
  }

  itemId(action: ContextMenuAction): string {
    return `${this.menuId}-${action}`;
  }

  setActiveAction(action: ContextMenuAction): void {
    if (this.menuItems.some((item) => item.action === action) && !this.isActionDisabled(action)) {
      this.activeAction.set(action);
      this.target?.setAttribute('aria-activedescendant', this.itemId(action));
    }
  }

  preserveTargetFocus(event: PointerEvent): void {
    event.preventDefault();
  }

  onContextMenu(event: MouseEvent): void {
    if (!this.isDocumentController()) {
      return;
    }
    if (this.menuRef?.nativeElement.contains(event.target as Node)) {
      event.preventDefault();
      return;
    }

    if (this.disabled()) {
      this.closeMenu();
      return;
    }

    const target = this.resolveTextControl(event.target);
    if (!target) {
      this.closeMenu();
      return;
    }

    event.preventDefault();
    event.stopPropagation();
    const point = this.resolveOpeningPoint(event.clientX, event.clientY, target);
    this.openMenu(target, point.left, point.top);
  }

  onHostKeydown(event: KeyboardEvent): void {
    if (!this.isDocumentController()) {
      return;
    }
    const clipboardKey = event.key.toLowerCase();
    if (
      this.isProtectedContext(event.target) &&
      (event.ctrlKey || event.metaKey) &&
      (clipboardKey === 'c' || clipboardKey === 'x')
    ) {
      this.blockEvent(event);
      return;
    }

    if (this.isOpen()) {
      if (this.isMenuInteractionKey(event.key)) {
        this.onMenuKeydown(event);
        return;
      }
      if (this.isEditingKey(event)) {
        this.closeMenu();
        return;
      }
      return;
    }

    const isContextMenuKey = event.key === 'ContextMenu';
    const isShiftF10 = event.shiftKey && event.key === 'F10';
    if (this.disabled() || (!isContextMenuKey && !isShiftF10)) {
      return;
    }

    const target = this.resolveTextControl(event.target);
    if (!target) {
      return;
    }

    event.preventDefault();
    event.stopPropagation();
    const rect = target.getBoundingClientRect();
    this.openMenu(target, rect.left, rect.bottom);
  }

  onProtectedClipboardEvent(event: ClipboardEvent): void {
    if (!this.isDocumentController()) {
      return;
    }
    if (this.isProtectedContext(event.target)) {
      this.blockEvent(event);
      return;
    }
    if (this.isOpen() && this.isCurrentTextTarget(event.target)) {
      this.closeMenu();
    }
  }

  onProtectedBeforeInput(event: InputEvent): void {
    if (!this.isDocumentController()) {
      return;
    }
    if (event.inputType === 'deleteByCut' && this.isProtectedContext(event.target)) {
      this.blockEvent(event);
      return;
    }
    if (this.isOpen() && this.isCurrentTextTarget(event.target)) {
      this.closeMenu();
    }
  }

  onProtectedDragStart(event: DragEvent): void {
    if (this.isDocumentController() && this.isProtectedContext(event.target)) {
      this.blockEvent(event);
    }
  }

  onControlInput(event: Event): void {
    if (!this.isDocumentController()) {
      return;
    }
    const target = this.resolveTextControl(event.target);
    if (target) {
      if (this.isOpen() && target === this.target) {
        this.closeMenu();
      }
      this.controlRevisions.set(target, this.controlRevision(target) + 1);
    }
  }

  onDocumentPointerDown(event: PointerEvent): void {
    if (!this.isDocumentController()) {
      return;
    }

    if (!this.isOpen()) {
      if (this.pendingOperationGeneration !== null) {
        this.generation += 1;
        this.pendingOperationGeneration = null;
      }
      return;
    }

    const node = event.target as Node | null;
    if (node && !this.menuRef?.nativeElement.contains(node)) {
      this.closeMenu();
    }
  }

  onDocumentFocusIn(event: FocusEvent): void {
    if (!this.isDocumentController() || !this.isOpen()) {
      return;
    }
    const node = event.target as Node | null;
    if (
      node &&
      node !== this.target &&
      !this.target?.contains(node) &&
      !this.menuRef?.nativeElement.contains(node)
    ) {
      this.closeMenu();
    }
  }

  @HostListener('window:resize')
  onViewportResize(): void {
    if (this.isDocumentController() && this.isOpen()) {
      this.repositionMenu();
    }
  }

  suppressNestedContextMenu(event: MouseEvent): void {
    event.preventDefault();
    event.stopPropagation();
  }

  isActionDisabled(action: ContextMenuAction): boolean {
    if (this.disabled() || this.disabledActions().includes(action) || !this.target || !this.selection) {
      return true;
    }

    switch (action) {
      case 'cut':
        return (
          this.hasPasteOnlyPolicy(this.target) ||
          !this.isWritable(this.target) ||
          !this.hasSelectedText(this.selection)
        );
      case 'copy':
        return this.hasPasteOnlyPolicy(this.target) || !this.hasSelectedText(this.selection);
      case 'paste':
        return !this.isWritable(this.target);
      case 'select-all':
        return this.selection.textLength === 0;
    }
  }

  async executeAction(action: ContextMenuAction): Promise<void> {
    const target = this.target;
    const selection = this.selection;
    if (!target || !selection || this.isActionDisabled(action)) {
      return;
    }

    const operationGeneration = this.generation;
    let detached = false;

    try {
      this.assertOperationTarget(target, selection, operationGeneration);
      this.pendingOperationGeneration = operationGeneration;
      this.restoreSelection(target, selection);
      this.detachMenuForOperation();
      detached = true;
      switch (action) {
        case 'cut':
          await this.cut(target, selection, operationGeneration);
          break;
        case 'copy':
          await this.copy(target, selection);
          break;
        case 'paste':
          await this.paste(target, selection, operationGeneration);
          break;
        case 'select-all':
          this.selectAll(target);
          break;
      }
      this.actionSelected.emit(action);
      if (operationGeneration === this.generation) {
        this.feedback.set(this.successFeedback(action));
      }
    } catch (reason: unknown) {
      if (!detached && this.target === target) {
        this.closeMenu();
      }
      const failureReason = this.failureReason(reason);
      this.actionError.emit({ action, reason: failureReason });
      if (operationGeneration === this.generation) {
        this.feedback.set(this.failureFeedback(failureReason));
      }
    } finally {
      if (this.pendingOperationGeneration === operationGeneration) {
        this.pendingOperationGeneration = null;
      }
      this.releaseSelection(selection);
    }
  }

  onMenuKeydown(event: KeyboardEvent): void {
    if (event.key === 'Escape') {
      event.preventDefault();
      event.stopPropagation();
      this.closeMenu(true);
      return;
    }

    if (event.key === 'Tab') {
      this.closeMenu();
      return;
    }

    const actions = this.navigationActions();
    if (actions.length === 0) {
      return;
    }

    const activeIndex = actions.indexOf(this.activeAction() as ContextMenuAction);
    let nextIndex: number | null = null;

    switch (event.key) {
      case 'Enter':
      case ' ':
        event.preventDefault();
        event.stopPropagation();
        void this.executeAction(actions[activeIndex < 0 ? 0 : activeIndex]!);
        return;
      case 'ArrowDown':
      case 'ArrowRight':
        nextIndex = activeIndex < 0 ? 0 : (activeIndex + 1) % actions.length;
        break;
      case 'ArrowUp':
      case 'ArrowLeft':
        nextIndex = activeIndex <= 0 ? actions.length - 1 : activeIndex - 1;
        break;
      case 'Home':
        nextIndex = 0;
        break;
      case 'End':
        nextIndex = actions.length - 1;
        break;
    }

    if (nextIndex !== null) {
      event.preventDefault();
      event.stopPropagation();
      const action = actions[nextIndex];
      if (action) {
        this.setActiveAction(action);
      }
    }
  }

  /** Recalcula la posición con las dimensiones reales del menú. */
  repositionMenu(): void {
    const menu = this.menuRef?.nativeElement;
    const view = this.document.defaultView;
    if (!menu || !view) {
      return;
    }

    const rect = menu.getBoundingClientRect();
    const visualViewport = view.visualViewport;
    const viewportLeft = visualViewport?.offsetLeft ?? 0;
    const viewportTop = visualViewport?.offsetTop ?? 0;
    const viewportWidth =
      visualViewport?.width || this.document.documentElement.clientWidth || view.innerWidth;
    const viewportHeight =
      visualViewport?.height || this.document.documentElement.clientHeight || view.innerHeight;
    const width = rect.width || menu.offsetWidth;
    const height = rect.height || menu.offsetHeight;
    const minLeft = viewportLeft + VIEWPORT_PADDING;
    const minTop = viewportTop + VIEWPORT_PADDING;
    const maxLeft = Math.max(minLeft, viewportLeft + viewportWidth - width - VIEWPORT_PADDING);
    const maxTop = Math.max(minTop, viewportTop + viewportHeight - height - VIEWPORT_PADDING);
    const left = this.clamp(this.requestedPosition.left, minLeft, maxLeft);
    const top = this.clamp(this.requestedPosition.top, minTop, maxTop);

    menu.style.left = `${left}px`;
    menu.style.top = `${top}px`;
    this.position.set({ left, top });
  }

  private openMenu(target: TextControl, left: number, top: number): void {
    if (this.isOpen() || this.target || this.selection) {
      this.closeMenu();
    }
    const openingGeneration = ++this.generation;
    this.target = target;
    this.selection = this.captureSelection(target);
    this.requestedPosition = { left, top };
    this.position.set({
      left: Math.max(VIEWPORT_PADDING, left),
      top: Math.max(VIEWPORT_PADDING, top),
    });
    this.isOpen.set(true);
    this.feedback.set('Menú de edición abierto.');
    const firstAction = this.navigationActions()[0] ?? null;
    this.activeAction.set(firstAction);
    this.attachTargetAria(target, firstAction);

    this.scheduleMenuLayout(openingGeneration);
  }

  private closeMenu(restoreFocus = false, invalidateGeneration = true): void {
    const target = this.target;
    const selection = this.selection;
    if (restoreFocus && target && selection) {
      this.restoreSelection(target, selection);
    }
    this.restoreTargetAria(target);
    this.cancelMenuLayout();
    this.isOpen.set(false);
    this.activeAction.set(null);
    this.target = null;
    this.selection = null;
    this.releaseSelection(selection);
    if (invalidateGeneration) {
      this.generation += 1;
      this.pendingOperationGeneration = null;
    }
  }

  private detachMenuForOperation(): void {
    this.restoreTargetAria(this.target);
    this.cancelMenuLayout();
    this.isOpen.set(false);
    this.activeAction.set(null);
    this.target = null;
    this.selection = null;
  }

  private navigationActions(): ContextMenuAction[] {
    return this.menuItems
      .map((item) => item.action)
      .filter((action) => !this.isActionDisabled(action));
  }

  private scheduleMenuLayout(openingGeneration: number, retries = 1): void {
    this.cancelMenuLayout();
    const view = this.document.defaultView;
    if (!view?.requestAnimationFrame) {
      queueMicrotask(() => this.repositionMenu());
      return;
    }
    this.layoutFrame = view.requestAnimationFrame(() => {
      this.layoutFrame = null;
      if (!this.isOpen() || openingGeneration !== this.generation) {
        return;
      }
      if (!this.menuRef && retries > 0) {
        this.scheduleMenuLayout(openingGeneration, retries - 1);
        return;
      }
      this.repositionMenu();
    });
  }

  private cancelMenuLayout(): void {
    if (this.layoutFrame === null) {
      return;
    }
    this.document.defaultView?.cancelAnimationFrame(this.layoutFrame);
    this.layoutFrame = null;
  }

  private resolveTextControl(eventTarget: EventTarget | null): TextControl | null {
    if (!(eventTarget instanceof Element)) {
      return null;
    }

    const policyElement = eventTarget.closest<HTMLElement>(`[${CONTEXT_MENU_POLICY_ATTRIBUTE}]`);
    const policy = policyElement?.getAttribute(CONTEXT_MENU_POLICY_ATTRIBUTE);
    if (policy === NATIVE_POLICY) {
      return null;
    }
    const explicitlyManaged = policy === TEXT_EDIT_POLICY;

    const nativeControl = eventTarget.closest<HTMLInputElement | HTMLTextAreaElement>(
      'textarea, input',
    );
    if (nativeControl?.isConnected) {
      if (nativeControl.disabled) {
        return null;
      }
      if (nativeControl instanceof HTMLInputElement && !TEXT_INPUT_TYPES.has(nativeControl.type)) {
        return null;
      }
      if (
        !explicitlyManaged &&
        (nativeControl.getAttribute('role') === 'combobox' ||
          nativeControl.hasAttribute('aria-controls') ||
          nativeControl.hasAttribute('aria-haspopup'))
      ) {
        return null;
      }
      return nativeControl;
    }

    let candidate: Element | null = eventTarget;
    while (candidate?.isConnected) {
      if (candidate.hasAttribute('contenteditable')) {
        const mode = (candidate.getAttribute('contenteditable') ?? '').toLowerCase();
        if (mode === 'false') {
          return null;
        }
        if (mode === '' || mode === 'true' || mode === 'plaintext-only') {
          return explicitlyManaged ? (candidate as HTMLElement) : null;
        }
      }
      candidate = candidate.parentElement;
    }
    return null;
  }

  private isDocumentController(): boolean {
    if (!this.registered) {
      return false;
    }
    const instances = ContextMenuComponent.documentInstances.get(this.document) ?? [];
    const controller = instances.find((instance) => instance.registered);
    if (controller !== this && this.isOpen()) {
      this.closeMenu();
    }
    if (controller !== this && this.pendingOperationGeneration !== null) {
      this.generation += 1;
      this.pendingOperationGeneration = null;
    }
    return controller === this;
  }

  private hasPasteOnlyPolicy(eventTarget: EventTarget | null): boolean {
    if (!(eventTarget instanceof Element)) {
      return false;
    }

    const passwordInput = eventTarget.closest<HTMLInputElement>('input[type="password"]');
    if (passwordInput?.isConnected) {
      return true;
    }

    const protectedTarget = eventTarget.closest<HTMLElement>(
      '[data-clipboard-policy="paste-only"]',
    );
    return Boolean(protectedTarget?.isConnected);
  }

  private isProtectedContext(eventTarget: EventTarget | null): boolean {
    return (
      this.hasPasteOnlyPolicy(eventTarget) ||
      Boolean(this.isOpen() && this.target && this.hasPasteOnlyPolicy(this.target))
    );
  }

  private isCurrentTextTarget(eventTarget: EventTarget | null): boolean {
    return (
      eventTarget instanceof Node &&
      Boolean(this.target && (eventTarget === this.target || this.target.contains(eventTarget)))
    );
  }

  private isEditingKey(event: KeyboardEvent): boolean {
    const key = event.key.toLowerCase();
    if (key === 'backspace' || key === 'delete' || event.isComposing) {
      return true;
    }
    if ((event.ctrlKey || event.metaKey) && ['a', 'c', 'v', 'x', 'y', 'z'].includes(key)) {
      return true;
    }
    return event.key.length === 1 && !event.metaKey && (!event.ctrlKey || event.altKey);
  }

  private isMenuInteractionKey(key: string): boolean {
    return [
      'Escape',
      'Tab',
      'ArrowDown',
      'ArrowRight',
      'ArrowUp',
      'ArrowLeft',
      'Home',
      'End',
      'Enter',
      ' ',
    ].includes(key);
  }

  private blockEvent(event: Event): void {
    event.preventDefault();
    event.stopImmediatePropagation();
  }

  private resolveOpeningPoint(
    clientX: number,
    clientY: number,
    target: TextControl,
  ): { left: number; top: number } {
    if (clientX !== 0 || clientY !== 0) {
      return { left: clientX, top: clientY };
    }

    const rect = target.getBoundingClientRect();
    return { left: rect.left, top: rect.bottom };
  }

  private captureSelection(target: TextControl): SelectionSnapshot {
    if (target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement) {
      const selectionSupported = target.selectionStart !== null && target.selectionEnd !== null;
      const start = target.selectionStart ?? target.value.length;
      const end = target.selectionEnd ?? start;
      return {
        kind: 'input',
        start,
        end,
        direction: target.selectionDirection ?? 'none',
        selectionSupported,
        textLength: target.value.length,
        revision: this.controlRevision(target),
      };
    }

    const selection = this.document.defaultView?.getSelection();
    const activeRange = selection && selection.rangeCount > 0 ? selection.getRangeAt(0) : null;
    const range =
      activeRange && target.contains(activeRange.commonAncestorContainer)
        ? activeRange.cloneRange()
        : null;
    return {
      kind: 'editable',
      range,
      textLength: target.textContent?.length ?? 0,
      revision: this.controlRevision(target),
    };
  }

  private restoreSelection(target: TextControl, snapshot: SelectionSnapshot): void {
    if (!target.isConnected) {
      return;
    }
    this.focusTarget(target);
    if (snapshot.kind === 'input') {
      if (target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement) {
        if (!snapshot.selectionSupported) {
          return;
        }
        try {
          target.setSelectionRange(snapshot.start, snapshot.end, snapshot.direction);
        } catch {
          return;
        }
      }
      return;
    }

    if (!snapshot.range || !snapshot.range.startContainer.isConnected) {
      return;
    }
    const selection = this.document.defaultView?.getSelection();
    selection?.removeAllRanges();
    selection?.addRange(snapshot.range);
  }

  private hasSelectedText(snapshot: SelectionSnapshot): boolean {
    return snapshot.kind === 'input'
      ? snapshot.end > snapshot.start
      : Boolean(snapshot.range && !snapshot.range.collapsed);
  }

  private selectedText(target: TextControl, snapshot: SelectionSnapshot): string {
    if (snapshot.kind === 'input') {
      return target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement
        ? target.value.slice(snapshot.start, snapshot.end)
        : '';
    }
    return snapshot.range?.toString() ?? '';
  }

  private isWritable(target: TextControl): boolean {
    if (target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement) {
      return !target.disabled && !target.readOnly;
    }
    return target.getAttribute('contenteditable') !== 'false';
  }

  private attachTargetAria(target: TextControl, activeAction: ContextMenuAction | null): void {
    this.targetAria = {
      controls: target.getAttribute('aria-controls'),
      expanded: target.getAttribute('aria-expanded'),
      haspopup: target.getAttribute('aria-haspopup'),
      activeDescendant: target.getAttribute('aria-activedescendant'),
    };
    target.setAttribute('aria-controls', this.menuId);
    target.setAttribute('aria-expanded', 'true');
    target.setAttribute('aria-haspopup', 'menu');
    if (activeAction) {
      target.setAttribute('aria-activedescendant', this.itemId(activeAction));
    } else {
      target.removeAttribute('aria-activedescendant');
    }
  }

  private restoreTargetAria(target: TextControl | null): void {
    const snapshot = this.targetAria;
    this.targetAria = null;
    if (!target || !snapshot) {
      return;
    }
    this.restoreAttribute(target, 'aria-controls', snapshot.controls);
    this.restoreAttribute(target, 'aria-expanded', snapshot.expanded);
    this.restoreAttribute(target, 'aria-haspopup', snapshot.haspopup);
    this.restoreAttribute(target, 'aria-activedescendant', snapshot.activeDescendant);
  }

  private restoreAttribute(target: HTMLElement, name: string, value: string | null): void {
    if (value === null) {
      target.removeAttribute(name);
    } else {
      target.setAttribute(name, value);
    }
  }

  private releaseSelection(snapshot: SelectionSnapshot | null): void {
    if (snapshot?.kind === 'editable') {
      snapshot.range?.detach();
      snapshot.range = null;
    }
  }

  private async copy(target: TextControl, selection: SelectionSnapshot): Promise<void> {
    if (this.executeDocumentCommand('copy')) {
      return;
    }
    const clipboard = this.resolveBrowserClipboard();
    if (!clipboard) {
      throw new ContextMenuOperationError('clipboard-unavailable');
    }
    let text = this.selectedText(target, selection);
    try {
      await clipboard.writeText(text);
    } catch {
      throw new ContextMenuOperationError('clipboard-denied');
    } finally {
      text = '';
    }
  }

  private async cut(
    target: TextControl,
    selection: SelectionSnapshot,
    operationGeneration: number,
  ): Promise<void> {
    if (this.executeDocumentCommand('cut')) {
      return;
    }
    const clipboard = this.resolveBrowserClipboard();
    if (!clipboard) {
      throw new ContextMenuOperationError('clipboard-unavailable');
    }
    let text = this.selectedText(target, selection);
    try {
      await clipboard.writeText(text);
    } catch {
      throw new ContextMenuOperationError('clipboard-denied');
    } finally {
      text = '';
    }
    this.assertOperationTarget(target, selection, operationGeneration);
    if (!this.deleteSelection(target, selection)) {
      throw new ContextMenuOperationError('operation-failed');
    }
  }

  private async paste(
    target: TextControl,
    selection: SelectionSnapshot,
    operationGeneration: number,
  ): Promise<void> {
    const clipboard = this.resolveBrowserClipboard();
    if (!clipboard) {
      if (this.executeDocumentCommand('paste')) {
        return;
      }
      throw new ContextMenuOperationError('clipboard-unavailable');
    }

    let text = '';
    try {
      text = await clipboard.readText();
    } catch {
      throw new ContextMenuOperationError('clipboard-denied');
    }
    try {
      this.assertOperationTarget(target, selection, operationGeneration);
      if (!this.insertText(target, selection, text)) {
        throw new ContextMenuOperationError('operation-failed');
      }
    } finally {
      text = '';
    }
  }

  private deleteSelection(target: TextControl, selection: SelectionSnapshot): boolean {
    if (!this.dispatchBeforeInputEvent(target, 'deleteByCut')) {
      return false;
    }
    if (selection.kind === 'input') {
      if (target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement) {
        if (selection.selectionSupported) {
          target.setRangeText('', selection.start, selection.end, 'start');
        } else {
          target.value = target.value.slice(0, selection.start) + target.value.slice(selection.end);
        }
        this.dispatchInputEvent(target, 'deleteByCut');
        return true;
      }
      return false;
    }

    if (!selection.range) {
      return false;
    }
    selection.range.deleteContents();
    this.dispatchInputEvent(target, 'deleteByCut');
    return true;
  }

  private insertText(
    target: TextControl,
    selection: SelectionSnapshot,
    clipboardText: string,
  ): boolean {
    const text = this.truncatePasteText(target, selection, clipboardText);
    if (text.length === 0 && !this.hasSelectedText(selection)) {
      return true;
    }
    if (!this.dispatchBeforeInputEvent(target, 'insertFromPaste', text)) {
      return false;
    }
    if (selection.kind === 'input') {
      if (target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement) {
        if (selection.selectionSupported) {
          target.setRangeText(text, selection.start, selection.end, 'end');
        } else {
          target.value =
            target.value.slice(0, selection.start) + text + target.value.slice(selection.end);
        }
        this.dispatchInputEvent(target, 'insertFromPaste', text);
        return true;
      }
      return false;
    }

    const range = selection.range ?? this.document.createRange();
    if (!selection.range) {
      range.selectNodeContents(target);
      range.collapse(false);
    } else {
      range.deleteContents();
    }
    const textNode = this.document.createTextNode(text);
    range.insertNode(textNode);
    range.setStartAfter(textNode);
    range.collapse(true);
    const browserSelection = this.document.defaultView?.getSelection();
    browserSelection?.removeAllRanges();
    browserSelection?.addRange(range);
    this.dispatchInputEvent(target, 'insertFromPaste', text);
    return true;
  }

  private selectAll(target: TextControl): void {
    this.focusTarget(target);
    if (target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement) {
      target.select();
      return;
    }

    const range = this.document.createRange();
    range.selectNodeContents(target);
    const selection = this.document.defaultView?.getSelection();
    selection?.removeAllRanges();
    selection?.addRange(range);
  }

  private resolveBrowserClipboard(): Clipboard | null {
    try {
      return this.document.defaultView?.navigator.clipboard ?? null;
    } catch {
      return null;
    }
  }

  private focusTarget(target: TextControl): void {
    try {
      target.focus({ preventScroll: true });
    } catch {
      target.focus();
    }
  }

  private executeDocumentCommand(command: 'copy' | 'cut' | 'paste'): boolean {
    try {
      return typeof this.document.execCommand === 'function' && this.document.execCommand(command);
    } catch {
      return false;
    }
  }

  private dispatchBeforeInputEvent(
    target: TextControl,
    inputType: 'deleteByCut' | 'insertFromPaste',
    data: string | null = null,
  ): boolean {
    const InputEventConstructor = this.document.defaultView?.InputEvent;
    const event = InputEventConstructor
      ? new InputEventConstructor('beforeinput', {
          bubbles: true,
          cancelable: true,
          data,
          inputType,
        })
      : new Event('beforeinput', { bubbles: true, cancelable: true });
    return target.dispatchEvent(event);
  }

  private dispatchInputEvent(
    target: TextControl,
    inputType: 'deleteByCut' | 'insertFromPaste',
    data: string | null = null,
  ): void {
    const InputEventConstructor = this.document.defaultView?.InputEvent;
    const event = InputEventConstructor
      ? new InputEventConstructor('input', { bubbles: true, data, inputType })
      : new Event('input', { bubbles: true });
    target.dispatchEvent(event);
  }

  private truncatePasteText(
    target: TextControl,
    selection: SelectionSnapshot,
    text: string,
  ): string {
    const normalizedText =
      target instanceof HTMLInputElement ? text.replace(/\r\n?|\n/g, ' ') : text;
    if (
      selection.kind !== 'input' ||
      !(target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement) ||
      target.maxLength < 0
    ) {
      return normalizedText;
    }
    const selectedLength = selection.end - selection.start;
    const capacity = Math.max(0, target.maxLength - (target.value.length - selectedLength));
    return normalizedText.slice(0, capacity);
  }

  private assertOperationTarget(
    target: TextControl,
    selection: SelectionSnapshot,
    operationGeneration: number,
  ): void {
    const activeElement = this.document.activeElement;
    if (
      operationGeneration !== this.generation ||
      !target.isConnected ||
      (activeElement !== target && !target.contains(activeElement)) ||
      selection.revision !== this.controlRevision(target)
    ) {
      throw new ContextMenuOperationError('target-changed');
    }

    if (selection.kind === 'input') {
      if (
        !(target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement) ||
        target.value.length !== selection.textLength ||
        (selection.selectionSupported &&
          (target.selectionStart !== selection.start || target.selectionEnd !== selection.end))
      ) {
        throw new ContextMenuOperationError('target-changed');
      }
      return;
    }

    const range = selection.range;
    const browserSelection = this.document.defaultView?.getSelection();
    const currentRange = browserSelection?.rangeCount ? browserSelection.getRangeAt(0) : null;
    if (
      !range ||
      !range.startContainer.isConnected ||
      target.textContent?.length !== selection.textLength ||
      !currentRange ||
      currentRange.startContainer !== range.startContainer ||
      currentRange.startOffset !== range.startOffset ||
      currentRange.endContainer !== range.endContainer ||
      currentRange.endOffset !== range.endOffset
    ) {
      throw new ContextMenuOperationError('target-changed');
    }
  }

  private controlRevision(target: TextControl): number {
    return this.controlRevisions.get(target) ?? 0;
  }

  private failureReason(reason: unknown): ContextMenuFailureReason {
    return reason instanceof ContextMenuOperationError ? reason.reason : 'operation-failed';
  }

  private successFeedback(action: ContextMenuAction): string {
    switch (action) {
      case 'cut':
        return 'Texto cortado.';
      case 'copy':
        return 'Texto copiado.';
      case 'paste':
        return 'Texto pegado.';
      case 'select-all':
        return 'Texto seleccionado.';
    }
  }

  private failureFeedback(reason: ContextMenuFailureReason): string {
    switch (reason) {
      case 'clipboard-unavailable':
        return 'El portapapeles no está disponible.';
      case 'clipboard-denied':
        return 'El sistema no permitió acceder al portapapeles.';
      case 'target-changed':
        return 'La acción se canceló porque el control cambió.';
      case 'operation-failed':
        return 'No se pudo completar la acción de edición.';
    }
  }

  private clamp(value: number, minimum: number, maximum: number): number {
    return Math.min(Math.max(value, minimum), maximum);
  }
}

export interface PaginaDto<T> {
  readonly elementos: readonly T[];
  readonly pagina: number;
  readonly tamano: number;
  readonly total: number;
}

/** Parámetros que emite el chasis cuando la tabla necesita datos nuevos. */
export interface SolicitudPagina {
  readonly pagina: number;
  readonly tamano: number;
  readonly busqueda: string;
}

// ============================================================
// MODOS CRUD
// ============================================================

/** Los tres modos que soporta el diálogo CRUD (Doctrina ADR-007). */
export type ModoCrud = 'crear' | 'editar' | 'ver';

/** Contexto que el chasis pasa a la plantilla del formulario proyectado. */
export interface ContextoFormularioCrud<T> {
  /** Referencia implícita para `let-entidad` en la plantilla. */
  readonly $implicit: T | null;
  /** La entidad activa (null en modo crear). */
  readonly entidad: T | null;
  /** Modo actual del diálogo. */
  readonly modo: ModoCrud;
  /** Indica si la operación de guardado está en curso. */
  readonly guardando: boolean;
}

// ============================================================
// CONFIGURACIÓN DE ENTIDAD (para accordion multi-entidad)
// ============================================================

/**
 * Define una entidad dentro de un acordeón CRUD.
 * Cada entrada genera un accordion-item con su propia grilla y diálogo.
 */
export interface EntidadAccordion<_T extends object = Record<string, unknown>> {
  /** Identificador único de la entidad dentro del acordeón. */
  readonly clave: string;
  /** Título visible en la cabecera del accordion-item. */
  readonly titulo: string;
  /** Descripción opcional debajo del título. */
  readonly descripcion?: string;
  /** Icono Font Awesome opcional para la cabecera del panel. */
  readonly icono?: string;
  /** Si el item arranca abierto (solo el principal). */
  readonly abiertoInicial?: boolean;
  /** Si el panel de la entidad está temporalmente deshabilitado. */
  readonly deshabilitada?: boolean;
  /** Etiqueta del botón de acción principal. Por defecto 'Nuevo'. */
  readonly etiquetaNuevo?: string;
  /** Placeholder del campo de búsqueda. */
  readonly placeholderBusqueda?: string;
  /** Título del diálogo CRUD según el modo. */
  readonly titulosDialogo?: Partial<Record<ModoCrud, string>>;
  /** Tamaño del diálogo. Por defecto 'md'. */
  readonly tamanoDialogo?: 'sm' | 'md' | 'lg' | 'xl';
}

// ============================================================
// ACCIONES DE FILA
// ============================================================

/**
 * Acciones estándar disponibles en la columna de acciones de la grilla.
 * Corresponden directamente a los valores de TableActionName de Atomic.
 *
 * Por defecto el chasis habilita: ver, editar, eliminar (Doctrina ADR-007).
 */
export interface AccionesCrud {
  /** Mostrar botón de previsualización (ojo). Por defecto: true. */
  readonly ver?: boolean;
  /** Mostrar botón de edición (lápiz). Por defecto: true. */
  readonly editar?: boolean;
  /** Mostrar botón de eliminación/baja (papelera). Por defecto: true. */
  readonly eliminar?: boolean;
}

/**
 * Justificación auditable para una tercera acción directa de catálogo.
 *
 * El estándar físico conserva Ver, Editar y Más acciones. Una acción
 * contextual solo puede ocupar un tercer botón directo cuando el consumidor
 * declara por qué es frecuente y cuál es la evidencia que sostiene esa
 * excepción. Atomic solo valida la declaración y la semántica visual; no
 * infiere permisos, contratos ni frecuencia real.
 */
export interface AccionDirectaContextualCatalogo {
  /** Id de una acción ya declarada por fila. */
  readonly idAccion: string;
  /** Razón concreta por la que la acción debe permanecer a la vista. */
  readonly justificacion: string;
  /** Evidencia verificable de uso frecuente o necesidad operacional. */
  readonly evidencia: string;
}

/** Acciones por defecto que el chasis utiliza si no se sobreescriben. */
export const ACCIONES_CRUD_DEFECTO: Readonly<Required<AccionesCrud>> = {
  ver: true,
  editar: true,
  eliminar: true,
} as const;

// ============================================================
// CONFIRMACIÓN DE BAJA
// ============================================================

/**
 * Configuración del diálogo de confirmación de baja lógica.
 * Cumple Doctrina de Interfaz §7 y §12:
 *   - El mensaje enumera qué va a cambiar con nombres concretos.
 *   - El botón lleva el verbo del acto ('Desactivar').
 *   - El foco inicial se pone en cancelar.
 */
export interface ConfiguracionConfirmacion {
  /** Función que genera el título del diálogo de confirmación. */
  readonly titulo?: (entidad: unknown) => string;
  /** Función que genera el cuerpo del mensaje. */
  readonly mensaje?: (entidad: unknown) => string;
  /** Texto del botón de confirmación. Por defecto: 'Desactivar'. */
  readonly etiquetaConfirmar?: string;
  /** Texto del botón de cancelación. Por defecto: 'Revisar'. */
  readonly etiquetaCancelar?: string;
  /** Consecuencia visual declarada por el consumidor; no se infiere del registro. */
  readonly varianteConfirmar?: 'danger' | 'success';
}

/** Confirmación por defecto para bajas lógicas. */
export const CONFIRMACION_BAJA_DEFECTO: Readonly<Required<ConfiguracionConfirmacion>> = {
  titulo: () => 'Confirmar desactivación',
  mensaje: () => 'Este registro quedará inactivo. Las referencias existentes se conservarán.',
  etiquetaConfirmar: 'Desactivar',
  etiquetaCancelar: 'Cancelar',
  varianteConfirmar: 'danger',
} as const;

// ============================================================
// CONTEXTO DE PESTAÑAS (para Chasis C)
// ============================================================

/** Define una pestaña en la vista de detalle. */
export interface PestanaDetalle {
  /** Identificador único de la pestaña. */
  readonly clave: string;
  /** Título visible en la pestaña. */
  readonly titulo: string;
  /** Icono Font Awesome opcional. */
  readonly icono?: string;
  /** Si la pestaña arranca activa. */
  readonly activa?: boolean;
  /** Si la pestaña está deshabilitada. */
  readonly deshabilitada?: boolean;
}

import { Component, inject, signal, computed, OnInit, viewChild } from '@angular/core';
import { Router } from '@angular/router';
import type { UserMenuAction } from '@shared/ui/molecules/user-menu/user-menu.component';
import { FormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';

import {
  SidebarMenuItem,
  LayoutShellComponent,
  SidebarComponent,
  TopbarComponent,
  ThemeSwitcherComponent,
  PaginaCrud,
  FloatingInputComponent,
  Select2Component,
  DataTableColumn,
  DataTableStatus,
  PopupService
} from '@shared/ui';


import { useApi } from '@shared/ui/services/use-api.service';
import { of, delay } from 'rxjs';

export interface Entity {
  id: string;
  name: string;
  email: string;
  role: string;
  status: string;
  createdAt: string;
}

const FAKE_DB: Entity[] = Array.from({ length: 50 }).map((_, i) => ({
  id: String(i + 1),
  name: `Usuario de Prueba ${i + 1}`,
  email: `usuario${i + 1}@example.com`,
  role: i % 3 === 0 ? 'admin' : i % 2 === 0 ? 'editor' : 'user',
  status: i % 5 === 0 ? 'inactive' : i % 7 === 0 ? 'pending' : 'active',
  createdAt: new Date(Date.now() - Math.floor(Math.random() * 10000000000)).toISOString().split('T')[0]
}));
let idCounter = 51;

@Component({
  selector: 'app-crud-table',
  standalone: true,
  imports: [
    ReactiveFormsModule,
    LayoutShellComponent,
    SidebarComponent,
    TopbarComponent,
    ThemeSwitcherComponent,
    PaginaCrud,
    FloatingInputComponent,
    Select2Component
  ],
  templateUrl: './crud-table.component.html',
  styleUrl: './crud-table.component.css'
})
export class CrudTableComponent implements OnInit {
  // SIDEBAR
  sidebarVisible = signal(true);
  menuItems: SidebarMenuItem[] = [
    { label: 'Showcase', icon: 'fa-solid fa-palette', route: '/showcase' , iconColor: 'var(--secondary-color)' },
    { label: 'Dashboard', icon: 'fa-solid fa-chart-pie', route: '/dashboard' , iconColor: 'var(--info-color)' },
    { label: 'CRUD', icon: 'fa-solid fa-table', route: '/crud' , active: true, iconColor: 'var(--success-color)' },
    { label: 'Wizard', icon: 'fa-solid fa-wand-magic-sparkles', route: '/wizard' , iconColor: 'var(--warning-color)' },
    { label: 'Cierres', icon: 'fa-solid fa-window-restore', route: '/dialogs', iconColor: 'var(--primary-color)' },
    { label: 'Settings', icon: 'fa-solid fa-gear', route: '/settings' , iconColor: 'var(--text-color-secondary)' },
  ];

  onToggleSidebar() {
    this.sidebarVisible.update(v => !v);
  }

  onSidebarNavigate(item: SidebarMenuItem) {
    if (item.route) {
      this.router.navigate([item.route]);
    }
  }

  onLogout() {
    this.popup.info('Sesión finalizada', 'Cerrando sesión...');
    this.router.navigate(['/login']);
  }

  onUserAction(action: UserMenuAction): void {
    if (action.id === 'settings') this.router.navigate(['/settings']);
  }

  private readonly fb = inject(FormBuilder).nonNullable;
  private readonly router = inject(Router);
  private readonly popup = inject(PopupService);

  private readonly consultaPaginaCrud = viewChild<PaginaCrud<Entity>>(PaginaCrud);
  get paginaCrud(): PaginaCrud<Entity> {
    return this.consultaPaginaCrud()!;
  }

  // ============================================
  // PAGINA CRUD CONFIGURATION
  // ============================================

  readonly columnas: DataTableColumn<Entity>[] = [
    { key: 'name', header: 'Nombre', sortable: true },
    { key: 'email', header: 'Email', sortable: true },
    { key: 'role', header: 'Rol', sortable: true, isBadge: true, badgeVariant: () => 'default' },
    {
      key: 'status',
      header: 'Estado',
      sortable: true,
      isBadge: true,
      badgeVariant: (row: Entity) => {
        switch (row.status) {
          case 'active': return 'success';
          case 'pending': return 'warning';
          case 'inactive': return 'danger';
          default: return 'default';
        }
      },
      format: (val: unknown) => val === 'active' ? 'Activo' : val === 'pending' ? 'Pendiente' : 'Inactivo'
    },
    {
      key: 'createdAt',
      header: 'Creado',
      sortable: true,
      format: (val: unknown) => new Date(val as string).toLocaleDateString('es-ES', { year: 'numeric', month: 'short', day: 'numeric' })
    }
  ];

  readonly opcionesBusqueda = [
    { value: 'name', label: 'Nombre del personal' },
    { value: 'document', label: 'Número de documento' },
    { value: 'regimen', label: 'Régimen laboral', tipo: 'select' as const, opcionesSelect: [
      { value: '728', label: 'D.L. 728' },
      { value: '1057', label: 'CAS' },
      { value: '276', label: 'D.L. 276' }
    ]},
    { value: 'status', label: 'Estado', tipo: 'select' as const, opcionesSelect: [
      { value: 'active', label: 'Activo' },
      { value: 'inactive', label: 'Inactivo' },
      { value: 'pending', label: 'Pendiente' }
    ]}
  ];

  roleOptions = [
    { value: 'admin', label: 'Administrador' },
    { value: 'user', label: 'Usuario' },
    { value: 'guest', label: 'Invitado' }
  ];

  statusOptions = [
    { value: 'active', label: 'Activo' },
    { value: 'inactive', label: 'Inactivo' },
    { value: 'pending', label: 'Pendiente' }
  ];

  // STATE
  listApi = useApi<{ data: Entity[], total: number }>();
  saveApi = useApi<Entity>();
  deleteApi = useApi<void>();

  filas = computed(() => this.listApi.data()?.data ?? []);
  totalRegistros = computed(() => this.listApi.data()?.total ?? 0);
  estadoGrilla = computed<DataTableStatus>(() => {
    if (this.listApi.loading() && this.filas().length === 0) return 'loading';
    if (this.listApi.hasError()) return 'error';
    if (this.filas().length === 0) return 'empty';
    return 'success';
  });

  paginaActual = signal(1);
  tamanoActual = signal(10);
  busquedaActual = signal('');
  modoCrud = signal<'crear' | 'editar' | 'ver'>('crear');
  entidadActiva = signal<Entity | null>(null);

  // FORM
  entityForm = this.fb.group({
    name: ['', [Validators.required, Validators.minLength(2)]],
    email: ['', [Validators.required, Validators.email]],
    role: ['user', [Validators.required]],
    status: ['active', [Validators.required]]
  });

  ngOnInit() {
    this.cargarPagina({ pagina: 1, tamano: 10, busqueda: '' });
  }

  cargarPagina(req: { pagina: number; tamano: number; busqueda: string }) {
    this.paginaActual.set(req.pagina);
    this.tamanoActual.set(req.tamano);
    this.busquedaActual.set(req.busqueda);

    // Simulate filtering
    let filtered = [...FAKE_DB];
    if (req.busqueda) {
      const type = this.paginaCrud?.tipoBusquedaInterno() ?? 'name';
      const val = req.busqueda.toLowerCase();

      if (type === 'name') filtered = filtered.filter(e => e.name.toLowerCase().includes(val) || e.email.toLowerCase().includes(val));
      if (type === 'document') filtered = filtered.filter(e => e.id.toLowerCase().includes(val));
      if (type === 'regimen') filtered = filtered.filter(e => (val === '728' ? e.role === 'admin' : e.role !== 'admin'));
      if (type === 'status') filtered = filtered.filter(e => e.status === val);
    }

    const start = (req.pagina - 1) * req.tamano;
    const paginated = filtered.slice(start, start + req.tamano);

    this.listApi.execute(of({ data: paginated, total: filtered.length }).pipe(delay(500)));
  }

  abrirCrear() {
    this.modoCrud.set('crear');
    this.entidadActiva.set(null);
    this.entityForm.reset({ role: 'user', status: 'active' });
    this.paginaCrud.abrirDialogo();
  }

  abrirEditar(entidad: Entity) {
    this.modoCrud.set('editar');
    this.entidadActiva.set(entidad);
    this.entityForm.patchValue(entidad);
    this.paginaCrud.abrirDialogo();
  }

  abrirVer(entidad: Entity) {
    this.modoCrud.set('ver');
    this.entidadActiva.set(entidad);
    this.entityForm.patchValue(entidad);
    this.entityForm.disable(); // For preview
    this.paginaCrud.abrirDialogo();
  }

  eliminar(entidad: Entity) {
    const idx = FAKE_DB.findIndex(e => e.id === entidad.id);
    if (idx !== -1) FAKE_DB.splice(idx, 1);

    this.deleteApi.execute(of(void 0).pipe(delay(500)));

    const check = setInterval(() => {
      if (this.deleteApi.success()) {
        clearInterval(check);
        const pagina =
          this.filas().length <= 1 && this.paginaActual() > 1
            ? this.paginaActual() - 1
            : this.paginaActual();
        this.cargarPagina({
          pagina,
          tamano: this.tamanoActual(),
          busqueda: this.busquedaActual(),
        });
      }
    }, 100);
  }

  guardar() {
    if (this.entityForm.invalid) {
      this.entityForm.markAllAsTouched();
      this.paginaCrud.enfocarError();
      return;
    }

    const val = this.entityForm.getRawValue();
    const curr = this.entidadActiva();
    const esEdicion = this.modoCrud() === 'editar' && Boolean(curr);
    const data: Entity = {
      id: curr?.id ?? String(idCounter++),
      createdAt: curr?.createdAt ?? new Date().toISOString().split('T')[0],
      ...val
    };

    if (esEdicion && curr) {
      const idx = FAKE_DB.findIndex(e => e.id === curr.id);
      if (idx !== -1) FAKE_DB[idx] = data;
    } else {
      FAKE_DB.unshift(data);
    }

    this.saveApi.execute(of(data).pipe(delay(500)));

    const check = setInterval(() => {
      if (this.saveApi.success()) {
        clearInterval(check);
        this.paginaCrud.cerrarDialogo();
        this.cargarPagina({
          pagina: esEdicion ? this.paginaActual() : 1,
          tamano: this.tamanoActual(),
          busqueda: this.busquedaActual(),
        });
      }
    }, 100);
  }

  cerrarDialogo() {
    this.saveApi.reset();
    this.entityForm.enable();
  }

  getFieldError(fieldName: string): string {
    const field = this.entityForm.get(fieldName);
    if (!field || !field.touched || !field.errors) return '';
    if (field.errors['required']) return 'Campo requerido';
    if (field.errors['email']) return 'Email inválido';
    if (field.errors['minlength']) return `Mínimo ${field.errors['minlength'].requiredLength} caracteres`;
    return '';
  }
}

import {
  ChangeDetectionStrategy,
  Component,
  computed,
  inject,
  input,
} from '@angular/core';

import { ActivatedRoute, Router } from '@angular/router';
import {
  ButtonComponent,
  TextComponent,
  ScrollOverlayComponent,
  RowComponent,
} from '@shared/ui';

export type ErrorCode = 400 | 401 | 403 | 404 | 500 | 503;

export interface ErrorPageConfig {
  code: ErrorCode;
  title: string;
  description: string;
  icon: string;
  primaryAction?: { label: string; route: string };
  secondaryAction?: { label: string; action: () => void };
}

const ERROR_DEFAULTS: Record<ErrorCode, Omit<ErrorPageConfig, 'primaryAction' | 'secondaryAction'>> = {
  400: {
    code: 400,
    title: 'Solicitud inválida',
    description: 'La solicitud enviada no es válida. Verifica los datos ingresados e intenta de nuevo.',
    icon: '⚠️',
  },
  401: {
    code: 401,
    title: 'No autorizado',
    description: 'No tienes credenciales para acceder a este recurso. Inicia sesión para continuar.',
    icon: '🔐',
  },
  403: {
    code: 403,
    title: 'Acceso denegado',
    description: 'No tienes permisos para acceder a esta página. Contacta a tu administrador.',
    icon: '🚫',
  },
  404: {
    code: 404,
    title: 'Página no encontrada',
    description: 'La página que buscas no existe o fue movida. Verifica la URL o vuelve al inicio.',
    icon: '🔍',
  },
  500: {
    code: 500,
    title: 'Error interno del servidor',
    description: 'Ocurrió un error inesperado en el servidor. Por favor intenta más tarde.',
    icon: '💥',
  },
  503: {
    code: 503,
    title: 'Servicio no disponible',
    description: 'El servicio está temporalmente fuera de línea por mantenimiento. Vuelve en unos minutos.',
    icon: '🔧',
  },
};

/**
 * ErrorPagesComponent — Página de error genérica para 400/401/403/404/500/503
 *
 * @usage
 * ```html
 * <!-- En app.routes.ts -->
 * { path: '**', component: ErrorPagesComponent, data: { code: 404 } }
 * { path: '500', component: ErrorPagesComponent, data: { code: 500 } }
 * ```
 *
 * @usage
 * ```html
 * <!-- En template -->
 * <app-error-pages [code]="404"></app-error-pages>
 * <app-error-pages [code]="500" title="Error personalizado"></app-error-pages>
 * ```
 */
@Component({
  selector: 'app-error-pages',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [
    ButtonComponent,
    TextComponent,
    ScrollOverlayComponent,
    RowComponent,
  ],
  template: `
    <app-scroll-overlay class="so-block h-screen w-full" [skipTableDetection]="true">
    <div class="error-page">
      <div class="error-container">

        <!-- Icono / Ilustración -->
        <div class="error-icon" role="img" [attr.aria-label]="'Error ' + resolvedCode()">
          {{ resolvedIcon() }}
        </div>

        <!-- Código HTTP -->
        <div class="error-code">{{ resolvedCode() }}</div>

        <!-- Título -->
        <app-text variant="h2" class="error-title">
          {{ resolvedTitle() }}
        </app-text>

        <!-- Descripción -->
        <app-text variant="body" color="muted" class="error-description">
          {{ resolvedDescription() }}
        </app-text>

        <!-- Acciones -->
        <app-row gap="1rem" class="error-actions">
          <app-button
            variant="primary"
            (click)="onPrimaryAction()"
          >
            <i class="fa-solid fa-house" icon-left></i>
            {{ primaryActionLabel() }}
          </app-button>

          @if (showSecondaryAction()) {
            <app-button variant="ghost" (click)="onSecondaryAction()">
              <i class="fa-solid fa-arrow-rotate-right" icon-left></i>
              Reintentar
            </app-button>
          }

          <app-button variant="ghost" (click)="goBack()">
            <i class="fa-solid fa-arrow-left" icon-left></i>
            Volver
          </app-button>
        </app-row>

        <!-- Info técnica (solo en development) -->
        @if (showTechnicalInfo() && technicalMessage()) {
          <details class="error-technical">
            <summary>Información técnica</summary>
            <code>{{ technicalMessage() }}</code>
          </details>
        }

      </div>
    </div>
    </app-scroll-overlay>
  `,
  styles: [`
    .error-page {
      min-height: 100vh;
      display: flex;
      align-items: center;
      justify-content: center;
      background: var(--page-background, var(--surface-background));
      padding: var(--space-8);
    }

    .error-container {
      max-width: 32.5rem;
      width: 100%;
      text-align: center;
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: var(--space-4);
    }

    .error-icon {
      font-size: 5rem;
      line-height: 1;
      animation: bounce-in 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);
    }

    .error-code {
      font-size: 7rem;
      font-weight: var(--font-weight-display);
      line-height: 1;
      color: var(--primary-color);
      opacity: 0.15;
      letter-spacing: -0.25rem;
      user-select: none;
    }

    .error-title {
      margin-top: calc(-1 * var(--space-8));
    }

    .error-description {
      max-width: 25rem;
    }

    .error-actions {
      margin-top: var(--space-2);
      justify-content: center;
      flex-wrap: wrap;
    }

    .error-technical {
      margin-top: var(--space-6);
      text-align: left;
      background: var(--surface-section);
      border: var(--border-width-sm, 0.0625rem) solid var(--border-color);
      border-radius: var(--radius-md);
      padding: var(--space-3) var(--space-4);
      width: 100%;
      font-size: 0.75rem;
    }

    .error-technical summary {
      cursor: pointer;
      color: var(--text-color-muted);
      margin-bottom: var(--space-2);
    }

    .error-technical code {
      font-family: monospace;
      color: var(--color-error);
      word-break: break-all;
    }

    @keyframes bounce-in {
      from { transform: scale(0.5); opacity: 0; }
      to   { transform: scale(1);   opacity: 1; }
    }

    @media (max-width: 30rem) {
      .error-code { font-size: 5rem; }
      .error-icon { font-size: 3.5rem; }
    }
  `],
})
export class ErrorPagesComponent {
  /** HTTP error code to display */
  readonly code = input<ErrorCode>(404);

  /** Override default title */
  readonly title = input<string | undefined>(undefined);

  /** Override default description */
  readonly description = input<string | undefined>(undefined);

  /** Override default icon */
  readonly icon = input<string | undefined>(undefined);

  /** Label for primary action button */
  readonly primaryActionLabel = input('Ir al inicio');

  /** Route for primary action */
  readonly primaryActionRoute = input('/');

  /** Show retry button (useful for 500, 503) */
  readonly showSecondaryAction = input(false);

  /** Show technical details section */
  readonly showTechnicalInfo = input(false);

  /** Technical error message for developers */
  readonly technicalMessage = input<string | undefined>(undefined);

  private readonly router = inject(Router, { optional: true });
  private readonly route = inject(ActivatedRoute, { optional: true });

  protected readonly resolvedCode = computed<ErrorCode>(() => {
    const routeCode = this.route?.snapshot?.data?.['code'];
    return typeof routeCode === 'number' ? (routeCode as ErrorCode) : this.code();
  });

  protected readonly resolvedTitle = computed<string>(() => {
    const code = this.resolvedCode();
    return this.title()?.trim() || ERROR_DEFAULTS[code]?.title || 'Error';
  });

  protected readonly resolvedDescription = computed<string>(() => {
    const code = this.resolvedCode();
    return this.description()?.trim() || ERROR_DEFAULTS[code]?.description || '';
  });

  protected readonly resolvedIcon = computed<string>(() => {
    const code = this.resolvedCode();
    return this.icon()?.trim() || ERROR_DEFAULTS[code]?.icon || '❌';
  });

  onPrimaryAction(): void {
    this.router?.navigate([this.primaryActionRoute()]);
  }

  onSecondaryAction(): void {
    window.location.reload();
  }

  goBack(): void {
    history.back();
  }
}

import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  contentChild,
  input,
  inject,
  output,
  signal,
  TemplateRef,
  viewChildren,
  viewChild,
} from '@angular/core';
import { PageHeader, PageHeaderAlignment } from '../../organisms/page-header/page-header';
import { QueryToolbar } from '../../organisms/query-toolbar/query-toolbar';
import {
  DataTable,
  type DataTableColumn,
  type DataTableStatus,
} from '../../organisms/data-table/data-table';
import { CrudDialog } from '../../organisms/crud-dialog/crud-dialog';
import {
  AccordionComponent,
  AccordionItemComponent,
  type AccordionVariant,
} from '../../organisms/accordion/accordion.component';
import { TableAction } from '../../atoms/table-action/table-action';
import { ButtonComponent } from '../../atoms/button/button.component';
import { InputComponent } from '../../atoms/input/input.component';
import { IconButtonComponent } from '../../atoms/icon-button/icon-button.component';
import { NgTemplateOutlet } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Alert } from '../../molecules/alert/alert.component';
import {
  type AccionesCrud,
  ACCIONES_CRUD_DEFECTO,
  type ModoCrud,
  type ContextoFormularioCrud,
  type SolicitudPagina,
  type EntidadAccordion,
  type ConfiguracionConfirmacion,
  CONFIRMACION_BAJA_DEFECTO,
} from '../modelos-crud';

/**
 * Evento emitido cuando una entidad del acordeón necesita datos o una acción.
 * Incluye la `clave` de la entidad para que la facade sepa cuál procesar.
 */
export interface EventoEntidadAccordion<T = unknown> {
  readonly clave: string;
  readonly datos: T;
}

/**
 * Chasis B — Página CRUD multi-entidad con acordeón.
 *
 * Agrupa varias entidades relacionadas (ej. Productos + Familias,
 * o Entidades financieras + Cuentas + Cajas) en accordion-items,
 * cada uno con su propia grilla y diálogo CRUD.
 *
 * Patrón definido por ADR-007:
 *   - Se abre la entidad principal, las secundarias arrancan retraídas.
 *   - Cada accordion-item contiene: búsqueda + botón «Nuevo» + grilla.
 *   - Los formularios CRUD viven en diálogos modales, no en la vista.
 *
 * @ejemplo Uso por un agente:
 * ```html
 * <app-pagina-crud-accordion
 *   titulo="Recaudación"
 *   [entidades]="entidades"
 *   [filasPorEntidad]="facade.filasPorEntidad()"
 *   [estadoPorEntidad]="facade.estadoPorEntidad()"
 *   [columnasPorEntidad]="columnasPorEntidad"
 *   (alSolicitarPagina)="facade.cargar($event.clave, $event.datos)"
 *   (alCrear)="facade.abrirCrear($event)"
 *   (alEditar)="facade.abrirEditar($event.clave, $event.datos)"
 *   (alEliminar)="facade.desactivar($event.clave, $event.datos)"
 *   (alGuardar)="facade.guardar()"
 *   (alCerrarDialogo)="facade.cerrarDialogo()"
 * >
 *   <ng-template #formularioCrud let-ctx>
 *     <!-- Formulario que se adapta según ctx.modo y la entidad activa -->
 *   </ng-template>
 * </app-pagina-crud-accordion>
 * ```
 */
@Component({
  selector: 'app-pagina-crud-accordion',
  imports: [
    PageHeader,
    QueryToolbar,
    DataTable,
    CrudDialog,
    AccordionComponent,
    AccordionItemComponent,
    TableAction,
    ButtonComponent,
    InputComponent,
    IconButtonComponent,
    NgTemplateOutlet,
    FormsModule,
    Alert,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './pagina-crud-accordion.html',
  styleUrl: './pagina-crud-accordion.scss',
})
export class PaginaCrudAccordion<T extends object = Record<string, unknown>> {
  // ─── Configuración de la página ──────────────────────────────
  readonly titulo = input.required<string>();
  readonly subtitulo = input<string | null>(null);
  readonly headerAlign = input<PageHeaderAlignment>('center');
  /** Variante del acordeón (`default`, `multiple`, `single`, `flush`). */
  readonly varianteAccordion = input<AccordionVariant>('default');
  /** Cuando es `true`, abrir una entidad cierra automáticamente las demás. */
  readonly soloUnoAbierto = input(false);
  /** En modo exclusivo (`single`), indica si el panel activo puede plegarse (`true` por omisión). */
  readonly colapsable = input(true);

  /**
   * Array de configuraciones de entidad. Cada una genera un accordion-item.
   * La primera con `abiertoInicial: true` arranca expandida.
   */
  readonly entidades = input.required<readonly EntidadAccordion[]>();

  // ─── Datos por entidad (mapas clave → valor) ────────────────
  /** Mapa clave → columnas de la grilla. */
  readonly columnasPorEntidad = input.required<
    Readonly<Record<string, readonly DataTableColumn<T>[]>>
  >();
  /** Mapa clave → filas de datos. */
  readonly filasPorEntidad = input.required<
    Readonly<Record<string, readonly T[]>>
  >();
  /** Mapa clave → estado de carga. */
  readonly estadoPorEntidad = input<
    Readonly<Record<string, DataTableStatus>>
  >({});
  /** Mapa clave → total de registros para paginación server. */
  readonly totalPorEntidad = input<Readonly<Record<string, number>>>({});
  /** Mapa clave → página actual. */
  readonly paginaPorEntidad = input<Readonly<Record<string, number>>>({});

  // ─── Configuración de acciones ───────────────────────────────
  readonly acciones = input<AccionesCrud>(ACCIONES_CRUD_DEFECTO);
  readonly confirmacionBaja = input<ConfiguracionConfirmacion>(CONFIRMACION_BAJA_DEFECTO);

  // ─── Estado del diálogo CRUD ─────────────────────────────────
  readonly claveEntidadActiva = input<string | null>(null);
  readonly modoCrud = input<ModoCrud>('crear');
  readonly entidadActiva = input<T | null>(null);
  readonly guardando = input(false);
  readonly errorOperacion = input<string | null>(null);

  // ─── Eventos (incluyen la clave de entidad) ──────────────────
  readonly alSolicitarPagina = output<EventoEntidadAccordion<SolicitudPagina>>();
  readonly alCrear = output<string>();
  readonly alVer = output<EventoEntidadAccordion<T>>();
  readonly alEditar = output<EventoEntidadAccordion<T>>();
  readonly alEliminar = output<EventoEntidadAccordion<T>>();
  readonly alGuardar = output<void>();
  readonly alCerrarDialogo = output<void>();
  readonly alReintentar = output<string>();

  // ─── Referencias internas ────────────────────────────────────
  protected readonly dialogoCrud = viewChildren<CrudDialog>('dialogoCrud');
  protected readonly dialogoConfirmacion = viewChild.required<CrudDialog>('dialogoConfirmacion');
  private readonly detectorCambios = inject(ChangeDetectorRef);
  protected readonly formularioCrud =
    contentChild<TemplateRef<ContextoFormularioCrud<T>>>('formularioCrud');

  // ─── Estado local ────────────────────────────────────────────
  protected readonly busquedaPorEntidad = signal<Record<string, string>>({});
  protected readonly mostrarConfirmacion = signal(false);
  protected readonly entidadAEliminar = signal<T | null>(null);
  protected readonly claveConfirmacion = signal<string | null>(null);

  private static contadorInstancias = 0;
  protected readonly idTituloDialogo = `accordion-crud-dialogo-${++PaginaCrudAccordion.contadorInstancias}`;
  protected readonly idTituloConfirmacion = this.idTituloDialogo + '-confirmacion';
  protected readonly idMensajeConfirmacion = this.idTituloDialogo + '-confirmacion-mensaje';

  // ─── Utilidades ──────────────────────────────────────────────
  protected tituloDialogo(): string {
    const clave = this.claveEntidadActiva();
    const entConf = this.entidades().find(e => e.clave === clave);
    const nombre = entConf?.titulo ?? '';
    const modo = this.modoCrud();
    if (entConf?.titulosDialogo?.[modo]) {
      return entConf.titulosDialogo[modo]!;
    }
    switch (modo) {
      case 'crear': return `Nuevo ${nombre}`;
      case 'editar': return `Editar ${nombre}`;
      case 'ver': return `Detalle de ${nombre}`;
    }
  }

  protected contextoFormulario(): ContextoFormularioCrud<T> {
    const entidad = this.entidadActiva();
    return {
      $implicit: entidad,
      entidad,
      modo: this.modoCrud(),
      guardando: this.guardando(),
    };
  }

  protected filasDeEntidad(clave: string): readonly T[] {
    return this.filasPorEntidad()[clave] ?? [];
  }

  protected estadoDeEntidad(clave: string): DataTableStatus {
    return this.estadoPorEntidad()[clave] ?? 'idle';
  }

  protected columnasDeEntidad(clave: string): readonly DataTableColumn<T>[] {
    return this.columnasPorEntidad()[clave] ?? [];
  }

  protected busquedaDeEntidad(clave: string): string {
    return this.busquedaPorEntidad()[clave] ?? '';
  }

  protected alBuscarEntidad(clave: string, termino: string): void {
    this.busquedaPorEntidad.update(m => ({ ...m, [clave]: termino }));
    this.alSolicitarPagina.emit({
      clave,
      datos: { pagina: 1, tamano: 10, busqueda: termino },
    });
  }

  protected alCambiarPaginaEntidad(clave: string, pagina: number): void {
    this.alSolicitarPagina.emit({
      clave,
      datos: {
        pagina,
        tamano: 10,
        busqueda: this.busquedaDeEntidad(clave),
      },
    });
  }

  protected solicitarBaja(clave: string, entidad: T): void {
    this.claveConfirmacion.set(clave);
    this.entidadAEliminar.set(entidad);
    this.mostrarConfirmacion.set(true);
    this.detectorCambios.detectChanges();
    this.dialogoConfirmacion().showModal('[data-dialog-initial-focus] button');
  }

  protected confirmarBaja(): void {
    const entidad = this.entidadAEliminar();
    const clave = this.claveConfirmacion();
    if (this.mostrarConfirmacion() && entidad && clave) {
      this.cancelarBaja();
      this.alEliminar.emit({ clave, datos: entidad });
    }
  }

  protected cancelarBaja(): void {
    this.dialogoConfirmacion().close();
    this.mostrarConfirmacion.set(false);
    this.entidadAEliminar.set(null);
    this.claveConfirmacion.set(null);
  }

  protected get accionesResueltas(): Required<AccionesCrud> {
    return { ...ACCIONES_CRUD_DEFECTO, ...this.acciones() };
  }

  protected get confResueltas(): Required<ConfiguracionConfirmacion> {
    return { ...CONFIRMACION_BAJA_DEFECTO, ...this.confirmacionBaja() };
  }

  protected get esModoPrevisualizacion(): boolean {
    return this.modoCrud() === 'ver';
  }

  /** Abre el diálogo CRUD del accordion. */
  abrirDialogo(): void {
    const dialogos = this.dialogoCrud();
    if (dialogos.length > 0) {
      dialogos[0].showModal();
    }
  }

  cerrarDialogo(): void {
    const dialogos = this.dialogoCrud();
    if (this.guardando() || !dialogos[0]?.open) {
      return;
    }
    dialogos[0].close();
    this.alCerrarDialogo.emit();
  }

  enfocarError(): void {
    const dialogos = this.dialogoCrud();
    if (dialogos.length > 0) {
      dialogos[0].focusError();
    }
  }
}

import { Component, signal } from '@angular/core';
import { PaginaCrud, FiltroBusqueda } from '../../../../shared/ui/templates/pagina-crud/pagina-crud';
import { PaginaCrudAccordion } from '../../../../shared/ui/templates/pagina-crud-accordion/pagina-crud-accordion';
import { PaginaWizardComponent } from '../../../../shared/ui/templates/pagina-wizard/pagina-wizard';
import { EntidadAccordion, SolicitudPagina } from '../../../../shared/ui/templates/modelos-crud';
import { PanelComponent } from '../../../../shared/ui/surfaces/panel/panel.component';
import { DataTableColumn } from '../../../../shared/ui/organisms/data-table/data-table';
import { InputComponent } from '../../../../shared/ui/atoms/input/input.component';
import { Step } from '../../../../shared/ui/organisms/stepper/stepper.component';

interface FilaProductoDemostracion {
  id: number;
  nombre: string;
  categoria: string;
  codigoCategoria: string;
}

@Component({
  selector: 'app-showcase-templates',
  standalone: true,
  imports: [PaginaCrud, PaginaCrudAccordion, PaginaWizardComponent, PanelComponent, InputComponent],
  template: `
    <app-panel title="Templates (Pagina CRUD y Variantes)" variant="flat" padding="md" class="showcase-section">
      <p class="showcase-description">
        Demostración de los templates de alto nivel, incluyendo Búsqueda en Cascada y variantes de CRUD.
      </p>

      <div class="showcase-preview-card showcase-preview-card--mb">
        <app-pagina-crud
          titulo="Búsqueda en Cascada (Pagina CRUD)"
          [columnas]="columnasCrud"
          [filas]="filasCrud()"
          [embedded]="true"
          [opcionesBusqueda]="opcionesBusqueda"
          [tipoBusqueda]="tipoBusquedaActual()"
          (alCambiarTipoBusqueda)="onCambiarTipoBusqueda($event)"
          (alSolicitarPagina)="onSolicitarPagina($event)"
        >
          <ng-template #formularioCrud let-ctx>
            <div class="showcase-form-grid">
              <app-input label="Nombre"></app-input>
              <app-input label="Categoría"></app-input>
            </div>
          </ng-template>
        </app-pagina-crud>
      </div>

      <div class="showcase-preview-card">
        <app-pagina-crud-accordion
          titulo="Variante: CRUD Accordion"
          varianteAccordion="single"
          [entidades]="entidadesAccordion"
          [columnasPorEntidad]="columnasAccordion"
          [filasPorEntidad]="filasAccordion"
        >
          <ng-template #formularioCrud let-ctx>
            <div class="showcase-form-grid">
              <app-input label="Dato"></app-input>
            </div>
          </ng-template>
        </app-pagina-crud-accordion>
      </div>
      <div class="showcase-preview-card showcase-preview-card--mt">
        <app-pagina-wizard
          titulo="Variante: CRUD Wizard"
          subtitulo="Paso a paso"
          [steps]="wizardSteps"
          [activeStep]="wizardActiveStep()"
          (stepChange)="wizardActiveStep.set($event)"
          (cancelled)="wizardActiveStep.set(0)"
          (backClicked)="wizardActiveStep.set(wizardActiveStep() - 1)"
          (nextClicked)="wizardActiveStep.set(wizardActiveStep() + 1)"
          (finished)="wizardActiveStep.set(0)"
        >
          <div class="showcase-wizard-step">
            <p>Contenido del paso {{ wizardActiveStep() + 1 }}</p>
          </div>
        </app-pagina-wizard>
      </div>
    </app-panel>
  `,
  styleUrl: './showcase-templates.component.css',
})
export class ShowcaseTemplatesComponent {
  // --- Búsqueda en Cascada (Pagina CRUD) ---
  opcionesBusqueda: FiltroBusqueda[] = [
    { label: 'Categoría', value: 'categoria', tipo: 'select', opcionesSelect: [
      { label: 'Electrónica', value: 'electro' },
      { label: 'Ropa', value: 'ropa' }
    ]},
    { label: 'Nombre', value: 'nombre', tipo: 'texto' }
  ];

  columnasCrud: DataTableColumn<FilaProductoDemostracion>[] = [
    { key: 'id', header: 'ID', width: '80px' },
    { key: 'nombre', header: 'Nombre' },
    { key: 'categoria', header: 'Categoría' }
  ];

  private readonly catalogoInicialCrud: FilaProductoDemostracion[] = [
    { id: 1, nombre: 'Laptop', categoria: 'Electrónica', codigoCategoria: 'electro' },
    { id: 2, nombre: 'Camisa', categoria: 'Ropa', codigoCategoria: 'ropa' }
  ];

  tipoBusquedaActual = signal<string | null>(null);
  filasCrud = signal<FilaProductoDemostracion[]>(this.catalogoInicialCrud);

  onCambiarTipoBusqueda(tipo: string | null): void {
    this.tipoBusquedaActual.set(tipo);
    this.filasCrud.set(this.catalogoInicialCrud);
  }

  onSolicitarPagina(solicitud: SolicitudPagina): void {
    const termino = (solicitud.busqueda ?? '').trim().toLowerCase();
    const tipo = this.tipoBusquedaActual();
    if (!termino || !tipo) {
      this.filasCrud.set(this.catalogoInicialCrud);
      return;
