import {
  Component,
  ChangeDetectionStrategy,
  signal,
  inject,
  PLATFORM_ID,
  ElementRef,
  ChangeDetectorRef,
  input,
  output,
  viewChild
} from '@angular/core';
import { isPlatformBrowser } from '@angular/common';
import { ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';
import { ScrollOverlayComponent } from '../../organisms/scroll-overlay/scroll-overlay.component';

let fileInputSequence = 0;

export interface FileInputFile {
  file: File;
  name: string;
  size: number;
  type: string;
  preview?: string;
}

export type FileInputDensity = 'comfortable' | 'compact';
export type FileInputVariant = 'standard' | 'dropzone';

/**
 * FileInputComponent — Campo de carga de archivos con drag & drop.
 *
 * @example
 * ```html
 * <app-file-input
 *   label="Adjuntar documentos"
 *   accept=".pdf,.docx"
 *   [multiple]="true"
 *   [maxSizeMB]="5"
 *   (filesChange)="onFiles($event)">
 * </app-file-input>
 * ```
 */
@Component({
  selector: 'app-file-input',
  standalone: true,
  imports: [ScrollOverlayComponent],
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [{ provide: NG_VALUE_ACCESSOR, useExisting: FileInputComponent, multi: true }],
  templateUrl: './file-input.component.html',
  styleUrl: './file-input.component.css',
})
export class FileInputComponent implements ControlValueAccessor {
  private readonly platformId = inject(PLATFORM_ID);
  private readonly changeDetectorRef = inject(ChangeDetectorRef);
  readonly inputId = `file-input-${++fileInputSequence}`;

  private readonly consultaFileInput = viewChild<ElementRef<HTMLInputElement>>('fileInput');
  get fileInputRef(): ElementRef<HTMLInputElement> {
    return this.consultaFileInput()!;
  }

  readonly label = input('');
  readonly hint = input('');
  readonly accept = input('');
  readonly multiple = input(false);
  readonly maxSizeMB = input<number>();
  readonly maxPreviewSizeMB = input(2);
  readonly maxPreviewFiles = input(4);
  readonly disabled = input(false);
  private readonly disabledByForm = signal(false);
  readonly error = input('');

  /** Variante visual: `standard` (compacta/clásica) o `dropzone` (zona destacada con insignia y cabecera de lista). */
  readonly variant = input<FileInputVariant>('standard');
  readonly dropzoneTitle = input('Arrastra tus archivos aquí');
  readonly dropzoneSubtitle = input('o haz clic para seleccionarlos desde tu equipo');
  readonly badgeHint = input('');
  readonly showHeader = input(false);
  readonly headerTitle = input('Documentos cargados');
  readonly allowClearAll = input(false);
  readonly clearAllLabel = input('Limpiar lista');
  readonly itemActionIcon = input('');
  readonly itemActionLabel = input('Acción sobre archivo');
  readonly maxListHeight = input<number | string>(210);

  readonly filesChange = output<FileInputFile[]>();
  readonly cleared = output<void>();
  readonly fileRemoved = output<FileInputFile>();
  readonly fileAction = output<FileInputFile>();

  /** Densidad visual. `compact` conserva el mismo contrato dentro de formularios modales. */
  readonly density = input<FileInputDensity>('comfortable');

  readonly files = signal<FileInputFile[]>([]);
  readonly isDragging = signal(false);
  readonly validationError = signal('');

  isDisabled(): boolean {
    return this.disabled() || this.disabledByForm();
  }

  get visibleError(): string {
    return this.error() || this.validationError();
  }

  private onChange: (v: FileInputFile[]) => void = () => {};
  protected onTouched: () => void = () => {};

  openFileDialog() {
    if (!this.isDisabled()) {
      this.onTouched();
      this.fileInputRef.nativeElement.click();
    }
  }

  onFileChange(event: Event) {
    if (this.isDisabled()) return;
    const input = event.target as HTMLInputElement;
    if (input.files) this.processFiles(Array.from(input.files));
    input.value = '';
  }

  onDragOver(event: DragEvent) {
    event.preventDefault();
    event.stopPropagation?.();
    if (this.isDisabled()) {
      this.isDragging.set(false);
      return;
    }
    const types = event.dataTransfer?.types;
    if (types && types.length > 0 && !Array.from(types).includes('Files')) {
      this.isDragging.set(false);
      return;
    }
    if (event.dataTransfer) {
      event.dataTransfer.dropEffect = 'copy';
    }
    this.isDragging.set(true);
  }

  onDragLeave(event: DragEvent) {
    event.preventDefault();
    event.stopPropagation?.();
    const currentTarget = event.currentTarget as HTMLElement | null;
    const relatedTarget = event.relatedTarget as Node | null;
    if (currentTarget && relatedTarget && currentTarget.contains(relatedTarget)) {
      return;
    }
    this.isDragging.set(false);
  }

  onDrop(event: DragEvent) {
    event.preventDefault();
    event.stopPropagation?.();
    this.isDragging.set(false);
    if (this.isDisabled()) return;
    const dropped = event.dataTransfer?.files;
    if (dropped) this.processFiles(Array.from(dropped));
  }

  private processFiles(rawFiles: File[]) {
    this.onTouched();
    this.validationError.set('');
    const selectedFiles = this.multiple() ? rawFiles : rawFiles.slice(0, 1);
    // Un archivo rechazado DESCARTA la seleccion anterior.
    //
    // Antes se ponia el mensaje de error y se salia sin tocar `files`, asi que lo
    // que hubiera seleccionado antes sobrevivia: el componente seguia mostrando
    // el fichero viejo, el formulario no recibia cambio alguno y el boton de
    // guardar del consumidor seguia habilitado. Lo que se enviaba no era lo que
    // la pantalla senalaba con el error, y en un flujo de archivado documental
    // eso significa guardar el documento equivocado de forma inmutable.
    //
    // Vaciar es la unica lectura en la que lo que se ve y lo que se envia
    // coinciden. Se notifica tambien al formulario, no solo al evento.
    const maxSizeMB = this.maxSizeMB();
    const invalidSize = selectedFiles.find(
      (file) => maxSizeMB !== undefined && file.size > maxSizeMB * 1024 * 1024,
    );
    if (invalidSize) {
      this.rejectSelection(
        `${invalidSize.name} supera el máximo de ${this.maxSizeMB()} MB.`,
      );
      return;
    }

    const invalidType = selectedFiles.find((file) => !this.isAccepted(file));
    if (invalidType) {
      this.rejectSelection(
        `${invalidType.name} no corresponde a los formatos permitidos.`,
      );
      return;
    }

    const processed: FileInputFile[] = selectedFiles.map((file) => ({
      file,
      name: file.name,
      size: file.size,
      type: file.type,
    }));

    this.generateImagePreviews(processed);

    const newFiles = this.multiple() ? [...this.files(), ...processed] : processed;
    this.files.set(newFiles);
    this.onChange(newFiles);
    this.filesChange.emit(newFiles);
  }

  /** Deja el campo vacio y avisa: al formulario y al evento. */
  private rejectSelection(message: string): void {
    this.validationError.set(message);
    this.files.set([]);
    this.onChange([]);
    this.filesChange.emit([]);
  }

  private generateImagePreviews(files: FileInputFile[]): void {
    if (!isPlatformBrowser(this.platformId)) {
      return;
    }

    const maxPreviewFiles = this.maxPreviewFiles();
    const maxFiles = Number.isFinite(maxPreviewFiles)
      ? Math.max(0, Math.trunc(maxPreviewFiles))
      : 0;
    const maxPreviewSizeMB = this.maxPreviewSizeMB();
    const maxSize = Number.isFinite(maxPreviewSizeMB)
      ? Math.max(0, maxPreviewSizeMB)
      : 0;
    const maxBytes = maxSize * 1024 * 1024;
    const existingPreviewCount = this.multiple()
      ? this.files().filter((file) => file.preview).length
      : 0;
    let remaining = Math.max(0, maxFiles - existingPreviewCount);

    for (const item of files) {
      if (remaining === 0) {
        break;
      }
      if (!item.type.startsWith('image/') || item.size > maxBytes) {
        continue;
      }

      remaining -= 1;
      const reader = new FileReader();
      reader.onload = (event) => {
        const preview = event.target?.result;
        if (typeof preview === 'string') {
          item.preview = preview;
          this.files.update((current) => [...current]);
        }
      };
      reader.readAsDataURL(item.file);
    }
  }

  private isAccepted(file: File): boolean {
    const rules = this.accept()
      .split(',')
      .map((rule) => rule.trim().toLowerCase())
      .filter(Boolean);
    if (rules.length === 0) {
      return true;
    }

    const name = file.name.toLowerCase();
    const type = file.type.toLowerCase();
    return rules.some((rule) => {
      if (rule.startsWith('.')) {
        return name.endsWith(rule);
      }
      if (rule.endsWith('/*')) {
        return type.startsWith(rule.slice(0, -1));
      }
      return type === rule;
    });
  }

  removeFile(f: FileInputFile) {
    if (this.isDisabled()) return;
    this.files.update((fs) => fs.filter((x) => x !== f));
    this.onChange(this.files());
    this.filesChange.emit(this.files());
    this.fileRemoved.emit(f);
    this.onTouched();
  }

  clearFiles(): void {
    if (this.isDisabled()) return;
    this.validationError.set('');
    this.files.set([]);
    if (this.fileInputRef?.nativeElement) {
      this.fileInputRef.nativeElement.value = '';
    }
    this.onChange([]);
    this.filesChange.emit([]);
    this.cleared.emit();
    this.onTouched();
  }

  onFileAction(f: FileInputFile): void {
    if (this.isDisabled()) return;
    this.fileAction.emit(f);
  }

  formatSize(bytes: number): string {
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  }

  // ControlValueAccessor
  writeValue(v: FileInputFile[]): void {
    this.files.set(v ?? []);
  }
  registerOnChange(fn: (v: FileInputFile[]) => void): void {
    this.onChange = fn;
  }
  registerOnTouched(fn: () => void): void {
    this.onTouched = fn;
  }
  setDisabledState(d: boolean): void {
    this.disabledByForm.set(d);
    this.changeDetectorRef.markForCheck();
  }
}

import { effect, untracked } from '@angular/core';
import {
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  inject,
  contentChild,
  input,
  output,
  signal,
  computed,
  TemplateRef,
  viewChild,
} from '@angular/core';
import { PageHeader, PageHeaderAlignment } from '../../organisms/page-header/page-header';
import { QueryToolbar } from '../../organisms/query-toolbar/query-toolbar';
import { DataTable, type DataTableColumn, type DataTableStatus } from '../../organisms/data-table/data-table';
import { StepperComponent, type Step } from '../../organisms/stepper/stepper.component';
import { CrudDialog } from '../../organisms/crud-dialog/crud-dialog';
import { ActionGroupComponent, type ActionItem } from '../../molecules/action-group/action-group.component';
import { resolveTableActionIcon, resolveTableActionTone } from '../../atoms/table-action/table-action';
import { SummaryListComponent, type SummaryListItem } from '../../molecules/summary-list/summary-list.component';
import { ButtonComponent } from '../../atoms/button/button.component';
import { InputComponent } from '../../atoms/input/input.component';
import { Select2Component, type Select2Option } from '../../molecules/select2/select2.component';
import { DatepickerComponent } from '../../molecules/datepicker/datepicker.component';
import { IconButtonComponent } from '../../atoms/icon-button/icon-button.component';
import { NgTemplateOutlet } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Alert } from '../../molecules/alert/alert.component';
import {
  type AccionesCrud,
  ACCIONES_CRUD_DEFECTO,
  type ModoCrud,
  type ContextoFormularioCrud,
  type SolicitudPagina,
  type AccionDirectaContextualCatalogo,
  type ConfiguracionConfirmacion,
  CONFIRMACION_BAJA_DEFECTO,
} from '../modelos-crud';

/**
 * Chasis A — Página CRUD canónica de entidad única.
 *
 * Compone los organismos Atomic (PageHeader, QueryToolbar, DataTable,
 * CrudDialog) en el patrón estándar definido por ADR-007:
 *   Vista principal = cabecera + barra de búsqueda + grilla + acciones
 *   Operaciones CRUD = diálogo modal con modos crear/editar/ver
 *
 * El consumidor NO recompone el diseño de tabla, acciones o ventanas. Solo:
 *   1. Declara columnas (DataTableColumn[])
 *   2. Proyecta el formulario con `<ng-template #formularioCrud>`
 *   3. Conecta las señales de datos y los eventos
 *
 * @ejemplo Uso mínimo por un agente:
 * ```html
 * <app-pagina-crud
 *   titulo="Clientes"
 *   [columnas]="columnas"
 *   [filas]="facade.elementos()"
 *   [estado]="facade.estado()"
 *   [totalRegistros]="facade.total()"
 *   [paginaActual]="facade.pagina()"
 *   [guardando]="facade.guardando()"
 *   [errorOperacion]="facade.errorOperacion()"
 *   (alSolicitarPagina)="facade.cargar($event)"
 *   (alCrear)="facade.abrirCrear()"
 *   (alEditar)="facade.abrirEditar($event)"
 *   (alVer)="facade.abrirVer($event)"
 *   (alEliminar)="facade.desactivar($event)"
 *   (alGuardar)="facade.guardar()"
 *   (alCerrarDialogo)="facade.cerrarDialogo()"
 * >
 *   <ng-template #formularioCrud let-ctx>
 *     <!-- Campos del formulario según ctx.modo -->
 *   </ng-template>
 * </app-pagina-crud>
 * ```
 */
export interface FiltroBusqueda {
  label: string;
  value: string;
  tipo?: 'texto' | 'select' | 'fecha';
  opcionesSelect?: Select2Option[];
}

@Component({
  selector: 'app-pagina-crud',
  host: { role: 'region', '[attr.aria-label]': 'titulo()', tabindex: '-1' },
  standalone: true,
  imports: [ FormsModule,
    PageHeader,
    QueryToolbar,
    DataTable,
    ButtonComponent,
    InputComponent,
    Select2Component,
    DatepickerComponent,
    IconButtonComponent,
    NgTemplateOutlet,
    Alert,
    CrudDialog,
    StepperComponent,
    ActionGroupComponent,
    SummaryListComponent,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './pagina-crud.html',
  styleUrl: './pagina-crud.scss',
})
export class PaginaCrud<T extends object = Record<string, unknown>> {
  // ─── Configuración de la página ──────────────────────────────
  private readonly elementoHost = inject<ElementRef<HTMLElement>>(ElementRef);
  readonly resolverFocoRetorno = input<(() => HTMLElement | null) | null>(null);

  obtenerDestinoFocoRetorno(): HTMLElement {
    return this.elementoHost.nativeElement;
  }

  readonly titulo = input.required<string>();
  readonly subtitulo = input<string | null>(null);
  readonly headerAlign = input<PageHeaderAlignment>('center');
  readonly etiquetaNuevo = input('Crear Nuevo');
  readonly embedded = input(false);
  readonly iconoNuevo = input('fa-solid fa-plus');

  // Opciones para búsqueda en cascada
  readonly opcionesBusqueda = input<readonly FiltroBusqueda[]>([]);
  readonly tipoBusqueda = input<string | null>(null);
  readonly alCambiarTipoBusqueda = output<string | null>();
  readonly placeholderBusqueda = input('Buscar…');
  readonly captionTabla = input('');

  // Estado UI interno para la cascada — signal puro.
  readonly tipoBusquedaInterno = signal<string | null>(null);

  readonly labelFiltroSecundario = computed(() => {
    const seleccion = this.tipoBusquedaInterno();
    return this.opcionesBusqueda().find(x => x.value === seleccion)?.label ?? 'Valor de Búsqueda';
  });

  /** Devuelve 'select' o 'texto' según la opción elegida. */
  constructor() {
    effect(() => {
      const tipo = this.tipoBusqueda() || null;
      untracked(() => {
        if (this.tipoBusquedaInterno() !== tipo) {
          this.tipoBusquedaInterno.set(tipo);
          this.busqueda.set('');
        }
      });
    });
    effect(() => {
      const opciones = this.opcionesBusqueda();
      untracked(() => {
        const actual = this.tipoBusquedaInterno();
        if (actual !== null && !opciones.some(o => o.value === actual)) {
          this.tipoBusquedaInterno.set(null);
          this.busqueda.set('');
        }
      });
    });
  }

  protected getTipoFiltro(tipo: string): 'select' | 'fecha' | 'texto' {
    const filtro = this.opcionesBusqueda().find(o => o.value === tipo);
    if (filtro?.tipo === 'select') return 'select';
    if (filtro?.tipo === 'fecha') return 'fecha';
    return 'texto';
  }

  /** Devuelve las opciones del select secundario. */
  protected getOpcionesFiltro(tipo: string): Select2Option[] {
    const filtro = this.opcionesBusqueda().find(o => o.value === tipo);
    return filtro?.opcionesSelect ?? [];
  }

  protected getOpcionesFiltroConVacio(tipo: string): Select2Option[] {
    const opciones = this.getOpcionesFiltro(tipo);
    return [
      { label: 'Seleccionar...', value: null },
      ...opciones
    ];
  }

  protected readonly opcionesFiltroSecundario = computed<Select2Option[]>(() => {
    const tipo = this.tipoBusquedaInterno();
    if (!tipo) return [];
    return this.getOpcionesFiltroConVacio(tipo);
  });

  protected readonly opcionesBusquedaParaSelect = computed<Select2Option[]>(() => {
    const opciones = this.opcionesBusqueda();
    if (opciones.length === 0) return [];
    return [
      { label: 'Seleccionar...', value: null },
      ...opciones.map(o => ({ label: o.label, value: o.value, icon: undefined, disabled: false })),
    ];
  });

  // ─── Datos de la grilla ──────────────────────────────────────
  readonly columnas = input.required<readonly DataTableColumn<T>[]>();
  readonly filas = input.required<readonly T[]>();
  readonly estado = input<DataTableStatus>('idle');
  readonly paginaActual = input(1);
  readonly totalRegistros = input<number | null>(null);
  readonly tamanioPagina = input(10);
  readonly totalPaginas = input(1);
  readonly tienePaginaAnterior = input(false);
  readonly tienePaginaSiguiente = input(false);
  readonly incluirInactivos = input(false);

  // ─── Configuración de acciones ───────────────────────────────
  readonly acciones = input<AccionesCrud>(ACCIONES_CRUD_DEFECTO);
  readonly confirmacionBaja = input<ConfiguracionConfirmacion>(CONFIRMACION_BAJA_DEFECTO);
  /** El consumidor decide permisos y acciones disponibles, nunca el ADN. */
  readonly accionesPorFila = input<((fila: T) => ActionItem[]) | null>(null);
  /**
   * Excepción declarada para mostrar una tercera acción directa de catálogo.
   * Sin evidencia válida, el presupuesto conserva Ver, Editar y el disparador
   * Más acciones como sus tres controles físicos.
   */
  readonly accionDirectaContextual = input<AccionDirectaContextualCatalogo | null>(null);
  /** Opt-in compatible. Finalizar con resolverConfirmacion tras la respuesta real. */
  readonly confirmacionControlada = input(false);
  readonly alAccionFila = output<{ accion: string; entidad: T }>();
  readonly alConfirmarAccion = output<{ accion: string; entidad: T }>();
  /** Detalle semántico; null conserva la proyección histórica. */
  readonly detalle = input<readonly SummaryListItem[] | null>(null);

  // ─── Estado del diálogo CRUD ─────────────────────────────────
  readonly modoCrud = input<ModoCrud>('crear');
  readonly entidadActiva = input<T | null>(null);
  readonly guardando = input(false);
  /** Guarda visual explícita para adopciones parciales; no conoce la operación. */
  readonly bloquearCierre = input(false);
  /** El consumidor decide validez y cambios reales; true conserva compatibilidad. */
  readonly guardarHabilitado = input(true);
  readonly errorOperacion = input<string | null>(null);

  // ─── Configuración de Interacción (Wizard/Browser/Popup) ──────
  readonly interaccionCrear = input<'popup' | 'stepper' | 'browser'>('popup');
  readonly interaccionEditar = input<'popup' | 'stepper' | 'browser'>('popup');
  readonly interaccionVer = input<'popup' | 'stepper' | 'browser'>('popup');
  readonly interaccionEliminar = input<'popup' | 'stepper' | 'browser'>('popup');

  protected interaccionActual(): 'popup' | 'stepper' | 'browser' {
    const modo = this.modoCrud();
    if (modo === 'crear') return this.interaccionCrear();
    if (modo === 'editar') return this.interaccionEditar();
    if (modo === 'ver') return this.interaccionVer();
    return 'popup';
  }
  readonly wizardSteps = input<Step[]>([]);
  readonly wizardActiveStep = input<number>(0);
  readonly wizardAllowSkip = input<boolean>(false);
  readonly alCambiarPasoWizard = output<number>();

  // ─── Configuración del diálogo ───────────────────────────────
  readonly tamanoDialogo = input<'sm' | 'md' | 'lg' | 'xl'>('md');

  // ─── Eventos ─────────────────────────────────────────────────
  /** Se emite cuando la tabla necesita datos (cambio de página, búsqueda). */
  readonly alSolicitarPagina = output<SolicitudPagina>();
  /** Se emite al pulsar el botón "Nuevo". */
  readonly alCrear = output<void>();
  /** Se emite al pulsar el botón "Ver" en una fila. */
  readonly alVer = output<T>();
  /** Se emite al pulsar el botón "Editar" en una fila. */
  readonly alEditar = output<T>();
  /** Se emite al confirmar la baja lógica de una fila. */
  readonly alEliminar = output<T>();
  /** Se emite al pulsar "Guardar" en el diálogo CRUD. */
  readonly alGuardar = output<void>();
  /** Se emite al cerrar el diálogo CRUD (cancelar o escape). */
  readonly alCerrarDialogo = output<void>();
  /** Se emite al pulsar "Reintentar" en la grilla. */
  readonly alReintentar = output<void>();

  // ─── Referencias internas ────────────────────────────────────
  /** Referencia al CrudDialog nativo para showModal/close. */
  protected readonly dialogoCrud = viewChild<CrudDialog>('dialogoCrud');
  protected readonly dialogoConfirmacion = viewChild<CrudDialog>('dialogoConfirmacion');

  /** Plantilla del formulario proyectada por el consumidor. */
  protected readonly formularioCrud =
    contentChild<TemplateRef<ContextoFormularioCrud<T>>>('formularioCrud');

  // ─── Estado local ────────────────────────────────────────────
  protected readonly busqueda = signal('');
  protected readonly mostrarConfirmacion = signal(false);
  protected readonly entidadAEliminar = signal<T | null>(null);
  protected readonly confirmacionEnviada = signal(false);
  private readonly configuracionAccion = signal<ConfiguracionConfirmacion | null>(null);
  private accionConfirmada = 'eliminar';

  private static contadorInstancias = 0;
  /** ID para aria-labelledby del diálogo. */
  protected readonly idTituloDialogo = `pagina-crud-dialogo-${++PaginaCrud.contadorInstancias}`;
  protected readonly idTituloConfirmacion = `${this.idTituloDialogo}-confirmacion`;
  protected readonly idMensajeConfirmacion = `${this.idTituloDialogo}-mensaje`;
  protected readonly bloqueadaConfirmacion = computed(() => this.guardando() || this.confirmacionEnviada());

  // ─── Título dinámico del diálogo según el modo ───────────────
  protected tituloDialogo(): string {
    const base = this.titulo();
    switch (this.modoCrud()) {
      case 'crear': return `Nuevo ${base}`;
      case 'editar': return `Editar`;
      case 'ver': return `Visualización`;
    }
  }

  // ─── Contexto del formulario proyectado ──────────────────────
  protected contextoFormulario(): ContextoFormularioCrud<T> {
    const entidad = this.entidadActiva();
    return {
      $implicit: entidad,
      entidad,
      modo: this.modoCrud(),
      guardando: this.guardando(),
    };
  }

  // ─── Acciones de la grilla ───────────────────────────────────
  /** Actualiza la cascada de UI internamente y notifica al padre. */
  protected onTipoBusquedaCambiado(valor: string | null): void {
    this.tipoBusquedaInterno.set(valor);
    this.busqueda.set('');
    this.alCambiarTipoBusqueda.emit(valor);
    this.alSolicitarPagina.emit({
      pagina: 1,
      tamano: this.tamanioPagina(),
      busqueda: '',
    });
  }

  protected alBuscar(termino: string | Date | null): void {
    let term = '';
    if (termino instanceof Date && !Number.isNaN(termino.getTime())) {
      const anio = termino.getFullYear();
      const mes = String(termino.getMonth() + 1).padStart(2, '0');
      const dia = String(termino.getDate()).padStart(2, '0');
      term = `${anio}-${mes}-${dia}`;
    } else if (typeof termino === 'string') {
      term = termino;
    }
    this.busqueda.set(term);
    this.alSolicitarPagina.emit({
      pagina: 1,
      tamano: this.tamanioPagina(),
      busqueda: term,
    });
  }

  protected alCambiarPagina(pagina: number): void {
    this.alSolicitarPagina.emit({
      pagina,
      tamano: this.tamanioPagina(),
      busqueda: this.busqueda(),
    });
  }

  protected alCambiarTamanioPagina(tamano: number): void {
    this.alSolicitarPagina.emit({
      pagina: 1,
      tamano,
      busqueda: this.busqueda(),
    });
  }

  // ─── Gestión del diálogo CRUD ────────────────────────────────
  protected solicitarGuardar(): void {
    if (this.guardando() || !this.guardarHabilitado() || this.modoCrud() === 'ver') return;
    this.alGuardar.emit();
  }

  /** Abre el diálogo con foco en el primer campo habilitado. */
  abrirDialogo(): void {
    this.dialogoCrud()?.showModal();
  }

  /** Cierra el diálogo y devuelve el foco al origen. */
  cerrarDialogo(): void {
    if (this.guardando() || this.bloquearCierre() || !this.dialogoCrud()?.open) return;
    this.dialogoCrud()?.close();
    this.alCerrarDialogo.emit();
  }

  /** Enfoca el primer error visible tras un fallo de guardado. */
  enfocarError(): void {
    this.dialogoCrud()?.focusError();
  }

  // ─── Baja lógica con confirmación (Doctrina §7 y §12) ───────
  protected solicitarBaja(entidad: T): void {
    if (this.interaccionEliminar() === 'browser') {
      // Si el modo es browser, omitimos el popup de confirmación interno
      // y delegamos la acción al consumidor (quien debe hacer la navegación o confirmación)
      this.alEliminar.emit(entidad);
    } else {
      this.abrirConfirmacion(entidad, this.confirmacionBaja());
    }
  }

  /** Configuración declarada por el consumidor; no deduce activar/baja del DTO. */
  abrirConfirmacion(entidad: T, configuracion: ConfiguracionConfirmacion, accion = 'eliminar'): void {
    if (this.bloqueadaConfirmacion()) return;
    this.accionConfirmada = accion;
    this.configuracionAccion.set(configuracion);
    this.entidadAEliminar.set(entidad);
    this.mostrarConfirmacion.set(true);
    this.dialogoConfirmacion()?.showModal('[data-dialog-initial-focus] button');
  }

  protected confirmarBaja(): void {
    if (this.bloqueadaConfirmacion()) return;
    const entidad = this.entidadAEliminar();
    if (entidad) {
      // El opt-in conserva contexto hasta la respuesta y bloquea doble emisión.
      this.confirmacionEnviada.set(this.confirmacionControlada());
      if (this.accionConfirmada === 'eliminar') this.alEliminar.emit(entidad);
      else this.alConfirmarAccion.emit({ accion: this.accionConfirmada, entidad });
    }
    if (!this.confirmacionControlada()) this.cancelarBaja();
  }

  /** El consumidor llama tras el resultado; un error conserva la confirmación. */
  resolverConfirmacion(exito: boolean): void {
    this.confirmacionEnviada.set(false);
    if (exito) this.cerrarConfirmacion();
    else this.dialogoConfirmacion()?.focusError();
  }

  protected cancelarBaja(): void {
    if (this.bloqueadaConfirmacion()) return;
    this.cerrarConfirmacion();
  }

  private cerrarConfirmacion(): void {
    this.dialogoConfirmacion()?.close();
    this.mostrarConfirmacion.set(false);
    this.entidadAEliminar.set(null);
    this.configuracionAccion.set(null);
  }

  // ─── Utilidades para el template ─────────────────────────────
  protected get accionesResueltas(): Required<AccionesCrud> {
    return { ...ACCIONES_CRUD_DEFECTO, ...this.acciones() };
  }

  protected get confResueltas(): Required<ConfiguracionConfirmacion> {
    return { ...CONFIRMACION_BAJA_DEFECTO, ...(this.configuracionAccion() ?? this.confirmacionBaja()) };
  }

  protected get esModoPrevisualizacion(): boolean {
    return this.modoCrud() === 'ver';
  }

  protected getGridActions(fila: T): ActionItem[] {
    return this.planAccionesGrid(fila).acciones;
  }

  /** Presupuesto directo del chasis; ActionGroup sigue siendo genérico. */
  protected maximoAccionesDirectas(fila: T): 2 | 3 {
    return this.planAccionesGrid(fila).maximoDirectas;
  }

  private planAccionesGrid(fila: T): { acciones: ActionItem[]; maximoDirectas: 2 | 3 } {
    const acciones = this.accionesIniciales(fila).map((accion) => this.accionCatalogo(accion));
    const accionContextual = this.resolverAccionDirectaContextual(acciones);
    const directas = [
      this.primeraAccionDirecta(acciones, (accion) => this.esAccionVer(accion)),
      this.primeraAccionDirecta(acciones, (accion) => this.esAccionEditar(accion)),
      accionContextual,
    ].filter((accion): accion is ActionItem => accion !== undefined && accion !== null);

    return {
      // El orden de las directas es contractual: Ver, Editar y, solo cuando
      // corresponde, la excepción contextual. El resto conserva su orden
      // relativo original dentro de Más acciones.
      acciones: [
        ...directas.map((accion) => ({ ...accion, isMenuOnly: false })),
        ...acciones
          .filter((accion) => !directas.includes(accion))
          .map((accion) => ({ ...accion, isMenuOnly: true })),
      ],
      maximoDirectas: accionContextual ? 3 : 2,
    };
  }

  private accionesIniciales(fila: T): ActionItem[] {
    const declaradas = this.accionesPorFila();
    if (declaradas) return declaradas(fila).map((accion) => ({ ...accion }));

    const acts: ActionItem[] = [];
    if (this.accionesResueltas.ver) acts.push({ id: 'ver', action: 'view', label: 'Ver detalle' });
    if (this.accionesResueltas.editar) acts.push({ id: 'editar', action: 'edit', label: 'Editar' });
    if (this.accionesResueltas.eliminar) {
      acts.push({ id: 'eliminar', action: 'deactivate', label: 'Desactivar', isMenuOnly: true });
    }
    return acts;
  }

  private primeraAccionDirecta(
    acciones: readonly ActionItem[],
    coincide: (accion: ActionItem) => boolean,
  ): ActionItem | undefined {
    return acciones.find((accion) => this.esElegibleAccionDirecta(accion) && coincide(accion));
  }

  private resolverAccionDirectaContextual(acciones: readonly ActionItem[]): ActionItem | null {
    const declaracion = this.accionDirectaContextual();
    if (!declaracion
      || !declaracion.idAccion.trim()
      || !declaracion.justificacion.trim()
      || !declaracion.evidencia.trim()) {
      return null;
    }

    const accion = acciones.find((candidata) => candidata.id === declaracion.idAccion);
    if (!accion
      || !this.esElegibleAccionDirecta(accion)
      || this.esAccionVer(accion)
      || this.esAccionEditar(accion)) {
      return null;
    }

    return accion;
  }

  private esAccionVer(accion: ActionItem): boolean {
    const identificador = accion.id.trim().toLowerCase();
    return accion.action === 'view' || identificador === 'ver' || identificador === 'view';
  }

  private esAccionEditar(accion: ActionItem): boolean {
    const identificador = accion.id.trim().toLowerCase();
    return accion.action === 'edit' || identificador === 'editar' || identificador === 'edit';
  }

  private esAccionDestructiva(accion: ActionItem): boolean {
    const identificador = accion.id.trim().toLowerCase();
    return accion.action === 'delete'
      || accion.action === 'deactivate'
      || accion.action === 'reverse'
      || identificador === 'delete'
      || identificador === 'deactivate'
      || identificador === 'reverse'
      || identificador === 'eliminar'
      || identificador === 'desactivar'
      || identificador === 'revertir';
  }

  private esAccionEstado(accion: ActionItem): boolean {
    const identificador = accion.id.trim().toLowerCase();
    return accion.action === 'activate'
      || accion.action === 'deactivate'
      || identificador === 'activate'
      || identificador === 'deactivate'
      || identificador === 'activar'
      || identificador === 'desactivar';
  }

  private esElegibleAccionDirecta(accion: ActionItem): boolean {
    return !accion.isMenuOnly
      && !this.esAccionContradictoria(accion)
      && !this.esAccionEstado(accion)
      && !this.esAccionDestructiva(accion)
      && accion.variant !== 'danger';
  }

  /** Una identidad que dice Ver y una semántica que dice Editar no se adivina. */
  private esAccionContradictoria(accion: ActionItem): boolean {
    return this.esAccionVer(accion) && this.esAccionEditar(accion);
  }

  private accionCatalogo(accion: ActionItem): ActionItem {
    const tipo = accion.action ?? 'custom';
    const tono = resolveTableActionTone(tipo, 'catalog');
    return {
      ...accion,
      icon: resolveTableActionIcon(tipo, accion.icon, 'catalog'),
      variant: accion.variant ?? (tono === 'neutral' ? 'default' : tono),
      disabled: accion.disabled || this.guardando(),
    };
  }

  protected handleGridAction(actionId: string, fila: T): void {
    const accion = this.getGridActions(fila).find(item => item.id === actionId);
    if (!accion || accion.disabled || accion.loading) return;
    if (actionId === 'ver') this.alVer.emit(fila);
    else if (actionId === 'editar') this.alEditar.emit(fila);
    else if (actionId === 'eliminar') this.solicitarBaja(fila);
    else this.alAccionFila.emit({ accion: actionId, entidad: fila });
  }
}

import { ChangeDetectionStrategy, Component, inject, signal } from '@angular/core';

import { FormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { Observable, tap } from 'rxjs';
import {
  AuthLayoutComponent,
  FloatingInputComponent,
  ButtonComponent,
  CheckboxComponent,
  FormErrorComponent,
  PanelComponent,
  TextComponent,
  RowComponent,
  FormRowComponent,
  DividerComponent,
  FooterComponent
} from '@shared/ui';
import { ApiService } from '@shared/ui/services/api.service';
import { useApi } from '@shared/ui/services/use-api.service';

/**
 * Response from login API endpoint
 * @customize Adjust to match your API response structure
 */
interface LoginResponse {
  token: string;
  refreshToken?: string;
  user: {
    id: string;
    name: string;
    email: string;
    role?: string;
  };
}

/**
 * Response from register API endpoint
 * @customize Adjust to match your API response structure
 */
interface RegisterResponse {
  message: string;
  userId?: string;
}

/**
 * Response from forgot password API endpoint
 */
interface ForgotPasswordResponse {
  message: string;
}

/**
 * Login Page Blueprint
 *
 * Features:
 * - Login form with email/password
 * - Register form with validation
 * - Forgot password flow
 * - Remember me checkbox
 * - API integration with loading states
 * - Error handling and display
 *
 * @usage
 * 1. Copy this folder to your project's pages directory
 * 2. Update imports to match your project structure
 * 3. Configure API_BASE_URL to your backend
 * 4. Add route in app.routes.ts
 */
@Component({
  selector: 'app-login-page',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [
    ReactiveFormsModule,
    AuthLayoutComponent,
    FloatingInputComponent,
    ButtonComponent,
    CheckboxComponent,
    FormErrorComponent,
    PanelComponent,
    TextComponent,
    RowComponent,
    FormRowComponent,
    DividerComponent,
    FooterComponent
  ],
  templateUrl: './login-page.component.html',
  styleUrl: './login-page.component.css'
})
export class LoginPageComponent {
  private fb = inject(FormBuilder);
  private api = inject(ApiService);
  private router = inject(Router);

  // ============================================
  // CONFIGURATION - Customize these values
  // ============================================

  /** @customize Set your API base URL */
  private readonly API_BASE_URL = 'https://api.example.com/v1';

  /** @customize Route to redirect after successful login */
  private readonly REDIRECT_AFTER_LOGIN = '/dashboard';

  /** @customize Token storage key */
  private readonly TOKEN_KEY = 'auth_token';

  // ============================================
  // STATE
  // ============================================

  /** Current active view: 'login' | 'register' | 'forgot' */
  activeView = signal<'login' | 'register' | 'forgot'>('login');

  /** API state hooks */
  loginApi = useApi<LoginResponse>();
  registerApi = useApi<RegisterResponse>();
  forgotApi = useApi<ForgotPasswordResponse>();

  /** Success message for forgot password */
  forgotSuccessMessage = signal<string | null>(null);

  // ============================================
  // FORMS
  // ============================================

  loginForm = this.fb.group({
    email: ['', [Validators.required, Validators.email]],
    password: ['', [Validators.required, Validators.minLength(6)]],
    rememberMe: [false]
  });

  registerForm = this.fb.group({
    name: ['', [Validators.required, Validators.minLength(2)]],
    email: ['', [Validators.required, Validators.email]],
    password: ['', [Validators.required, Validators.minLength(8)]],
    confirmPassword: ['', [Validators.required]],
    acceptTerms: [false, [Validators.requiredTrue]]
  });

  forgotForm = this.fb.group({
    email: ['', [Validators.required, Validators.email]]
  });

  // ============================================
  // LIFECYCLE
  // ============================================

  constructor() {
    this.api.setBaseUrl(this.API_BASE_URL);
  }

  // ============================================
  // VIEW SWITCHING
  // ============================================

  goBack(): void {
    this.router.navigate(['/']);
  }

  showLogin(): void {
    this.activeView.set('login');
    this.resetAllForms();
  }

  showRegister(): void {
    this.activeView.set('register');
    this.resetAllForms();
  }

  showForgot(): void {
    this.activeView.set('forgot');
    this.resetAllForms();
  }

  private resetAllForms(): void {
    this.loginForm.reset();
    this.registerForm.reset();
    this.forgotForm.reset();
    this.loginApi.reset();
    this.registerApi.reset();
    this.forgotApi.reset();
    this.forgotSuccessMessage.set(null);
  }

  // ============================================
  // FORM SUBMISSIONS
  // ============================================

  onLogin(): void {
    if (this.loginForm.invalid) {
      this.loginForm.markAllAsTouched();
      return;
    }

    const { email, rememberMe } = this.loginForm.value;

    // Solicitud aislada de demostración. El consumidor reemplaza esta variable
    // por this.api.post<LoginResponse>('/auth/login', { email, password }).
    const request = new Observable<LoginResponse>(observer => {
        setTimeout(() => {
          observer.next({
            token: 'DEMO_TOKEN_EJEMPLO',
            user: {
              id: '1',
              name: 'Usuario de demostración',
              email: email || 'demo@example.com'
            }
          });
          observer.complete();
        }, 1500);
    });

    this.loginApi.execute(
      request.pipe(tap(response => this.handleLoginSuccess(response, rememberMe ?? false)))
    );
  }

  onRegister(): void {
    if (this.registerForm.invalid) {
      this.registerForm.markAllAsTouched();
      return;
    }

    const { password, confirmPassword } = this.registerForm.value;

    if (password !== confirmPassword) {
      // Handle password mismatch
      return;
    }

    const { name, email } = this.registerForm.value;

    this.registerApi.execute(
      this.api.post<RegisterResponse>('/auth/register', { name, email, password })
    );
  }

  onForgotPassword(): void {
    if (this.forgotForm.invalid) {
      this.forgotForm.markAllAsTouched();
      return;
    }

    const { email } = this.forgotForm.value;

    this.forgotApi.execute(
      this.api.post<ForgotPasswordResponse>('/auth/forgot-password', { email }).pipe(
        tap(response => this.forgotSuccessMessage.set(
          response.message || 'Se ha enviado un correo con instrucciones'
        ))
      )
    );
  }

  // ============================================
  // HANDLERS
  // ============================================

  private handleLoginSuccess(response: LoginResponse, rememberMe: boolean): void {
    // TODO: SECURITY - Migrar a cookies HttpOnly cuando el backend lo soporte
    // Los tokens en localStorage son vulnerables a ataques XSS
    const storage = rememberMe ? localStorage : sessionStorage;
    storage.setItem(this.TOKEN_KEY, response.token);

    // Set auth header for future requests
    this.api.setAuthToken(response.token);

    // Store user info if needed
    storage.setItem('user', JSON.stringify(response.user));

    // Navigate to dashboard
    this.router.navigate([this.REDIRECT_AFTER_LOGIN]);
  }

  // ============================================
  // FORM FIELD ERRORS
  // ============================================

  getFieldError(form: 'login' | 'register' | 'forgot', fieldName: string): string {
    let field;

    if (form === 'login') {
      field = this.loginForm.get(fieldName);
    } else if (form === 'register') {
      field = this.registerForm.get(fieldName);
    } else {
      field = this.forgotForm.get(fieldName);
    }

    if (!field || !field.touched || !field.errors) {
      return '';
    }

    if (field.errors['required']) {
      return 'Este campo es requerido';
    }
    if (field.errors['email']) {
      return 'Ingresa un email válido';
    }
    if (field.errors['minlength']) {
      const min = field.errors['minlength'].requiredLength;
      return `Mínimo ${min} caracteres`;
    }

    return '';
  }
}

import { NgTemplateOutlet } from '@angular/common';
import {
  AfterViewInit,
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  NgZone,
  OnDestroy,
  TemplateRef,
  computed,
  contentChild,
  inject,
  input,
  linkedSignal,
  output,
  signal,
} from '@angular/core';
import { TranslatePipe } from '@ngx-translate/core';
import { Alert } from '../../molecules/alert/alert.component';
import { ButtonComponent } from '../../atoms/button/button.component';
import { BadgeComponent, BadgeVariant } from '../../atoms/badge/badge.component';

import { ScrollOverlayComponent } from '../scroll-overlay/scroll-overlay.component';
import { VariablesCssDirective } from '../../directives/variables-css.directive';
import { Select2Component, Select2Option } from '../../molecules/select2/select2.component';
import { FormsModule } from '@angular/forms';

export type DataTableAlignment = 'start' | 'center' | 'end';
export type DataTableDensity = 'comfortable' | 'compact';
export type DataTablePaginationMode = 'none' | 'client' | 'server';
export type DataTableStatus = 'idle' | 'loading' | 'success' | 'empty' | 'error';
export type DataTableSortDirection = 'asc' | 'desc' | null;

export interface DataTableColumn<T extends object = Record<string, unknown>> {
  readonly key: Extract<keyof T, string>;
  readonly header: string;
  readonly sortable?: boolean;
  readonly align?: DataTableAlignment;
  readonly width?: string;
  readonly isBadge?: boolean;
  readonly badgeVariant?: (row: T) => BadgeVariant;
  readonly isTag?: boolean;
  readonly tagVariant?: (row: T) => BadgeVariant;
  readonly value?: (row: T) => unknown;
  readonly format?: (value: unknown, row: T) => string;
  readonly sortValue?: (row: T) => unknown;
  readonly compare?: (left: T, right: T) => number;
}

export interface DataTableSortChange<T extends object = Record<string, unknown>> {
  readonly key: Extract<keyof T, string>;
  readonly direction: DataTableSortDirection;
}

export interface DataTableActionContext<T extends object = Record<string, unknown>> {
  readonly $implicit: T;
  readonly row: T;
  readonly index: number;
}

export type DataTableTrackBy<T extends object = Record<string, unknown>> = (
  index: number,
  row: T,
) => unknown;

interface ActiveSort<T extends object> {
  readonly key: Extract<keyof T, string>;
  readonly direction: Exclude<DataTableSortDirection, null>;
}

interface IndexedRow<T extends object> {
  readonly row: T;
  readonly originalIndex: number;
}

function trackByIdentity<T extends object>(_index: number, row: T): T {
  return row;
}

@Component({
  selector: 'app-data-table, prest-data-table',
  imports: [
    Alert,
    ButtonComponent,
    NgTemplateOutlet,
    ScrollOverlayComponent,
    BadgeComponent,
    VariablesCssDirective,
    Select2Component,
    FormsModule,
    TranslatePipe,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './data-table.html',
  styleUrl: './data-table.scss',
})
export class DataTable<T extends object = Record<string, unknown>> implements AfterViewInit, OnDestroy {
  private readonly host = inject<ElementRef<HTMLElement>>(ElementRef);
  private readonly zone = inject(NgZone);
  readonly columns = input.required<readonly DataTableColumn<T>[]>();
  readonly rows = input.required<readonly T[]>();
  readonly caption = input.required<string>();
  readonly captionVisible = input(false);
  readonly density = input<DataTableDensity>('comfortable');
  readonly status = input<DataTableStatus>('success');
  readonly loadingMessage = input('Cargando información…');
  readonly idleMessage = input('Aún no se ha cargado información.');
  readonly emptyMessage = input('No hay información para mostrar.');
  readonly errorMessage = input('No fue posible cargar la información.');
  readonly retryLabel = input('Reintentar');
  readonly actionsHeader = input('Acciones');
  readonly actionsWidth = input('12rem');
  readonly emptyValue = input('—');
  readonly trackBy = input<DataTableTrackBy<T>>(trackByIdentity);
  readonly showRowNumber = input(true);
  readonly rowNumberHeader = input('N.º');
  readonly rowNumberWidth = input('4.5rem');

  // Row numbering and local pagination remain the published defaults.
  // Consumers may opt out of pagination explicitly with `none`.
  readonly pagination = input<DataTablePaginationMode>('client');
  readonly totalRecords = input<number | null>(null);
  readonly page = input(1);
  readonly pageSize = input(10);
  readonly totalPages = input(1);
  readonly pageSizeOptions = input<readonly number[]>([10, 20, 50, 100]);
  readonly hasPreviousPage = input(false);
  readonly hasNextPage = input(false);

  readonly sortChange = output<DataTableSortChange<T>>();
  readonly retry = output<void>();
  readonly pageChange = output<number>();
  readonly pageSizeChange = output<number>();

  protected readonly actionsTemplate =
    contentChild<TemplateRef<DataTableActionContext<T>>>('actions');

  private readonly activeSort = signal<ActiveSort<T> | null>(null);
  private readonly internalPage = linkedSignal(() => Math.max(this.page(), 1));
  private readonly internalPageSize = linkedSignal(() => Math.max(this.pageSize(), 1));
  private readonly collator = new Intl.Collator('es-PE', {
    numeric: true,
    sensitivity: 'base',
  });

  protected readonly usesClientPagination = computed(
    () => this.pagination() === 'client' && this.totalRecords() === null,
  );
  protected readonly paginationEnabled = computed(
    () => this.pagination() !== 'none',
  );
  protected readonly effectivePageSize = computed(() => this.internalPageSize());
  /*
    El desplegable «POR PÁGINA» tiene que poder mostrar el tamaño REALMENTE
    vigente, aunque nadie lo haya incluido en la lista de opciones.

    Sin esto, un consumidor que fije `[pageSize]="25"` con las opciones por
    omisión —10, 20, 30, 40, 50— obtiene una tabla que pagina de 25 en 25 y un
    desplegable sin ninguna opción que coincida, que queda en blanco: el
    paginador contradice a su propia tabla y el usuario no puede saber de cuánto
    está paginando.

    Se inserta ordenado, no al final, para que la escala siga leyéndose.
  */
  protected readonly effectivePageSizeOptions = computed<readonly number[]>(() => {
    const options = this.pageSizeOptions();
    const current = this.effectivePageSize();
    return options.includes(current)
      ? options
      : [...options, current].sort((first, second) => first - second);
  });
  protected readonly pageSizeSelectOptions = computed<Select2Option[]>(() => {
    return this.effectivePageSizeOptions().map((size) => ({
      value: size,
      label: String(size),
    }));
  });
  protected readonly effectiveTotalRecords = computed(
    () => this.totalRecords() ?? this.sortedRows().length,
  );
  protected readonly effectiveTotalPages = computed(() => {
    if (!this.paginationEnabled()) {
      return 1;
    }
    if (!this.usesClientPagination()) {
      return Math.max(this.totalPages(), 1);
    }
    return Math.max(
      Math.ceil(this.effectiveTotalRecords() / this.effectivePageSize()),
      1,
    );
  });
  protected readonly effectivePage = computed(() => {
    if (!this.paginationEnabled()) return 1;
    return this.usesClientPagination()
      ? Math.min(this.internalPage(), this.effectiveTotalPages())
      : this.internalPage();
  });
  protected readonly effectiveHasPreviousPage = computed(() =>
    this.usesClientPagination()
      ? this.effectivePage() > 1
      : this.hasPreviousPage(),
  );
  protected readonly effectiveHasNextPage = computed(() =>
    this.usesClientPagination()
      ? this.effectivePage() < this.effectiveTotalPages()
      : this.hasNextPage(),
  );

  protected readonly rangeStart = computed(() => {
    const total = this.effectiveTotalRecords();
    if (total === 0) return 0;
    return (this.effectivePage() - 1) * this.effectivePageSize() + 1;
  });

  protected readonly rangeEnd = computed(() => {
    const total = this.effectiveTotalRecords();
    if (total === 0) return 0;
    return Math.min(this.effectivePage() * this.effectivePageSize(), total);
  });

  protected onPageSizeSelectionChange(value: string | number): void {
    const pageSize = Number(value);
    this.internalPageSize.set(pageSize);
    if (this.usesClientPagination()) {
      this.internalPage.set(1);
      return;
