import { Injectable, computed, signal } from '@angular/core';
import { Observable, from } from 'rxjs';
import {
  ConfirmDialogCloseReason,
  ConfirmDialogOptions,
  ConfirmDialogResult,
  ConfirmDialogViewModel,
} from './confirm-dialog.models';

interface PendingConfirmEntry {
  readonly viewModel: ConfirmDialogViewModel;
  readonly resolve: (result: ConfirmDialogResult) => void;
}

/**
 * Servicio de presentación para gestionar una cola de confirmaciones globales.
 */
@Injectable({ providedIn: 'root' })
export class ConfirmDialogService {
  private readonly queue = signal<readonly PendingConfirmEntry[]>([]);
  private sequence = 0;

  readonly active = computed<ConfirmDialogViewModel | null>(() => {
    const entries = this.queue();
    return entries.length > 0 ? entries[0].viewModel : null;
  });

  readonly pendingCount = computed<number>(() => this.queue().length);

  confirm(options: ConfirmDialogOptions): Promise<ConfirmDialogResult> {
    this.sequence += 1;
    const id = options.id ?? `confirm-dialog-${this.sequence}`;
    const viewModel: ConfirmDialogViewModel = {
      id,
      title: options.title,
      subtitle: options.subtitle,
      message: options.message,
      confirmLabel: options.confirmLabel ?? 'Confirmar',
      cancelLabel: options.cancelLabel ?? 'Cancelar',
      tone: options.tone ?? 'danger',
      initialFocus: options.initialFocus ?? 'cancel',
      closeOnEscape: options.closeOnEscape ?? true,
      closeOnBackdrop: options.closeOnBackdrop ?? false,
      headerAlign: options.headerAlign ?? 'center',
    };

    return new Promise<ConfirmDialogResult>((resolve) => {
      this.queue.update((current) => [...current, { viewModel, resolve }]);
    });
  }

  confirm$(options: ConfirmDialogOptions): Observable<ConfirmDialogResult> {
    return from(this.confirm(options));
  }

  settle(id: string, reason: ConfirmDialogCloseReason): void {
    const current = this.queue();
    const target = current.find((entry) => entry.viewModel.id === id);
    if (!target) {
      return;
    }

    this.queue.set(current.filter((entry) => entry.viewModel.id !== id));
    target.resolve({
      id,
      confirmed: reason === 'confirmed',
      reason,
    });
  }

  dismissAll(): void {
    const pending = this.queue();
    if (pending.length === 0) {
      return;
    }

    this.queue.set([]);
    for (const entry of pending) {
      entry.resolve({
        id: entry.viewModel.id,
        confirmed: false,
        reason: 'dismissed',
      });
    }
  }
}

import { ErrorHandler, Injectable, inject, NgZone } from '@angular/core';
import { Router } from '@angular/router';
import { HttpErrorResponse } from '@angular/common/http';

/**
 * GlobalErrorHandlerService — Captura errores no manejados en la aplicación.
 *
 * Features:
 * - Captura errores de JavaScript no atrapados (runtime errors)
 * - Redirige a /500 en errores críticos
 * - Registra errores en consola (reemplaza por tu servicio de monitoreo)
 * - Ignora errores conocidos no críticos
 *
 * @usage En app.config.ts:
 * ```typescript
 * import { GlobalErrorHandlerService } from '@shared/ui';
 * providers: [
 *   { provide: ErrorHandler, useClass: GlobalErrorHandlerService }
 * ]
 * ```
 */
@Injectable()
export class GlobalErrorHandlerService implements ErrorHandler {
  private readonly router = inject(Router);
  private readonly zone = inject(NgZone);

  /** Errores a ignorar (fragmentos de mensaje) */
  private readonly IGNORED_ERRORS = [
    'ExpressionChangedAfterItHasBeenCheckedError',
    'ResizeObserver loop',
    'Non-Error promise rejection',
  ];

  handleError(error: unknown): void {
    const err = error instanceof Error ? error : new Error(String(error));

    // Ignorar errores no críticos
    if (this.shouldIgnore(err)) {
      return;
    }

    // Log para desarrollo — @customize: reemplaza con Sentry, Datadog, etc.
    console.error('[GlobalErrorHandler]', err);

    // Redirigir a página de error en zona Angular
    this.zone.run(() => {
      // Solo redirige si es un error crítico y estamos en el browser
      if (typeof window !== 'undefined') {
        document.body.innerHTML = '<div style="padding:2.5rem;background:red;color:white;position:fixed;top:0;left:0;width:100%;height:100%;z-index:999999;font-size:1.25rem;overflow:auto;"><pre>' + err.stack + '</pre></div>';
      }
    });
  }

  private shouldIgnore(error: Error): boolean {
    if (error instanceof HttpErrorResponse && error.status === 403) {
      return true;
    }

    // A veces Angular envuelve los errores en un "rejection" promise
    if ('rejection' in error && error['rejection'] instanceof HttpErrorResponse && error['rejection'].status === 403) {
      return true;
    }

    return this.IGNORED_ERRORS.some(ignored =>
      error.message?.includes(ignored)
    );
  }
}

