:host {
  display: block;
  min-width: 0;
  max-width: 100%;
}

:host.alert-flow--default { margin-block: calc(var(--alert-flow-gap) / 2); }
:host.alert-flow--compact { margin-block: calc(var(--alert-flow-gap-compact) / 2); }
:host.alert-flow--none { margin-block: 0; }

/* Una sola superficie para el showcase y sus consumidores. El acento comunica
   el tono; el texto usa contraste de lectura, nunca el color de relleno. */
.alert {
  min-width: 0;
  display: flex;
  align-items: flex-start;
  gap: var(--space-3);
  padding: var(--space-4);
  border: 0;
  border-inline-start: var(--space-1) solid var(--alert-accent);
  border-radius: var(--radius-md);
  background: var(--alert-background);
  color: var(--text-color);
  font-size: var(--text-sm);
  line-height: 1.5;
}

.alert--compact {
  gap: var(--space-2);
  padding: var(--space-3);
  line-height: 1.35;
}

.alert--collapsed {
  align-items: center;
}

.alert__icon {
  flex: 0 0 auto;
  color: var(--alert-symbol);
  font-size: var(--text-lg);
  line-height: inherit;
}

.alert--compact .alert__icon {
  font-size: var(--text-sm);
}

.alert__body {
  flex: 1;
  min-width: 0;
  overflow-wrap: anywhere;
}

.alert__title {
  margin-inline-end: var(--space-2);
  font-weight: var(--font-weight-title);
}

.alert__message {
  display: inline;
  overflow-wrap: anywhere;
}

.alert__message--collapsed {
  display: none;
}

.alert__toggle {
  flex: 0 0 auto;
}

.alert__close { flex: 0 0 auto; }

.alert--info {
  --alert-background: var(--alert-info-bg);
  --alert-accent: var(--alert-info-border);
  --alert-symbol: var(--alert-info-text);
}
.alert--success {
  --alert-background: var(--alert-success-bg);
  --alert-accent: var(--alert-success-border);
  --alert-symbol: var(--alert-success-text);
}
.alert--warning {
  --alert-background: var(--alert-warning-bg);
  --alert-accent: var(--alert-warning-border);
  --alert-symbol: var(--alert-warning-text);
}
.alert--danger {
  --alert-background: var(--alert-danger-bg);
  --alert-accent: var(--alert-danger-border);
  --alert-symbol: var(--alert-danger-text);
}

components.templateData:
@if (visible()) {
      <div
        class="alert"
        [class]="classes()"
        [attr.role]="kind() === 'danger' ? 'alert' : 'status'"
        [attr.aria-live]="kind() === 'danger' ? 'assertive' : 'polite'"
      >
        @if (kind() === 'info') {
          <i class="fa-solid fa-circle-info alert__icon" aria-hidden="true"></i>
        } @else if (kind() === 'success') {
          <i class="fa-solid fa-circle-check alert__icon" aria-hidden="true"></i>
        } @else if (kind() === 'warning') {
          <i class="fa-solid fa-triangle-exclamation alert__icon" aria-hidden="true"></i>
        } @else if (kind() === 'danger') {
          <i class="fa-solid fa-xmark alert__icon" aria-hidden="true"></i>
        }

        <div class="alert__body">
          @if (title() || (collapsible() && collapsed())) {
            <strong class="alert__title">{{ title() || collapsedTitle() }}</strong>
          }
          <div class="alert__message" [class.alert__message--collapsed]="collapsible() && collapsed()" [hidden]="collapsible() && collapsed()"><ng-content /></div>
        </div>

        @if (collapsible()) {
          <app-table-action class="alert__toggle" action="custom"
            [iconClass]="collapsed() ? 'fa-chevron-down' : 'fa-chevron-up'"
            [label]="collapsed() ? 'Expandir mensaje' : 'Contraer mensaje'"
            tone="neutral" size="sm" (triggered)="toggleCollapsed()" />
        }

        @if (closable()) {
          <app-table-action class="alert__close" action="custom" iconClass="fa-xmark"
            label="Cerrar mensaje" tone="neutral" size="sm" (triggered)="close()" />
        }
      </div>
    }

