.auth-layout-container {
  display: flex;
  height: 100vh;
  width: 100vw;
  overflow: hidden;
  background-color: var(--surface-background);
}

.auth-layout-main {
  flex: 1;
  display: flex;
  flex-direction: column;
  position: relative;
  background-color: var(--surface-section);
  width: 100%;
  min-height: 0;
  overflow: hidden;
}

@media (min-width: 64rem) {
  .auth-layout-main {
    max-width: 50%;
  }
}

.auth-scroll-content {
  display: flex;
  flex-direction: column;
  min-height: 100%;
  padding: var(--space-6);
}

.auth-top-nav {
  display: flex;
  justify-content: flex-start;
  margin-bottom: var(--space-6);
}

.auth-form-wrapper {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: var(--space-8) 0;
}

.auth-card {
  width: 100%;
  max-width: 27.5rem;
  background-color: var(--surface-background);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-xl);
