}

/* Overflow badge */
.overflow-badge {
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  /* --color-neutral-200 no se define en ningun tema: el respaldo era el valor, y
     por eso el contador de sobrantes se quedaba en gris claro sobre pagina oscura,
     con su propio texto encima. --surface-section es la superficie neutra del tema
     y es la misma pareja que usa la variante `default` del badge, que es lo que
     este contador es. */
  background: var(--surface-section);
