}

.crud-dialog::backdrop {
  background: var(--modal-overlay);
  backdrop-filter: blur(var(--space-1));
}

@media (max-width: 36rem) {
  .crud-dialog {
    width: calc(100% - var(--space-4));
    max-height: calc(100dvh - var(--space-4));
