      top: -0.5rem !important;
      right: -0.5rem !important;
    }
  }
}

.crud-dialog.side-panel {
  margin: 0;
  margin-left: auto;
  border-radius: var(--radius-lg) 0 0 var(--radius-lg);
  height: 100dvh;
  max-height: 100dvh;
  border-right: none;
  border-top: none;
  border-bottom: none;
}

