.data-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: var(--space-8);
  min-height: 9.375rem;
}

/* Loading */
.data-state--loading {
  gap: var(--space-4);
}

.loading-text {
  margin: 0;
  font-size: var(--text-sm);
  color: var(--text-color-secondary);
}

/* Error */
.error-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: var(--space-3);
  width: 100%;      /* Ocupa el ancho disponible en pantallas pequeñas */
  max-width: 25rem; /* Limita en pantallas grandes */
}

.error-icon {
  font-size: var(--text-3xl);
  color: var(--danger-color-text);
}

.error-title {
  margin: 0;
  font-size: var(--text-lg);
  font-weight: var(--font-weight-emphasis);
  color: var(--text-color);
}

.error-message {
  margin: 0;
  font-size: var(--text-sm);
  color: var(--text-color-secondary);
  line-height: 1.5;
}

app-button.retry-button {
  margin-top: var(--space-2);
}

/* Empty */
.empty-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-3);
}

.empty-icon {
  font-size: var(--text-4xl);
  color: var(--text-color-muted);
}

.empty-text {
  margin: 0;
  font-size: var(--text-sm);
  color: var(--text-color-secondary);
}

