        rows = valorAnidado['elementos'];
      } else if (valorAnidado && Array.isArray(valorAnidado['data'])) {
        rows = valorAnidado['data'];
      } else {
        const claveArreglo = Object.keys(envoltorio).find(clave => Array.isArray(envoltorio[clave]));
