      <h3>⚙️ Panel de Configuración</h3>

      <div class="setting-group">
        <label for="theme-select">Preferencia de Tema</label>
        <select id="theme-select" [value]="themeService.getSelectedTheme()"
          (change)="onThemeChange($event)">
          <option value="light">☀️ Claro</option>
          <option value="dark">🌙 Oscuro</option>
          <option value="system">💻 Sistema</option>
        </select>
      </div>

      <div class="setting-info">
        <p>Tema efectivo: <strong>{{ themeService.getEffectiveDarkMode() === 'dark' ? 'Oscuro' : 'Claro' }}</strong></p>
        <p>Almacenado en localStorage: <code>{{ themeService.getSelectedTheme() }}</code></p>
      </div>
    </div>
  `,
  styles: [`
    .settings-panel {
      background-color: var(--bg-secondary);
      color: var(--text-primary);
      padding: 20px;
      border: 1px solid var(--border-color);
      border-radius: 8px;
      max-width: 400px;
    }

    .setting-group {
      margin: 15px 0;
    }

    label {
      display: block;
      margin-bottom: 8px;
      font-weight: var(--font-weight-emphasis);
    }

    select {
      width: 100%;
      padding: 10px;
      border: 1px solid var(--border-color);
      border-radius: 6px;
      background-color: var(--bg-primary);
      color: var(--text-primary);
      font-size: 1rem;
      cursor: pointer;
    }

    select:hover {
      border-color: #2563eb;
    }

    .setting-info {
      margin-top: 15px;
      padding-top: 15px;
      border-top: 1px solid var(--border-color);
    }

    code {
      background-color: var(--bg-primary);
      padding: 2px 6px;
      border-radius: 4px;
      font-family: monospace;
    }
  `]
})
export class ExampleSettingsComponent {
  themeService = inject(ThemeService);

  onThemeChange(event: Event): void {
    const target = event.target as HTMLSelectElement;
    const value = target.value;
    if (value === 'light') {
      this.themeService.setLightTheme();
    } else if (value === 'dark') {
      this.themeService.setDarkTheme();
    } else {
      this.themeService.setSystemTheme();
    }
  }
}

