:host {
  display: block;
}

/* La zona de arrastre no tiene modo flotante (la etiqueta nombra un area, no un campo de texto);
   comparte la tipografia de etiqueta de todos los controles. */
.file-label {
  display: block;
  margin-bottom: var(--field-label-gap);
  color: var(--field-label-color);
  font-size: var(--field-label-font-size);
  font-weight: var(--field-label-font-weight);
  line-height: var(--field-label-line-height);
}

.drop-zone {
  border: var(--border-width-medium) dashed var(--border-color);
  border-radius: var(--radius-md);
  padding: var(--space-6) var(--space-5);
  text-align: center;
  cursor: pointer;
  transition:
    border-color var(--table-transition-duration),
    background var(--table-transition-duration),
    box-shadow var(--table-transition-duration);
  background: var(--surface-background);
  outline: none;
  user-select: none;
  --wails-draggable: no-drag;
}

.drop-zone > * {
  pointer-events: none;
}

.drop-zone:hover,
.drop-zone:focus-visible {
  border-color: var(--input-border-focus);
  background: var(--surface-hover);
}

.drag-over .drop-zone {
  border-color: var(--input-border-focus);
  background: var(--surface-hover);
}

.variant-dropzone .drop-zone {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-lg);
  background: var(--surface-section);
  padding: var(--space-6) var(--space-5);
}

.variant-dropzone .drop-zone:hover,
.variant-dropzone .drop-zone:focus-visible,
.variant-dropzone.drag-over .drop-zone {
  border-color: var(--primary-color);
  background: var(--primary-color-lighter);
}

.variant-dropzone.drag-over .drop-zone {
  box-shadow: var(--shadow-focus-primary);
}

.invalid .drop-zone,
.variant-dropzone.invalid .drop-zone {
  border-color: var(--danger-color);
}

.disabled .drop-zone {
  pointer-events: none;
  cursor: not-allowed;
  color: var(--input-disabled-text);
}

.drop-icon-container {
  width: var(--avatar-lg);
  height: var(--avatar-lg);
  border-radius: var(--radius-full);
  background: var(--primary-color-light);
  color: var(--primary-color);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-3);
  transition: transform var(--table-transition-duration);
}

.variant-dropzone .drop-zone:hover .drop-icon-container {
  transform: scale(1.06);
}

.variant-dropzone .drop-icon {
  font-size: var(--icon-md);
  color: var(--primary-color);
  margin: 0;
}

.drop-title {
  margin: 0 0 var(--space-1);
  font-size: var(--text-md);
  font-weight: var(--font-weight-title);
  color: var(--text-color);
}

.drop-subtitle {
  margin: 0 0 var(--space-2);
  font-size: var(--text-sm);
  color: var(--text-color-secondary);
}

.drop-badge-hint {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  margin-top: var(--space-2);
  padding: var(--space-1) var(--space-3);
  border-radius: var(--radius-full);
  border: var(--border-width-thin) solid var(--border-color);
  background: var(--surface-background);
  color: var(--text-color-secondary);
  font-size: var(--text-xs);
  font-weight: var(--font-weight-emphasis);
  box-shadow: var(--shadow-xs);
}

.drop-badge-icon {
  color: var(--text-color);
  font-size: var(--text-sm);
}

.compact .drop-zone {
  display: flex;
  flex-direction: row;
  min-height: var(--control-height);
  align-items: center;
  justify-content: flex-start;
  gap: var(--space-3);
  padding: var(--space-3) var(--space-4);
  text-align: left;
}

.compact:not(.variant-dropzone) .drop-icon {
  display: grid;
  flex: 0 0 auto;
  width: var(--space-10);
  height: var(--space-10);
  margin: 0;
  place-items: center;
  border-radius: var(--radius-md);
  background: var(--surface-section);
  font-size: var(--text-lg);
}

.compact.variant-dropzone .drop-icon-container {
  flex: 0 0 auto;
  width: var(--space-10);
  height: var(--space-10);
  margin: 0;
}

.compact .drop-text,
.compact .drop-title,
.compact .drop-subtitle,
.compact .drop-hint {
  margin: 0;
}

.drop-icon {
  font-size: var(--space-6);
  color: var(--text-color-muted);
  display: block;
  margin-bottom: var(--space-2);
}

.drop-copy {
  min-width: 0;
}

.drop-text {
  margin: var(--space-1) 0;
  font-size: var(--text-sm);
  color: var(--text-color-secondary);
}

.drop-hint {
  margin: var(--space-1) 0 0;
  font-size: var(--text-xs);
  color: var(--text-color-muted);
}

.file-hidden {
  display: none;
}

.file-hint {
  margin: 0 0 var(--space-2);
  font-size: var(--text-xs);
  color: var(--text-color-muted);
}

.file-error {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  margin: var(--space-2) 0 0;
  font-size: var(--text-sm);
  color: var(--danger-color-text);
}

.file-list-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-2);
  margin-top: var(--space-4);
  padding-bottom: var(--space-2);
  border-bottom: var(--border-width-thin) solid var(--border-color-light);
}

.file-list-heading {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-size: var(--text-sm);
  color: var(--text-color);
}

.file-list-folder-icon {
  color: var(--primary-color);
}

.file-list-title {
  font-weight: var(--font-weight-title);
}

.file-list-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: var(--space-5);
  height: var(--space-5);
  padding: 0 var(--space-2);
  border-radius: var(--radius-full);
  background: var(--primary-color);
  color: var(--text-color-on-primary);
  font-size: var(--text-xs);
  font-weight: var(--font-weight-emphasis);
}

.file-clear-all {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  padding: var(--space-1) var(--space-3);
  border-radius: var(--radius-sm);
  border: var(--border-width-thin) solid var(--danger-color-light);
  background: var(--danger-color-lighter);
  color: var(--danger-color-text);
  font-size: var(--text-xs);
  font-weight: var(--font-weight-emphasis);
  cursor: pointer;
  transition:
    background var(--table-transition-duration),
    color var(--table-transition-duration),
    border-color var(--table-transition-duration);
}

.file-clear-all:hover {
  background: var(--danger-color);
  border-color: var(--danger-color);
  color: var(--text-color-on-primary);
}

.file-list-scroll {
  display: block;
  width: 100%;
  margin-top: var(--space-3);
}

.file-list {
  list-style: none;
  margin: 0;
  padding: 0 var(--space-2) 0 0;
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.file-item {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  padding: var(--space-2) var(--space-3);
  background: var(--surface-section);
  border-radius: var(--radius-sm);
  border: var(--border-width-thin) solid var(--border-color);
}

.variant-dropzone .file-item {
  border: var(--border-width-thin) solid var(--border-color-light);
  border-left: var(--border-width-thick) solid var(--primary-color);
  background: var(--surface-background);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-xs);
  transition:
    box-shadow var(--table-transition-duration),
    border-color var(--table-transition-duration);
}

.variant-dropzone .file-item:hover {
  box-shadow: var(--shadow-sm);
  border-color: var(--border-color);
  border-left-color: var(--primary-color);
}

.file-preview {
  width: var(--space-6);
  height: var(--space-6);
  object-fit: cover;
  border-radius: var(--radius-sm);
  flex-shrink: 0;
}

.file-icon-box {
  width: var(--avatar-sm);
  height: var(--avatar-sm);
  border-radius: var(--radius-sm);
  background: var(--danger-color-lighter);
  color: var(--danger-color-text);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.file-icon {
  color: var(--text-color-muted);
  flex-shrink: 0;
}

.variant-dropzone .file-icon-box .file-icon {
  color: var(--danger-color-text);
}

.file-details {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  flex: 1;
  min-width: 0;
}

.variant-dropzone .file-details {
  flex-direction: column;
  align-items: flex-start;
  gap: var(--space-1);
}

.file-name {
  flex: 1;
  font-size: var(--text-sm);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 100%;
}

.variant-dropzone .file-name {
  font-weight: var(--font-weight-emphasis);
  color: var(--text-color);
}

.file-size {
  font-size: var(--text-xs);
  color: var(--text-color-muted);
  white-space: nowrap;
}

.file-actions {
  display: flex;
  align-items: center;
  gap: var(--space-1);
  flex-shrink: 0;
}

.file-action,
.file-remove {
  background: none;
  border: none;
  cursor: pointer;
  padding: var(--space-1) var(--space-2);
  color: var(--text-color-muted);
  border-radius: var(--radius-sm);
  transition:
    color var(--table-transition-duration),
    background var(--table-transition-duration);
  flex-shrink: 0;
}

.file-action:hover {
  color: var(--primary-color);
  background: var(--surface-hover);
}

.file-remove:hover {
  color: var(--danger-color-text);
  background: var(--surface-hover);
}

.variant-dropzone .file-remove {
  background: var(--danger-color-lighter);
  border: var(--border-width-thin) solid var(--danger-color-light);
  color: var(--danger-color-text);
}

.variant-dropzone .file-remove:hover {
  background: var(--danger-color);
  border-color: var(--danger-color);
  color: var(--text-color-on-primary);
}

