}

/* El botón no crece: tamaño fijo */
.filter-actions {
  flex: 0 0 auto;
  display: flex;
  gap: var(--space-2);
  align-items: center;
}

/* Móvil: stack vertical completo */
@media (max-width: 40rem) {
  .filter-bar > ::ng-deep * {
    flex: 1 1 100%;
  }
  .filter-actions {
    width: 100%;
  }
}

