  width: 100%;
  height: var(--space-1);
  background: var(--input-border);
}

.textarea-line::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 50%;
  width: 0;
  height: var(--space-1);
  background: var(--info-color);
  transition: all 300ms cubic-bezier(0.4, 0, 0.2, 1);
  transform: translateX(-50%);
}

.focused .textarea-line::after {
  width: 100%;
}

/* === VARIANT: FLOATING === */
.variant-floating .floating-textarea {
  border: var(--input-border-width, 1.5px) solid var(--input-border);
  border-radius: var(--radius-md);
  background: var(--input-bg);
  font-size: 0.875rem;
  box-shadow: var(--input-shadow);
}

.variant-floating .floating-label {
  left: var(--field-label-inset);
  background: var(--input-bg);
  padding: var(--field-label-padding);
  border-radius: var(--radius-sm);
  white-space: nowrap;
}

.variant-floating.focused .floating-label,
.variant-floating.has-value .floating-label {
  top: 0;
  transform: translateY(-50%);
}

.variant-floating .floating-textarea,
.variant-outline .floating-textarea {
  padding-top: var(--space-4);
}

.variant-floating.focused .floating-textarea {
  border-color: var(--input-border-focus);
  box-shadow: var(--input-shadow-focus);
}

.variant-floating .textarea-line {
  display: none;
}

/* === VARIANT: UNDERLINE === */
.variant-underline .floating-textarea {
  padding: var(--space-5) var(--space-4) 0.875rem;
  font-size: 0.875rem;
  border-bottom: 1px solid var(--input-border);
}

.variant-underline.has-icon .floating-textarea {
  padding-right: var(--space-8);
}

.variant-underline .floating-label {
  left: var(--field-label-inset);
  padding: var(--field-label-padding);
}

.variant-underline.focused .floating-label,
.variant-underline.has-value .floating-label {
  top: var(--space-1);
}

.variant-underline.focused .floating-textarea,
.variant-underline.has-value .floating-textarea {
  border-bottom-color: transparent;
}

.variant-underline .textarea-line {
  height: var(--space-1);
}

/* === VARIANT: MATERIAL === */
.variant-material .floating-textarea {
  padding: var(--space-5) var(--space-4) 0.875rem;
  font-size: 0.875rem;
}

.variant-material.has-icon .floating-textarea {
  padding-right: var(--space-8);
}

.variant-material .floating-label {
  left: var(--field-label-inset);
  padding: var(--field-label-padding);
  font-size: var(--field-label-font-size);
}

.variant-material.focused .floating-label,
.variant-material.has-value .floating-label {
  top: var(--space-1);
}

/* === VARIANT: OUTLINE === */
.variant-outline .floating-textarea {
  font-size: 0.875rem;
  background: var(--input-bg);
  border: var(--input-border-width, 1.5px) solid var(--input-border);
  border-radius: var(--radius-md);
  box-shadow: var(--input-shadow);
}

.variant-outline .floating-label {
  top: calc(var(--control-height) / 2);
  background: var(--input-bg);
  padding: var(--field-label-padding);
  border-radius: var(--radius-sm);
  font-size: var(--field-label-font-size);
  white-space: nowrap;
}

.variant-outline.focused .floating-label,
.variant-outline.has-value .floating-label {
  top: 0;
  font-size: var(--field-label-floated-font-size);
  transform: translateY(-50%);
}

.variant-outline.focused .floating-textarea {
  border-color: var(--input-border-focus);
  box-shadow: var(--input-shadow-focus);
}

.variant-outline .textarea-line {
  display: none;
}

/* === HOVER STATE (floating + outline, antes del focus) === */
.variant-floating:not(.focused) .floating-textarea:hover,
.variant-outline:not(.focused) .floating-textarea:hover {
  border-color: var(--input-border-hover);
  box-shadow: var(--input-shadow-hover);
}

/* === ICONS === */
.textarea-icon-btn {
  position: absolute;
  right: var(--space-2);
  top: calc(var(--control-height, 2.5rem) / 2);
  transform: translateY(-50%);
  width: var(--space-7);
  height: var(--space-7);
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: none;
  border-radius: 50%;
  color: var(--text-color-secondary);
  cursor: pointer;
  transition: all 150ms ease;
}

.textarea-icon-btn:hover {
  background: var(--hover-background-subtle);
  color: var(--primary-color);
}

.textarea-icon-btn:focus-visible {
  outline: none;
  box-shadow: var(--shadow-focus-primary);
}

.textarea-icon-btn--static {
  width: 1.75rem;
  height: 1.75rem;
  right: var(--space-3);
  cursor: default;
}

.textarea-icon-btn--static.floating-textarea__icon--clickable {
  cursor: pointer;
}

/* === STATES === */
.disabled .floating-textarea {
  background: var(--input-disabled-bg);
  cursor: not-allowed;
  color: var(--input-disabled-text);
}

.disabled .floating-label,
.disabled.focused .floating-label,
.disabled.has-value .floating-label {
  color: var(--input-disabled-text);
}

.disabled.variant-floating .floating-label,
.disabled.variant-outline .floating-label {
  background: var(--input-disabled-bg);
}

.has-error .floating-textarea {
  border-color: var(--danger-color) !important;
}

.has-error .floating-label {
  color: var(--danger-color-text) !important;
}

.has-error .textarea-line::after {
  background: var(--danger-color);
}

.textarea-error {
  display: block;
  margin-top: var(--space-2);
  font-size: 0.8125rem;
  color: var(--danger-color-text);
}

/* === VARIANT: STANDARD (etiqueta superior fija) === */
.floating-textarea-top-label {
  margin-bottom: var(--field-label-gap);
}

.variant-standard {
  margin-top: 0;
}

.variant-standard .floating-textarea {
  border: var(--input-border-width, 1.5px) solid var(--input-border);
  border-radius: var(--radius-md);
  background: var(--input-bg);
  box-shadow: var(--input-shadow);
}

.variant-standard.focused .floating-textarea {
  border-color: var(--input-border-focus);
  box-shadow: var(--input-shadow-focus);
}

.variant-standard .textarea-line {
  display: none;
}

.variant-standard:not(.focused) .floating-textarea:hover {
  border-color: var(--input-border-hover);
  box-shadow: var(--input-shadow-hover);
}

/* === MOMENTO DE LA ETIQUETA: floating-value === */
.label-solo-valor.focused:not(.has-value) .floating-label {
  top: calc(var(--control-height) / 2);
  transform: translateY(-50%);
  font-size: var(--field-label-font-size);
  font-weight: var(--field-label-font-weight);
  color: var(--field-label-color-resting);
}

/*
  Estilos compartidos de la etiqueta de campo (contrato `variant`: standard | floating | floating-value).

  Se incluyen en cada control con `styleUrls: ['./x.css', '../form-field/field-label.css']`, de modo
  que la tipografia, el color y la geometria de la etiqueta salen de UN solo lugar y de tokens
  `--field-label-*`: nada de rem literales ni `uppercase` en los controles.

  Geometria de la etiqueta flotante
  ---------------------------------
  `.fl-control` es la CAJA del control y solo contiene el control. La ayuda y el error viven FUERA
  de ella. Si la etiqueta se anclara al contenedor que tambien lleva la ayuda, `top: 50%` caeria
  en el centro de caja + ayuda y la etiqueta quedaria desplazada hacia abajo cuando hay mensaje.

  - Reposo:  centrada en la mitad de `--control-height` (primera linea en controles multilinea).
  - Elevada: centrada sobre el borde superior (`top: 0` + `translateY(-50%)`), con el fondo del
             campo recortando el borde. Como el centrado es relativo al propio texto, no depende
             del tamano de fuente.
*/

.fl-field {
  display: grid;
  min-width: 0;
  gap: var(--field-label-gap);
}

/* Reserva el espacio que ocupa la etiqueta elevada sobre el borde superior del control. */
.fl-field--floating {
  margin-top: var(--space-3);
}

/* El mensaje de error lo dibuja app-form-error: la rejilla ya separa, asi que no suma su propio margen. */
.fl-field > app-form-error {
  --form-error-gap: 0;
}

.fl-control {
  position: relative;
  min-width: 0;
}

/* Etiqueta superior (variant="standard"). */
.fl-label {
  display: block;
  color: var(--field-label-color);
  font-size: var(--field-label-font-size);
  font-weight: var(--field-label-font-weight);
  line-height: var(--field-label-line-height);
}

.field__required,
.fl-label__required {
  color: var(--field-label-color-error);
}

/* Etiqueta flotante (variant="floating" | "floating-value"): reposo. */
.fl-label--floating {
  position: absolute;
  top: calc(var(--control-height) / 2);
  left: var(--field-label-inset);
  z-index: 1;
  max-width: calc(100% - var(--field-label-inset) - var(--space-1));
  overflow: hidden;
  padding: var(--field-label-padding);
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--field-label-color-resting);
  font-size: var(--field-label-font-size);
  font-weight: var(--field-label-font-weight);
  line-height: var(--field-label-line-height);
  text-overflow: ellipsis;
  white-space: nowrap;
  pointer-events: none;
  transform: translateY(-50%);
  transition:
    top var(--field-label-duration) ease,
    color var(--field-label-duration) ease,
    font-size var(--field-label-duration) ease;
}

/* Etiqueta flotante: elevada sobre el borde superior. */
.fl-label--floating.fl-label--floated {
  top: 0;
  background: var(--input-bg);
  color: var(--field-label-color-floated);
  font-size: var(--field-label-floated-font-size);
  font-weight: var(--field-label-floated-font-weight);
}

.fl-label.fl-label--disabled,
.fl-label--floating.fl-label--disabled {
  color: var(--input-disabled-text);
}

.fl-label--floating.fl-label--floated.fl-label--disabled {
  background: var(--input-disabled-bg);
}

.fl-label.fl-label--error,
.fl-label--floating.fl-label--error,
.fl-label--floating.fl-label--floated.fl-label--error {
  color: var(--field-label-color-error);
}

@media (prefers-reduced-motion: reduce) {
  .fl-label--floating {
    transition: none;
  }
}

