:host {
  display: block;
  width: 100%;
  min-width: 0;
  max-width: 100%;
}

.kpi-card {
  --kpi-accent: var(--text-color-secondary);
  --kpi-accent-background: var(--surface-section);
  width: 100%;
  min-width: 0;
  min-height: 6.5rem;
  display: grid;
  box-sizing: border-box;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-4);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  background: var(--surface-background);
  box-shadow: var(--shadow-sm);
}

.kpi-card--brand {
  --kpi-accent: var(--primary-color);
  --kpi-accent-background: var(--primary-color-lighter);
}

.kpi-card--info {
  --kpi-accent: var(--info-color-text);
  --kpi-accent-background: var(--info-color-lighter);
}

.kpi-card--success {
  --kpi-accent: var(--success-color-text);
  --kpi-accent-background: var(--success-color-lighter);
}

.kpi-card--warning {
  --kpi-accent: var(--warning-color-text);
  --kpi-accent-background: var(--warning-color-lighter);
}

.kpi-card--danger {
  --kpi-accent: var(--danger-color-text);
  --kpi-accent-background: var(--danger-color-lighter);
}

.kpi-card__header {
  min-width: 0;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--space-3);
}

.kpi-card__heading,
.kpi-card__content {
  min-width: 0;
}

.kpi-card__heading {
  flex: 1;
}

.kpi-card__title {
  margin: 0;
  color: var(--text-color-secondary);
  font-family: var(--font-family-heading);
  font-size: var(--text-xs);
  font-weight: var(--font-weight-title);
  letter-spacing: 0.04em;
  overflow-wrap: anywhere;
  text-transform: uppercase;
}

.kpi-card__subtitle {
  margin: var(--space-1) 0 0;
  color: var(--text-color-muted);
  font-size: var(--text-xs);
  line-height: 1.4;
  overflow-wrap: anywhere;
}

.kpi-card__icon {
  width: 2rem;
  height: 2rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  border: 1px solid color-mix(in srgb, var(--kpi-accent) 28%, transparent);
  border-radius: var(--radius-md);
  background: var(--kpi-accent-background);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--surface-background) 42%, transparent);
  color: var(--kpi-accent);
}

.kpi-card__value {
  margin: 0;
  color: var(--text-color);
  font-family: var(--font-family-heading);
  font-size: 1.35rem;
  font-variant-numeric: tabular-nums;
  font-weight: var(--font-weight-title);
  letter-spacing: -0.02em;
  line-height: 1.2;
  overflow-wrap: anywhere;
}

.kpi-card__meta {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--space-2);
  margin-top: var(--space-2);
}

.kpi-card__trend {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-1) var(--space-2);
  border: 1px solid transparent;
  border-radius: var(--radius-full);
  font-size: var(--text-xs);
