:host {
  display: block;
  width: 100%;
  height: 100%;
}

/* CSS Grid Layout */
.layout-shell {
  display: grid;
  height: 100vh;
  height: 100dvh;
  --sidebar-width: 16.25rem;
  grid-template-columns: var(--sidebar-width) minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr) auto;
  grid-template-areas:
    'sidebar header'
    'sidebar content'
    'sidebar footer';
  background-color: var(--surface-section);
  color: var(--text-color);
}

.layout-sidebar {
  grid-area: sidebar;
  background-color: var(--sidebar-bg);
  border-right: 1px solid var(--border-color);
  overflow: hidden;
  z-index: 30;
  width: var(--sidebar-width);
  min-width: var(--sidebar-width);
}

.layout-header {
  grid-area: header;
  position: sticky;
  top: 0;
  z-index: 30;
  padding: 0;
  display: flex;
  align-items: center;
  height: var(--topbar-height, 4rem);
  min-width: 0;
}

.layout-content {
  grid-area: content;
  overflow: hidden;
  padding: 0;
  display: flex;
  flex-direction: column;
}

.layout-footer {
  grid-area: footer;
  min-width: 0;
}

.layout-content ::ng-deep app-scroll-overlay {
  flex: 1;
  height: 100%;
  width: 100%;
}

.content-wrapper {
  width: 100%;
  padding: var(--space-5) 2.25rem;
  box-sizing: border-box;
}

.layout-overlay {
  display: none;
}

/* RESPONSIVE MOBILE/TABLET (matches max-width: 64rem of Prestamos) */
@media (max-width: 64rem) {
  .layout-shell {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: var(--topbar-height, 4rem) minmax(0, 1fr) auto;
    grid-template-areas:
      'header'
      'content'
      'footer';
  }

  .content-wrapper {
    padding: var(--space-5) 2.25rem;
  }

  .layout-sidebar {
    position: fixed;
    inset-block: 0;
    left: 0;
    bottom: 0;
    top: 0;
    width: min(var(--sidebar-width), calc(100vw - 3rem));
    transform: translateX(-102%);
    transition: transform 180ms ease;
    z-index: 50;
  }

  /* When sidebar is visible on mobile */
  .layout-shell.sidebar-visible .layout-sidebar {
    transform: translateX(0);
  }

  .layout-overlay {
    display: block;
    position: fixed;
    inset: 0;
