  grid-column: 3;
  justify-self: end;
}

.modal-body-scroll {
  flex: 1;
  min-height: 0;
}

.modal-body {
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
  padding: var(--space-4) var(--space-5);
}

.modal-footer {
  display: flex;
  justify-content: flex-end;
  gap: var(--space-3);
  padding: var(--space-4) var(--space-5);
  background: var(--modal-footer-bg, var(--surface-section));
  border-top: 1px solid var(--modal-border, var(--border-color));
}

@media (prefers-reduced-motion: reduce) {
  .modal-overlay,
  .modal {
    animation: none;
  }
}

/* Dark mode se maneja automáticamente via tokens semánticos.
 * --surface-background, --overlay-backdrop, --surface-hover
 * ya tienen valores apropiados para temas oscuros.
 */

