import { Component, ChangeDetectionStrategy, inject, ElementRef, effect, viewChildren } from '@angular/core';

import { ModalService, ModalItem } from '../../services/modal.service';

/**
 * Contenedor de modales global.
 * Debe colocarse en el nivel raíz del app (app.component o app.html).
 * Lee los modales del ModalService y los renderiza.
 * 
 * @example
 * ```html
 * <!-- En app.html o app.component -->
 * <app-modal-container></app-modal-container>
 * ```
 */
import { ButtonComponent } from '../../atoms/button/button.component';
import { IconButtonComponent } from '../../atoms/icon-button/icon-button.component';
import { ScrollOverlayComponent } from '../../organisms/scroll-overlay/scroll-overlay.component';

@Component({
  selector: 'app-modal-container',
  standalone: true,
  imports: [ButtonComponent, IconButtonComponent, ScrollOverlayComponent],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    @for (modal of modalService.modals(); track modal.id; let first = $first) {
      <div 
        class="modal-overlay" 
        [class.modal-closing]="modal.closing"
        (click)="onBackdropClick(modal)"
        (keydown.escape)="onEscape(modal)"
        tabindex="-1"
      >
        <div 
          #modalElement
          class="modal" 
          [class]="'modal-' + modal.size"
          [class.modal-exit]="modal.closing"
          (click)="$event.stopPropagation()"
          (keydown)="onModalKeydown($event, modal)"
          role="dialog"
          aria-modal="true"
          [attr.aria-labelledby]="'modal-title-' + modal.id"
          tabindex="-1"
        >
          <!-- Header -->
          <div class="modal-header">
            <h3 class="modal-title" [id]="'modal-title-' + modal.id">{{ modal.title }}</h3>
            @if (modal.closable) {
              <app-icon-button class="modal-close" (clicked)="modalService.close(modal.id)" ariaLabel="Cerrar" variant="close" animation="none">
              </app-icon-button>
            }
          </div>

          <!-- Body -->
          <app-scroll-overlay
            class="so-block modal-body-scroll"
            [skipTableDetection]="true"
            [disableHorizontal]="true"
          >
            <div class="modal-body">
              @if (modal.message) {
                <p class="modal-message">{{ modal.message }}</p>
              }
              @if (modal.htmlContent) {
                <div [innerHTML]="modal.htmlContent"></div>
              }
            </div>
          </app-scroll-overlay>

          <!-- Footer -->
          @if (modal.hasFooter && modal.buttons && modal.buttons.length > 0) {
            <div class="modal-footer">
              @for (button of modal.buttons; track button.label) {
                <app-button 
                  class="modal-btn"
                  [variant]="button.variant || 'primary'"
                  (buttonClick)="button.action()"
                >
                  {{ button.label }}
                </app-button>
              }
            </div>
          }
        </div>
      </div>
    }
  `,
  styleUrl: './modal-container.component.css'
})
export class ModalContainerComponent {
  protected readonly modalService = inject(ModalService);

  readonly modalElements = viewChildren<ElementRef<HTMLElement>>('modalElement');

  constructor() {
    // Effect to focus the newest modal when the list changes
    effect(() => {
      const modalList = this.modalService.modals();
      if (modalList.length > 0) {
        // Wait for next tick to ensure DOM is updated
        setTimeout(() => {
          const elements = this.modalElements();
          const newestModal = elements[elements.length - 1];
          if (newestModal) {
            // Find first focusable element (close button or first action button)
            const focusable = newestModal.nativeElement.querySelector(
              'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
            ) as HTMLElement;

            if (focusable) {
              focusable.focus({ preventScroll: true });
            } else {
              newestModal.nativeElement.focus({ preventScroll: true });
            }
          }
        }, 0);
      }
    });
  }

  onBackdropClick(modal: ModalItem): void {
    if (modal.closeOnBackdrop) {
      this.modalService.close(modal.id);
    }
  }

  onEscape(modal: ModalItem): void {
    if (modal.closable) {
      this.modalService.close(modal.id);
    }
  }

  onModalKeydown(event: KeyboardEvent, modal: ModalItem): void {
    event.stopPropagation();
    if (event.key === 'Escape') {
      this.onEscape(modal);
    }
  }
}

