import {
  AfterViewInit,
  Component,
  ElementRef,
  forwardRef,
  ChangeDetectionStrategy,
  signal,
  computed,
  input,
  output,
  viewChild
} from '@angular/core';

import { ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';
import {
  FIELD_LABEL_VARIANT_DEFAULT,
  FieldLabelVariant,
  esEtiquetaFlotante,
} from '../form-field/field-label';

/**
 * NumberInputComponent — Input numérico con botones de incremento/decremento.
 * Compatible con `ngModel` y `FormControl`.
 *
 * @example
 * ```html
 * <app-number-input [(ngModel)]="quantity" [min]="1" [max]="99" label="Cantidad"></app-number-input>
 * ```
 */
@Component({
  selector: 'app-number-input',
  standalone: true,
  imports: [],
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => NumberInputComponent),
      multi: true,
    },
  ],
  templateUrl: './number-input.component.html',
  styleUrls: ['./number-input.component.css', '../form-field/field-label.css'],
})
export class NumberInputComponent implements ControlValueAccessor, AfterViewInit {
  private static nextId = 0;

  readonly label = input('');
  /**
   * Modo de etiqueta comun: standard | floating | floating-value.
   * Un campo numerico siempre contiene un valor, de modo que en los modos flotantes la etiqueta
   * permanece elevada sobre el borde y no hay etiqueta en reposo ni marcador que superponer.
   */
  readonly variant = input<FieldLabelVariant>(FIELD_LABEL_VARIANT_DEFAULT);
  /** Oculta la etiqueta visualmente y la conserva como nombre accesible (p. ej. filas repetidas). */
  readonly labelHidden = input(false);
  readonly hint = input('');
  readonly error = input('');
  readonly required = input(false);
  readonly min = input(0);
  readonly max = input(9999);
  readonly step = input(1);
  readonly disabled = input(false);
  private readonly disabledByForm = signal(false);
  readonly inputId = input(`number-input-${++NumberInputComponent.nextId}`);

  isDisabled(): boolean {
    return this.disabled() || this.disabledByForm();
  }

  readonly valueChange = output<number>();

  protected value = signal<number>(0);
  protected readonly flotante = computed(() =>
    esEtiquetaFlotante(this.variant(), this.label().length > 0),
  );
  /** Lo que se ajusto de lo tecleado, para poder decirlo. */
  protected readonly adjustment = signal<string | null>(null);

  private readonly consultaNativeInput = viewChild<ElementRef<HTMLInputElement>>('nativeInput');
  private get nativeInput(): ElementRef<HTMLInputElement> | undefined {
    return this.consultaNativeInput();
  }

  private onChange: (value: number) => void = () => {};
  protected onTouched: () => void = () => {};

  protected get describedBy(): string | null {
    const ids = [this.hint() ? `${this.inputId()}-hint` : '', this.error() ? `${this.inputId()}-error` : ''].filter(Boolean);
    return ids.length > 0 ? ids.join(' ') : null;
  }

  ngAfterViewInit(): void {
    this.syncNative();
  }

  writeValue(value: number): void {
    this.value.set(value ?? 0);
    this.adjustment.set(null);
    /*
    RECHAZAR UNA ENTRADA TAMBIEN TIENE QUE RETIRARLA DEL CAMPO.

    `[value]` solo reescribe el `<input>` cuando el numero CAMBIA. Si el padre
    repone el mismo valor que ya tenia —que es exactamente lo que hace un
    rechazo— el binding no toca el DOM y el campo se queda con lo que tecleo la
    persona. A partir de ahi, lo que se ve y lo que se cuenta son dos cifras
    distintas y nada lo delata.
    */
    this.syncNative();
  }

  registerOnChange(fn: (value: number) => void): void {
    this.onChange = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this.disabledByForm.set(isDisabled);
  }

  increment(): void {
    const next = Math.min(this.value() + this.step(), this.max());
    this.adjustment.set(null);
    this.setValue(next);
    this.onTouched();
  }

  decrement(): void {
    const next = Math.max(this.value() - this.step(), this.min());
    this.adjustment.set(null);
    this.setValue(next);
    this.onTouched();
  }

  onInput(event: Event): void {
    const element = event.target as HTMLInputElement;
    const raw = element.value;

    if (raw.trim() === '') {
      /*
      UN CAMPO `type=number` MIENTE CUANDO LO TECLEADO NO ES UN NUMERO.

      Si se escribe `1o0`, el navegador ENSEÑA `1o0` y a la vez nos entrega
      cadena vacia; solo `validity.badInput` distingue eso de un campo borrado.
      Antes esto caia en `isNaN` y se ignoraba sin mas: el modelo conservaba la
      cantidad anterior mientras la fila seguia mostrando `1o0`. En un arqueo de
      caja, esa fila cuenta una cosa y enseña otra.

      Se limpia el estado invalido —solo asi el navegador suelta el texto— y se
      repone la cantidad contada.
      */
      if (element.validity?.badInput) {
        this.adjustment.set('Solo se admiten números: se repuso la cantidad contada.');
        element.value = '';
        this.syncNative();
        return;
      }

      // Vacio de verdad: se interpreta como cero, pero conserva el contrato
      // declarado por min/max igual que cualquier otro valor tecleado.
      const bounded = this.boundToRange(0);
      this.adjustment.set(
        bounded === 0
          ? null
          : `Se ajustó a ${bounded} (permitido de ${this.min()} a ${this.max()}).`,
      );
      this.setValue(bounded);
      return;
    }

    const parsed = parseFloat(raw);
    if (isNaN(parsed)) {
      this.adjustment.set('Solo se admiten números: se repuso la cantidad contada.');
      this.syncNative();
      return;
    }

    const bounded = this.boundToRange(parsed);
    this.adjustment.set(
      bounded === parsed
        ? null
        : `Se ajustó a ${bounded} (permitido de ${this.min()} a ${this.max()}).`,
    );
    this.setValue(bounded);
  }

  private setValue(val: number, options: { readonly sync?: boolean } = {}): void {
    this.value.set(val);
    this.onChange(val);
    this.valueChange.emit(val);
    if (options.sync !== false) {
      // Aunque el numero no haya cambiado: es justo el caso en que el binding
      // no reescribe y el campo se queda con lo tecleado.
      this.syncNative();
    }
  }

  private boundToRange(value: number): number {
    return Math.min(Math.max(value, this.min()), this.max());
  }

  private syncNative(): void {
    const element = this.nativeInput?.nativeElement;
    if (!element) {
      return;
    }
    const expected = String(this.value());
    if (element.value !== expected) {
      element.value = expected;
    }
  }
}

styleUrlsData.data:
:host { display: block; }

/* La tipografia de la etiqueta (superior y flotante) vive en ../form-field/field-label.css */
.number-input__label--hidden {
  /* gate-etiqueta-exento: texto solo para tecnologia de apoyo (visualmente oculto), no es una etiqueta visible. */
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.number-input__control {
  display: flex;
  align-items: center;
  gap: var(--space-1);
  width: 100%;
  height: var(--control-height);
  min-height: var(--control-height);
  padding: var(--space-1) var(--space-2);
  box-sizing: border-box;
  border: 1px solid var(--input-border);
  border-radius: var(--radius-md);
  background: var(--input-bg);
  box-shadow: var(--input-shadow);
  transition:
    border-color 150ms ease,
    box-shadow 150ms ease;
}

.number-input-wrapper:not(.number-input--disabled) .number-input__control:hover {
  border-color: var(--input-border-hover);
  box-shadow: var(--input-shadow-hover);
}

.number-input__control:focus-within {
  border-color: var(--input-border-focus);
  box-shadow: var(--input-shadow-focus);
}

.number-input--error .number-input__control {
  border-color: var(--danger-color);
}

.number-input__btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--control-height-xs);
  height: var(--control-height-xs);
  flex-shrink: 0;
  background: var(--surface-section);
  border: none;
  border-radius: var(--radius-sm);
  cursor: pointer;
  color: var(--text-color-secondary);
  transition: background 150ms ease, color 150ms ease;
  font-size: var(--text-sm);
}
.number-input__btn:hover:not(:disabled) {
  background: var(--primary-color);
  color: var(--text-color-on-primary);
}
.number-input__btn:focus-visible {
  outline: 2px solid var(--primary-color);
  outline-offset: -2px;
  box-shadow: none;
}
.number-input__btn:disabled {
  cursor: not-allowed;
  color: var(--input-disabled-text);
}

.number-input__field {
  flex: 1;
  min-width: var(--space-8);
  border: none;
  background: transparent;
  text-align: center;
  font-family: inherit;
  font-size: var(--text-md);
  font-weight: var(--font-weight-body);
  line-height: var(--field-label-line-height);
  color: var(--text-color);
  padding: 0 var(--space-2);
  outline: none;
  box-shadow: none;
  -moz-appearance: textfield;
}
.number-input__field:focus,
.number-input__field:focus-visible {
  outline: none;
  box-shadow: none;
}
.number-input__field::-webkit-inner-spin-button,
.number-input__field::-webkit-outer-spin-button { -webkit-appearance: none; }

.number-input--disabled .number-input__control {
  pointer-events: none;
  background: var(--input-disabled-bg);
  color: var(--input-disabled-text);
  box-shadow: none;
}

.number-input--disabled .number-input__field {
  color: var(--input-disabled-text);
}

.number-input__hint {
  display: block;
  font-size: var(--text-xs);
  color: var(--text-color-muted);
}

.number-input__adjustment {
  display: block;
  font-size: var(--text-xs);
  color: var(--warning-color-text);
}

.number-input__error {
  display: block;
  font-size: var(--text-xs);
  color: var(--danger-color-text);
}

/*
  Estilos compartidos de la etiqueta de campo (contrato `variant`: standard | floating | floating-value).

  Se incluyen en cada control con `styleUrls: ['./x.css', '../form-field/field-label.css']`, de modo
  que la tipografia, el color y la geometria de la etiqueta salen de UN solo lugar y de tokens
  `--field-label-*`: nada de rem literales ni `uppercase` en los controles.

  Geometria de la etiqueta flotante
  ---------------------------------
  `.fl-control` es la CAJA del control y solo contiene el control. La ayuda y el error viven FUERA
  de ella. Si la etiqueta se anclara al contenedor que tambien lleva la ayuda, `top: 50%` caeria
  en el centro de caja + ayuda y la etiqueta quedaria desplazada hacia abajo cuando hay mensaje.

  - Reposo:  centrada en la mitad de `--control-height` (primera linea en controles multilinea).
  - Elevada: centrada sobre el borde superior (`top: 0` + `translateY(-50%)`), con el fondo del
             campo recortando el borde. Como el centrado es relativo al propio texto, no depende
             del tamano de fuente.
*/

.fl-field {
  display: grid;
  min-width: 0;
  gap: var(--field-label-gap);
}

/* Reserva el espacio que ocupa la etiqueta elevada sobre el borde superior del control. */
.fl-field--floating {
  margin-top: var(--space-3);
}

/* El mensaje de error lo dibuja app-form-error: la rejilla ya separa, asi que no suma su propio margen. */
.fl-field > app-form-error {
  --form-error-gap: 0;
}

.fl-control {
  position: relative;
  min-width: 0;
}

/* Etiqueta superior (variant="standard"). */
.fl-label {
  display: block;
  color: var(--field-label-color);
  font-size: var(--field-label-font-size);
  font-weight: var(--field-label-font-weight);
  line-height: var(--field-label-line-height);
}

.field__required,
.fl-label__required {
  color: var(--field-label-color-error);
}

/* Etiqueta flotante (variant="floating" | "floating-value"): reposo. */
.fl-label--floating {
  position: absolute;
  top: calc(var(--control-height) / 2);
  left: var(--field-label-inset);
  z-index: 1;
  max-width: calc(100% - var(--field-label-inset) - var(--space-1));
  overflow: hidden;
  padding: var(--field-label-padding);
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--field-label-color-resting);
  font-size: var(--field-label-font-size);
  font-weight: var(--field-label-font-weight);
  line-height: var(--field-label-line-height);
  text-overflow: ellipsis;
  white-space: nowrap;
  pointer-events: none;
  transform: translateY(-50%);
  transition:
    top var(--field-label-duration) ease,
    color var(--field-label-duration) ease,
    font-size var(--field-label-duration) ease;
}

/* Etiqueta flotante: elevada sobre el borde superior. */
.fl-label--floating.fl-label--floated {
  top: 0;
  background: var(--input-bg);
  color: var(--field-label-color-floated);
  font-size: var(--field-label-floated-font-size);
  font-weight: var(--field-label-floated-font-weight);
}

.fl-label.fl-label--disabled,
.fl-label--floating.fl-label--disabled {
  color: var(--input-disabled-text);
}

.fl-label--floating.fl-label--floated.fl-label--disabled {
  background: var(--input-disabled-bg);
}

.fl-label.fl-label--error,
.fl-label--floating.fl-label--error,
.fl-label--floating.fl-label--floated.fl-label--error {
  color: var(--field-label-color-error);
}

@media (prefers-reduced-motion: reduce) {
  .fl-label--floating {
    transition: none;
  }
}

