import { ChangeDetectionStrategy, Component, input } from '@angular/core';

export type PageHeaderDensity = 'comfortable' | 'compact';
export type PageHeaderAlignment = 'start' | 'center';

/**
 * Encabezado canónico de página. Mantiene la jerarquía de título, contexto y
 * acciones sin conocer rutas, permisos ni reglas de negocio del consumidor.
 */
@Component({
  selector: 'app-page-header, prest-page-header',
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './page-header.html',
  styleUrl: './page-header.scss',
})
export class PageHeader {
  private static nextId = 0;
  private readonly generatedHeadingId = `prest-page-header-${++PageHeader.nextId}`;

  readonly title = input.required<string>();
  readonly subtitle = input<string | null>(null);
  readonly eyebrow = input<string | null>(null);
  readonly density = input<PageHeaderDensity>('comfortable');
  readonly align = input<PageHeaderAlignment>('center');
  readonly headingId = input(this.generatedHeadingId);
  readonly actionsLabel = input('Acciones de la página');
}

styleUrlsData.data:
:host {
  display: block;
  min-width: 0;
  margin-block-end: var(--space-5);
}

.page-header {
  display: flex;
  min-width: 0;
  align-items: flex-end;
  justify-content: space-between;
  gap: var(--space-4);
}

.page-header--compact {
  gap: var(--space-3);
}

.page-header--align-center {
  display: grid;
  grid-template-columns: 1fr minmax(0, auto) 1fr;
  align-items: center;
}

.page-header--align-center .page-header__content {
  grid-column: 2;
  text-align: center;
}

.page-header--align-center .page-header__subtitle {
  margin-inline: auto;
}

.page-header--align-center .page-header__actions {
  grid-column: 3;
  justify-self: end;
}

.page-header--align-center:has(.page-header__actions:empty) {
  grid-template-columns: minmax(0, 1fr);
}

.page-header--align-center:has(.page-header__actions:empty) .page-header__content {
  grid-column: 1;
}

.page-header__content {
  min-width: 0;
}

.page-header__eyebrow,
.page-header__title,
.page-header__subtitle {
  margin: 0;
}

.page-header__eyebrow {
  margin-block-end: var(--space-1);
  color: var(--primary-color);
  font-size: var(--text-xs);
  font-weight: var(--font-weight-display);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.page-header__title {
  color: var(--text-color);
  font-family: var(--font-family-heading);
  font-size: clamp(var(--text-2xl), 3vw, var(--text-3xl));
  line-height: 1.2;
}

.page-header--compact .page-header__title {
  font-size: var(--text-2xl);
}

.page-header__subtitle {
  max-width: 68ch;
  margin-block-start: var(--space-2);
  color: var(--text-color-secondary);
  font-size: var(--text-sm);
  line-height: 1.5;
}

.page-header__actions {
  display: flex;
  flex: 0 0 auto;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: var(--space-2);
}

.page-header__actions:empty {
  display: none;
}

@media (max-width: 48rem) {
  .page-header--align-center {
    grid-template-columns: minmax(0, 1fr);
  }

  .page-header--align-center .page-header__content {
    grid-column: 1;
  }

  .page-header--align-center .page-header__actions {
    grid-column: 1;
    justify-self: center;
  }
}

@media (max-width: 40rem) {
  .page-header {
    align-items: stretch;
    flex-direction: column;
  }

  .page-header--align-start .page-header__actions {
    justify-content: flex-start;
  }
}

