/**
 * Estilos del Chasis A — PaginaCrud.
 *
 * Doctrina §10: todo espacio sale de --space-N.
 * Doctrina §8:  los estados se comunican con tokens de contraste verificado.
 * Doctrina §16: no se usan valores sueltos; todo cierra con la escala.
 */

:host {
  display: block;
}

/* ─── Espaciado entre secciones ──────────────────────────── */
app-page-header {
  margin-block-end: var(--space-4);
}

app-query-toolbar {
  margin-block-end: var(--space-5);
}

/* ─── Diálogo CRUD ───────────────────────────────────────── */
.pagina-crud__dialogo-cabecera {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--space-4) var(--space-5);
  background-color: var(--modal-header-bg);
  border-block-end: var(--border-width-thin, 1px) solid var(--border-color);
}

.pagina-crud__dialogo-titulo {
  margin: 0;
  font-family: var(--font-family-heading);
  font-size: var(--text-lg);
  font-weight: var(--font-weight-title);
  text-transform: uppercase;
  text-align: center;
  width: 100%;
}


.pagina-crud__dialogo-error {
  padding-inline: calc(var(--space-6) + var(--space-1));
  padding-block-start: var(--space-5);
}

.pagina-crud__dialogo-cuerpo {
  padding: var(--space-4) var(--space-5);
}

.pagina-crud__dialogo-pie {
  display: flex;
  justify-content: flex-end;
  gap: var(--form-row-gap); /* Token existente: 2.25rem = 36 CSS px. */
  flex-wrap: wrap;
  padding: var(--space-4) var(--space-5);
  background-color: var(--modal-footer-bg);
  border-block-start: var(--border-width-thin, 1px) solid var(--border-color);
}

/* ─── Diálogo de confirmación de baja ────────────────────── */
.pagina-crud__confirmacion-mensaje {
  margin: 0;
  color: var(--text-color-secondary);
}

.pagina-crud__filtros-cascada {
  grid-column: 1 / -1;
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-3);
  align-items: flex-end;
}

.pagina-crud__filtro-control {
  width: 15rem;
  min-width: 15rem;
  max-width: 20rem;
}

.pagina-crud__formulario {
  padding: var(--space-5) var(--form-row-gap);
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
}

.pagina-crud__grid {
  display: grid;
  gap: var(--space-4);
}

.pagina-crud__stepper-container {
  padding: var(--space-5) var(--form-row-gap) var(--space-4);
}

