.popup-overlay {
  position: fixed;
  inset: 0;
  background: var(--overlay-backdrop);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10000;
  animation: popupFadeIn 150ms ease;
}

.popup-overlay.popup-closing {
  animation: popupFadeOut 200ms ease forwards;
}

@keyframes popupFadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes popupFadeOut {
  from { opacity: 1; }
  to { opacity: 0; }
}

.popup {
  position: relative;
  background: var(--surface-background);
  border-radius: var(--radius-lg);
  width: 90%;
  box-shadow: var(--shadow-xl);
  animation: popupSlideUp 200ms ease;
  display: flex;
  flex-direction: column;
  max-height: 90vh;
  overflow: visible;
}

.popup-closing .popup {
  animation: popupSlideDown 200ms ease forwards;
}

@keyframes popupSlideUp {
  from { transform: translateY(1.25rem) scale(0.95); opacity: 0; }
  to { transform: translateY(0) scale(1); opacity: 1; }
}

@keyframes popupSlideDown {
  from { transform: translateY(0) scale(1); opacity: 1; }
  to { transform: translateY(1.25rem) scale(0.95); opacity: 0; }
}

/* Sizes */
.popup-sm { max-width: 22.5rem; }
.popup-md { max-width: 28.125rem; }
.popup-lg { max-width: 37.5rem; }
.popup-xl { max-width: 71.25rem; }

/* Header */
.popup-header {
  display: grid;
  grid-template-columns: var(--space-10) minmax(0, 1fr) var(--space-10);
  align-items: center;
  gap: var(--space-3);
  padding: var(--space-5);
  border-bottom: 1px solid var(--border-color);
}

.popup-icon {
  grid-column: 1;
  font-size: var(--text-2xl);
  display: flex;
  align-items: center;
  justify-content: center;
  width: var(--space-10);
  height: var(--space-10);
  border-radius: var(--radius-full);
  flex-shrink: 0;
}

.popup-icon-info { background: var(--info-color-light); color: var(--info-color-dark); }
.popup-icon-success { background: var(--success-color-light); color: var(--success-color-dark); }
.popup-icon-warning { background: var(--warning-color-light); color: var(--warning-color-dark); }
.popup-icon-error { background: var(--danger-color-light); color: var(--danger-color-dark); }
.popup-icon-confirm { background: var(--primary-color-lighter); color: var(--primary-color); }

.popup-title {
  grid-column: 2;
  text-align: center;
  margin: 0;
  font-family: var(--font-family-heading);
  font-size: var(--text-lg);
  font-weight: var(--font-weight-emphasis);
  color: var(--text-color);
}

.popup-header:not(:has(.popup-icon)) {
  grid-template-columns: minmax(0, 1fr);
}

.popup-header:not(:has(.popup-icon)) .popup-title {
  grid-column: 1;
}



/* Body */
.popup-body-scroll {
  flex: 1;
  min-height: 0;
  max-height: 65vh;
}

.popup-body {
  padding: var(--space-5);
}

.popup-message {
  margin: 0;
  font-size: var(--text-md);
  color: var(--text-color-secondary);
  line-height: 1.6;
}

/* Footer */
.popup-footer {
  display: flex;
  justify-content: flex-end;
  gap: var(--space-3);
  padding: var(--space-4) var(--space-5);
  border-top: 1px solid var(--border-color);
}

