:host {
  display: block;
  width: 100%;
  min-width: 0;
}

.stepper {
  width: 100%;
  min-width: 0;
}

.stepper__list {
  display: flex;
  align-items: flex-start;
  width: 100%;
  min-width: 0;
  margin: 0;
  padding: var(--space-3) var(--space-1);
  list-style: none;
}

.stepper__item {
  position: relative;
  flex: 1 1 0;
  min-width: 0;
}

.stepper__item:not(:last-child)::after {
  position: absolute;
  z-index: 0;
  top: calc(var(--space-2) + (var(--touch-target-min) / 2));
  right: calc(-50% + var(--space-6));
  left: calc(50% + var(--space-6));
  height: var(--border-width-medium);
  border-radius: var(--radius-sm);
  background: var(--input-border);
  content: '';
  transition: background-color 180ms ease;
}

.stepper__item--completed:not(:last-child)::after {
  background: var(--success-color);
}

.stepper__button {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
  min-width: 0;
  gap: var(--space-2);
  padding: var(--space-2);
  border: 0;
  border-radius: var(--radius-md);
  background: transparent;
  color: var(--text-color-secondary);
  font: inherit;
  text-align: center;
  cursor: pointer;
  transition:
    background-color 180ms ease,
    box-shadow 180ms ease,
    color 180ms ease;
}

.stepper__button:focus-visible {
  outline: none;
}

.stepper__button:focus-visible .stepper__indicator {
  border-color: var(--focus-ring-color);
  box-shadow:
    var(--shadow-xs),
    var(--focus-ring);
}

.stepper__button:disabled {
  cursor: not-allowed;
}

.stepper__indicator {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  width: var(--touch-target-min);
  height: var(--touch-target-min);
  border: 2px solid var(--input-border);
  border-radius: 50%;
  background: var(--surface-background);
  box-shadow: var(--shadow-xs);
  color: var(--text-color-secondary);
  font-size: var(--text-md);
  font-weight: var(--font-weight-title);
  transition:
    background-color 180ms ease,
    border-color 180ms ease,
    color 180ms ease,
    transform 180ms ease;
}

.stepper__item--active .stepper__indicator {
  border-color: var(--button-primary-bg);
  background: var(--button-primary-bg);
  color: var(--button-primary-text);
  transform: scale(1.05);
}

.stepper__item--completed .stepper__indicator {
  border-color: var(--success-color);
  background: var(--success-color);
  color: var(--gray-900);
}

.stepper__item--disabled:not(.stepper__item--active) .stepper__indicator {
  background: var(--surface-sunken);
  box-shadow: none;
  color: var(--text-color-muted);
}

.stepper__content {
  display: flex;
  flex-direction: column;
  align-items: center;
  min-width: 0;
  gap: var(--space-1);
}

.stepper__label {
  color: var(--text-color-secondary);
  font-size: var(--text-md);
  font-weight: var(--font-weight-title);
  overflow-wrap: anywhere;
  transition: color 180ms ease;
}

.stepper__item--active .stepper__label {
  color: var(--text-color);
  font-weight: var(--font-weight-display);
}

.stepper__item--completed .stepper__label {
  color: var(--text-color);
}

.stepper__description {
  color: var(--text-color-muted);
  font-size: var(--text-sm);
  line-height: 1.4;
  overflow-wrap: anywhere;
  transition: color 180ms ease;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (hover: hover) {
  .stepper__button:not(:disabled):hover {
    background: var(--stepper-hover-bg);
    box-shadow:
      inset 0 0 0 var(--border-width-thin) var(--stepper-hover-border),
      var(--shadow-xs);
  }

  .stepper__button:not(:disabled):hover .stepper__indicator {
    border-color: var(--stepper-hover-indicator-border);
    background: var(--stepper-hover-indicator-bg);
    color: var(--stepper-hover-text);
  }

  .stepper__button:not(:disabled):hover .stepper__label {
    color: var(--stepper-hover-text);
  }

  .stepper__button:not(:disabled):hover .stepper__description {
    color: var(--stepper-hover-description);
  }

  .stepper__item--active .stepper__button:not(:disabled):hover .stepper__indicator {
    border-color: var(--stepper-active-hover-indicator-bg);
    background: var(--stepper-active-hover-indicator-bg);
    color: var(--stepper-active-hover-indicator-text);
  }

  .stepper__item--completed .stepper__button:not(:disabled):hover {
    background: var(--stepper-completed-hover-bg);
    box-shadow:
      inset 0 0 0 var(--border-width-thin) var(--stepper-completed-hover-border),
      var(--shadow-xs);
  }

  .stepper__item--completed .stepper__button:not(:disabled):hover .stepper__indicator {
    border-color: var(--stepper-completed-hover-indicator-border);
    background: var(--stepper-completed-hover-indicator-bg);
    color: var(--stepper-completed-hover-indicator-text);
  }

  .stepper__item--completed .stepper__button:not(:disabled):hover .stepper__label {
    color: var(--stepper-completed-hover-text);
  }
}

@media (forced-colors: active) {
  .stepper__button:focus-visible .stepper__indicator {
    outline: 2px solid CanvasText;
    outline-offset: 2px;
  }
}

@media (max-width: 38rem) {
  .stepper__list {
    flex-direction: column;
    align-items: stretch;
    padding-inline: 0;
  }

  .stepper__item {
    width: 100%;
  }

  .stepper__item:not(:last-child)::after {
    top: calc(var(--space-2) + var(--space-6));
    right: auto;
    bottom: calc(-1 * var(--space-2));
    left: calc(var(--space-3) + (var(--space-6) / 2) - (var(--border-width-medium) / 2));
    width: var(--border-width-medium);
    height: auto;
  }

  .stepper__button {
    flex-direction: row;
    align-items: flex-start;
    gap: var(--space-3);
    padding: var(--space-2) var(--space-3);
    text-align: left;
  }

  .stepper__indicator {
    width: var(--space-6);
    height: var(--space-6);
    font-size: var(--text-sm);
  }

  .stepper__content {
    align-items: flex-start;
    padding-top: var(--space-1);
  }
}

@media (prefers-reduced-motion: reduce) {
  .stepper__item::after,
  .stepper__button,
  .stepper__indicator,
  .stepper__label,
  .stepper__description {
    transition: none;
  }

  .stepper__item--active .stepper__indicator {
    transform: none;
  }
}
/* Vertical class support */
.stepper--vertical .stepper__list { flex-direction: column; align-items: stretch; padding-inline: 0; }
.stepper--vertical .stepper__item { width: 100%; }
.stepper--vertical .stepper__item:not(:last-child)::after { top: calc(var(--space-2) + var(--space-6)); right: auto; bottom: calc(-1 * var(--space-2)); left: calc(var(--space-3) + (var(--space-6) / 2) - (var(--border-width-medium) / 2)); width: var(--border-width-medium); height: auto; }
.stepper--vertical .stepper__button { flex-direction: row; align-items: flex-start; gap: var(--space-3); padding: var(--space-2) var(--space-3); text-align: left; }
.stepper--vertical .stepper__indicator { width: var(--space-6); height: var(--space-6); font-size: var(--text-sm); }
.stepper--vertical .stepper__content { align-items: flex-start; padding-top: var(--space-1); }

