th[app-table-header-cell] {
  /* Estilos base heredados de table-head.component.ts */
}

th[app-table-header-cell].sortable-cell {
  cursor: pointer;
  user-select: none;
  transition: filter 0.2s ease, background-color 0.2s ease, color 0.2s ease;
  --hover-brightness: 0.96; /* Oscurece 4% en modo claro */
}

[data-theme="dark"] th[app-table-header-cell].sortable-cell,
.theme-dark th[app-table-header-cell].sortable-cell,
html.dark th[app-table-header-cell].sortable-cell {
  --hover-brightness: 1.2; /* Ilumina 20% en modo oscuro */
}

th[app-table-header-cell].sortable-cell:hover {
  filter: brightness(var(--hover-brightness));
}

/*
EL FOCO SE VE, Y ESO ES LA MITAD DEL ARREGLO.

La celda ya se alcanza con el tabulador, pero un foco que no se dibuja deja a
quien navega con teclado sin saber donde esta: puede ordenar, y no sabe que
columna va a ordenar. Se usa `:focus-visible` y no `:focus` para no pintar el
anillo cuando se llega con el raton, que es ruido.

El `outline-offset` negativo mete el anillo DENTRO de la celda: en una cabecera
pegada al borde de la tabla, un anillo por fuera queda recortado por el
desbordamiento del contenedor y se pierde justo en la primera y la ultima
columna, que son las que mas se ordenan.
*/
th[app-table-header-cell].sortable-cell:focus-visible {
  outline: 2px solid var(--focus-ring-color);
  outline-offset: -2px;
  filter: brightness(var(--hover-brightness));
}

.th-content {
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

/* Los respaldos literales que habia aqui nunca llegaban a usarse -ambos tokens
   estan definidos en los tres temas- y ademas mentian: #3b82f6 es un azul que no
   pertenece a la marca. Se quitan para que el color venga de un unico sitio. */
.sort-indicator {
  font-size: 0.85em;
  opacity: 0.3;
  transition: opacity 0.2s ease, transform 0.2s ease, color 0.2s ease;
  color: var(--text-color-muted);
}

.sort-indicator.active {
  opacity: 1;
  color: var(--primary-color);
}

th[app-table-header-cell].sortable-cell:hover .sort-indicator {
  opacity: 0.8;
  transform: scale(1.1);
}

th[app-table-header-cell].sortable-cell:hover .sort-indicator.active {
  opacity: 1;
}

