.tabs-container {
  width: 100%;
}

.tabs-header {
  display: flex;
  position: relative;
  border-bottom: 1px solid var(--border-color);
  margin-bottom: 0;
  gap: var(--space-2);
}

.tab-button {
  flex: 1;
  padding: var(--space-4) var(--space-5);

  /* Base Style (Inactive) */
  background: var(--surface-ground);
  border: 1px solid var(--border-color-strong);
  border-bottom: none;

  margin-bottom: -1px;
  font-size: var(--text-md);
  font-weight: var(--font-weight-body);
  color: var(--text-color-secondary);
  cursor: pointer;
  transition: all 200ms ease;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  border-radius: var(--radius-md) var(--radius-md) 0 0;
}

/* Hover state */
.tab-button:not(.disabled):not(.active):hover {
  color: var(--primary-color);
  background: var(--hover-background-subtle);
  border-color: var(--primary-color);
}

/* Pressed state effects */
.tab-button:active {
  /* El color de la sombra sale de --shadow-color, que es el mismo canal del que
     derivan --shadow-xs..xl; el negro fijo mantenia la sombra clara del tema claro
     cuando el resto de la elevacion ya se habia oscurecido. */
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--primary-color), transparent 30%),
              0 1px var(--space-1) hsl(var(--shadow-color) / 0.2);
}

.tab-button.active {
  color: var(--text-color);
  font-weight: var(--font-weight-emphasis);
  background: var(--surface-background);

  /* Active: Thick Top Border + Sides matching content border */
  border-top: var(--space-1) solid var(--primary-color);
  border-left: 1px solid var(--border-color);
  border-right: 1px solid var(--border-color);
  border-bottom: 1px solid var(--surface-background);
}

.tab-button.disabled {
  cursor: not-allowed;
  background: var(--surface-section);
  border: 1px solid var(--border-color);
  border-bottom: none;
  color: var(--text-color-muted);
}

.tab-icon {
  font-size: var(--text-lg);
}

.tabs-content {
  padding: var(--space-5);
  background: var(--surface-background);
  border-radius: 0 0 var(--radius-md) var(--radius-md);
  border: 1px solid var(--border-color);
  border-top: none;
}

/*
 * Dark mode se maneja automáticamente via tokens semánticos.
 * --surface-ground, --surface-background, --border-color, --primary-color
 * ya tienen valores apropiados para temas oscuros.
 */

/* RESPONSIVE: Compact scrollable tabs on mobile */
@media (max-width: 48rem) {
  .tabs-header {
    overflow-x: auto;
    overflow-y: hidden;
    -webkit-overflow-scrolling: touch;
    scrollbar-width: thin;
    gap: var(--space-1);
    padding-bottom: 0;
  }

  .tabs-header::-webkit-scrollbar {
    height: var(--space-1);
  }

  .tabs-header::-webkit-scrollbar-thumb {
    background: var(--border-color);
    border-radius: var(--radius-sm);
  }

  .tab-button {
    flex: 0 0 auto;
    min-width: max-content;
    padding: var(--space-2) var(--space-3);
    font-size: var(--text-sm);
    white-space: nowrap;
  }

  .tab-icon {
    font-size: var(--text-md);
  }

  .tabs-content {
    padding: var(--space-3);
  }
}

