:host {
  display: inline-block;
  position: relative;
}

.user-menu {
  position: relative;
}

/* === Trigger Button === */
.user-menu__trigger {
  display: flex;
  align-items: center;
  justify-content: center;
  width: var(--control-height);
  height: var(--control-height);
  padding: 0;
  background: transparent;
  border: none;
  border-radius: 50%;
  cursor: pointer;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.user-menu__trigger:hover {
  transform: scale(1.05);
}

/* === Dropdown === */
.user-menu__dropdown {
  position: absolute;
  top: calc(100% + var(--space-2));
  right: 0;
  /* min() evita que el dropdown desborde el viewport en pantallas pequeñas */
  min-width: min(13.75rem, calc(100vw - var(--space-6)));
  max-width: calc(100vw - var(--space-4));
  background: var(--surface-background);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  /*
    Menu de usuario: flota sobre toda la pagina, y por eso sube al peldano `lg`
    de la escala. `--shadow-dropdown` pesa alfa 0,1 en claro y en los temas
    oscuros no lleva el anillo de 1px que separa una superficie del fondo casi
    negro, asi que el panel se fundia con lo que tenia debajo.
  */
  box-shadow: var(--shadow-lg);
  opacity: 0;
  visibility: hidden;
  transform: translateY(calc(-1 * var(--space-2))) translateZ(0);
  transition: all 200ms ease;
  z-index: 1000;
  overflow: hidden;
  isolation: isolate;
}

.user-menu.open .user-menu__dropdown {
  opacity: 1;
  visibility: visible;
  transform: translateY(0) translateZ(0);
}

/* === Header === */
.user-menu__header {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  padding: var(--space-4);
}

.user-menu__info {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
  min-width: 0;
}

.user-menu__name {
  font-size: var(--text-sm);
  font-weight: var(--font-weight-emphasis);
  color: var(--text-color);
  white-space: nowrap;
  overflow: hidden;
  isolation: isolate;
  text-overflow: ellipsis;
}

.user-menu__email {
  font-size: var(--text-xs);
  color: var(--text-color-secondary);
  white-space: nowrap;
  overflow: hidden;
  isolation: isolate;
  text-overflow: ellipsis;
}

.user-menu__role {
  color: var(--primary-color);
  font-size: var(--text-xs);
  font-weight: var(--font-weight-emphasis);
  text-transform: uppercase;
}

/* === Divider === */
.user-menu__divider {
  height: 1px;
  background: var(--border-color);
  margin: 0;
}

/* === Menu Items === */
.user-menu__item {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  width: 100%;
  padding: var(--space-3) var(--space-4);
  background: transparent;
  border: none;
  color: var(--text-color);
  font-size: var(--text-sm);
  cursor: pointer;
  transition: background 0.15s ease;
  text-align: left;
}

.user-menu__item:hover {
  background: var(--surface-hover);
}

.user-menu__item--danger {
  color: var(--danger-color-text);
}

.user-menu__item--danger:hover {
  background: var(--danger-color-lighter);
}

.user-menu__item-icon {
  font-size: var(--text-md);
  width: var(--space-5);
  text-align: center;
}

.user-menu__item-label {
  flex: 1;
  text-transform: uppercase;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/*
 * Dark mode se maneja automáticamente via tokens semánticos.
 * --surface-background, --border-color, --shadow-lg, --surface-hover
 * ya tienen valores apropiados para temas oscuros.
 */


.user-menu__trigger--extended {
  width: auto;
  padding: var(--space-1) var(--space-2);
  border-radius: var(--radius-md);
  gap: var(--space-3);
  text-align: left;
}
.user-menu__trigger--extended:hover {
  background: var(--surface-hover);
  transform: none;
}
.user-menu__trigger-info {
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.user-menu__trigger-name {
  font-size: var(--text-sm);
  font-weight: bold;
  color: var(--text-color);
  line-height: 1.2;
  text-transform: uppercase;
}
.user-menu__trigger-role {
  font-size: var(--text-xs);
  color: var(--text-color-secondary);
  line-height: 1.2;
}
.user-menu__trigger-chevron {
  font-size: var(--icon-sm);
  color: var(--text-color-secondary);
  margin-left: var(--space-1);
}

.user-menu__item:last-child { border-bottom-left-radius: calc(var(--radius-lg) - var(--border-width-thin)); border-bottom-right-radius: calc(var(--radius-lg) - var(--border-width-thin)); }

