      "import('../blueprints/dialogs-page/dialogs-page.component').then(m => m.DialogsPageComponent)",
  },

  // ===================================================
  // Rutas de ERROR
  // ===================================================
  {
    path: '403',
    loadComponent: () =>
      "import('../blueprints/error-pages/error-pages.component').then(m => m.ErrorPagesComponent)",
    data: { code: 403 },
  },
  {
    path: '404',
    loadComponent: () =>
      "import('../blueprints/error-pages/error-pages.component').then(m => m.ErrorPagesComponent)",
    data: { code: 404 },
  },
  {
    path: '500',
    loadComponent: () =>
      "import('../blueprints/error-pages/error-pages.component').then(m => m.ErrorPagesComponent)",
    data: { code: 500 },
  },

  // Catch-all → 404 (lazy, coherente con las demás rutas de error)
  {
    path: '**',
    loadComponent: () =>
      "import('../blueprints/error-pages/error-pages.component').then(m => m.ErrorPagesComponent)",
    data: { code: 404 },
  },
]

